function RTTimer({ item, C }) {
  const remHrs = item.remaining;
  const pct = Math.max(0, Math.min(100, (item.ageHrs / item.limit) * 100));
  const urgent = remHrs < 1;
  return (
    <div style={{
      background: C.bg, padding: "10px 12px", borderRadius: 8,
      border: `1px solid ${urgent ? C.accent : C.line + "22"}`,
      display: "flex", alignItems: "center", gap: 12,
    }}>
      <div style={{
        width: 32, height: 32, borderRadius: "50%",
        background: `conic-gradient(${urgent ? C.accent : C.ink} ${pct * 3.6}deg, ${C.line}22 0)`,
        display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      }}>
        <div style={{ width: 24, height: 24, borderRadius: "50%", background: C.bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Milk size={12} color={urgent ? C.accent : C.ink} />
        </div>
      </div>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 13, fontWeight: 500 }}>{item.oz} oz · room temp</div>
        <div style={{ fontSize: 11, color: urgent ? C.accent : C.muted, fontFamily: "'JetBrains Mono', monospace", marginTop: 1 }}>
          {remHrs > 0 ? `${fmtHours(remHrs)} until expiration` : "expired"}
        </div>
      </div>
    </div>
  );
}

function TimelineEvent({ ev, C, now }) {
  // Cluster mode: rendered as a single condensed row showing combined oz + range
  if (ev._isCluster) {
    const startTs = new Date(ev.ts);
    const endTs = new Date(ev.endTs);
    // Build a description: "X oz from N bottles" plus breastfeed minutes if any
    const parts = [];
    if (ev.totalOz > 0) {
      const bottleCount = ev.events.filter(e => e.type === "feed").length;
      parts.push(`${ev.totalOz.toFixed(1)}oz · ${bottleCount} bottle${bottleCount === 1 ? "" : "s"}`);
    }
    if (ev.totalBfMin > 0) {
      parts.push(`${ev.totalBfMin}m breastfeed`);
    }
    const sourcesStr = ev.sources.filter(s => s !== "Breastfeed").join(" + ");
    return (
      <div style={{ position: "relative", padding: "7px 0", paddingLeft: 22 }}>
        <div style={{
          position: "absolute", left: -8, top: 9,
          width: 12, height: 12, borderRadius: "50%",
          background: C.accent, color: "#fff",
          border: `1.5px solid ${C.paper}`,
          boxShadow: `0 0 0 1px ${C.accent}55`,
          display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          <Milk size={10} />
        </div>
        <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.muted, minWidth: 52 }}>
            {fmtTimeShort(startTs)}
          </span>
          <span style={{ fontSize: 13, flex: 1, color: C.ink }}>
            <span style={{
              display: "inline-block", width: 3, height: 12,
              background: C.accent, borderRadius: 2, marginRight: 8, verticalAlign: "middle",
            }} />
            <strong>Feeding session</strong> · {parts.join(" + ")}
            {sourcesStr && <span style={{ color: C.muted, fontSize: 11 }}> · {sourcesStr}</span>}
            <span style={{ display: "block", fontSize: 10, color: C.muted, marginLeft: 11, marginTop: 2, fontStyle: "italic" }}>
              {fmtTimeShort(startTs)}–{fmtTimeShort(endTs)} · {ev.events.length} entries grouped
            </span>
          </span>
          <span style={{ fontSize: 10, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
            {fmtElapsed(minutesAgo(ev.ts))}
          </span>
        </div>
      </div>
    );
  }

  const icon = {
    feed: <Milk size={10} />,
    breastfeed: <Heart size={10} />,
    pump: <Droplet size={10} />,
    diaper: <Baby size={10} />,
    sleep_down: <Moon size={10} />,
    sleep_up: <Sun size={10} />,
    bath: <Bath size={10} />,
    skincare: <Sparkles size={10} />,
    activity: <Star size={10} />,
    takeover: <ArrowRightLeft size={10} />,
  }[ev.type];

  const activityInfo = ev.type === "activity" ? ACTIVITIES.find(a => a.v === ev.activityType) : null;

  // Color by event type
  const typeColor = {
    feed: C.accent,           // coral — bottle feeds
    breastfeed: C.mommy,      // rose — breastfeeds
    pump: C.mommy,            // rose — pumping
    diaper: C.daddy,          // sage
    sleep_down: "#7C5C84",    // warm plum (night/dusk in warm-palette terms)
    sleep_up: C.gold,      // gold (waking)
    bath: "#7B9B6E",          // sage green (water/clean in warm-palette terms)
    skincare: "#9C6BB0",      // soft purple
    activity: activityInfo?.color || C.gold,
    takeover: C.accent,
  }[ev.type] || C.ink;

  const label = {
    feed: `Feed${ev.oz ? ` · ${ev.oz}oz` : ""}${ev.source ? ` ${ev.source}` : ""}${feedBottleSuffix(ev)}`,
    breastfeed: `Breastfed${ev.totalDurationMin ? ` · ${ev.totalDurationMin}m` : ""}${(ev.leftMin || ev.rightMin) ? ` (L${ev.leftMin || 0}/R${ev.rightMin || 0})` : ""}`,
    pump: `${ev.pumpType === "power" ? "⚡ Power pump" : "Pump"}${ev.oz ? ` · ${ev.oz}oz` : ""}${ev.durationMin ? ` · ${ev.durationMin}m` : ""}${ev.bottleLabel ? ` · Bottle ${ev.bottleLabel}` : ""}`,
    diaper: `Diaper${ev.notes ? ` · ${ev.notes}` : ""}${ev.pooSize === "lots" ? " 💩💩💩" : ev.pooSize === "tiny" ? " · tiny" : ""}`,
    sleep_down: "Down for sleep",
    sleep_up: "Awake",
    bath: `${BATH_TYPES[ev.bathType]?.icon || "🛁"} ${BATH_TYPES[ev.bathType]?.label || "Bath"}`,
    bath_skipped: "🛁 No bath tonight",
    skincare: `${ev.routine === "AM" ? "☀️ AM" : "🌙 PM"} routine done`,
    activity: activityInfo ? `${activityInfo.emoji} ${activityInfo.l}${ev.durationMin ? ` · ${ev.durationMin}m` : ""}` : `Activity${ev.durationMin ? ` · ${ev.durationMin}m` : ""}`,
    takeover: `Takeover · ${ev.coveringParent} covered ${ev.originalParent}${ev.durationMin ? ` for ${fmtBalance(ev.durationMin)}` : ""}`,
  }[ev.type] || ev.type;

  return (
    <div style={{ position: "relative", padding: "7px 0", paddingLeft: 22 }}>
      <div style={{
        position: "absolute", left: -8, top: 9,
        width: 12, height: 12, borderRadius: "50%",
        background: typeColor, color: "#fff",
        border: `1.5px solid ${C.paper}`,
        boxShadow: `0 0 0 1px ${typeColor}55`,
        display: "flex", alignItems: "center", justifyContent: "center",
      }}>
        {icon}
      </div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.muted, minWidth: 52 }}>
          {fmtTimeShort(new Date(ev.ts))}
        </span>
        <span style={{ fontSize: 13, flex: 1, color: C.ink }}>
          <span style={{
            display: "inline-block", width: 3, height: 12,
            background: typeColor, borderRadius: 2, marginRight: 8, verticalAlign: "middle",
          }} />
          {label}
          {/* v05.05bt308 — Per chat: 'option to show who logged what
              event.' Small attribution pill after label. Color-coded by
              logger: M=mauve, D=daddy blue, C=sage. Hidden if no
              ownerName recorded (legacy events). */}
          {ev.ownerName && (
            <span
              title={`Logged by ${ev.ownerName}`}
              style={{
                marginLeft: 8,
                display: "inline-block",
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 8.5, fontWeight: 800,
                letterSpacing: "0.06em",
                padding: "1px 5px", borderRadius: 3,
                verticalAlign: "middle",
                background:
                  ev.ownerName === "Mommy" ? `${C.mommy}1c`
                  : ev.ownerName === "Daddy" ? `${C.daddy}1c`
                  : "rgba(123, 155, 110, 0.18)",
                color:
                  ev.ownerName === "Mommy" ? C.mommy
                  : ev.ownerName === "Daddy" ? C.daddy
                  : "#5C7D55",
              }}>
              {ev.ownerName === "Mommy" ? "M"
                : ev.ownerName === "Daddy" ? "D"
                : ev.ownerName === "Caregiver" ? "C"
                : ev.ownerName.slice(0, 1).toUpperCase()}
            </span>
          )}
        </span>
        <span style={{ fontSize: 10, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
          {fmtElapsed(minutesAgo(ev.ts))}
        </span>
      </div>
    </div>
  );
}

function WeatherCard({ C, weather, uvNow, tempNow, walkWindows }) {
  if (!weather) {
    return <div style={{ color: C.muted, fontSize: 13, padding: "12px 0", fontStyle: "italic" }}>fetching weather…</div>;
  }
  const uvLabel = uvNow == null ? "—" : uvNow < 3 ? "low" : uvNow < 6 ? "moderate" : uvNow < 8 ? "high" : "very high";
  const uvColor = uvNow == null ? C.muted : uvNow < 3 ? "#5C8E5C" : uvNow < 6 ? C.gold : C.accent;

  return (
    <div style={{ background: C.paper, borderRadius: 12, padding: 16, border: `1px solid ${C.line}15` }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <div>
          <div style={{ fontSize: 10, color: C.muted, letterSpacing: "0.2em", textTransform: "uppercase" }}>OUTSIDE NOW</div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 12, marginTop: 2 }}>
            <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 28, fontWeight: 500 }}>
              {tempNow != null ? `${Math.round(tempNow)}°F` : "—"}
            </div>
            <div style={{ fontSize: 12, color: uvColor, fontWeight: 500 }}>
              UV {uvNow != null ? uvNow.toFixed(1) : "—"} · {uvLabel}
            </div>
          </div>
          {uvNow != null && uvNow >= 6 && (
            <div style={{ fontSize: 11, color: C.accent, marginTop: 4, fontWeight: 500 }}>
              ☀️ Apply Aveeno SPF before going out
            </div>
          )}
        </div>
        <Sun size={28} color={uvColor} style={{ opacity: 0.7 }} />
      </div>

      <div style={{ fontSize: 10, letterSpacing: "0.2em", textTransform: "uppercase", color: C.muted, marginBottom: 8 }}>
        Good walk windows
      </div>
      {walkWindows && walkWindows.length > 0 ? (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(72px, 1fr))", gap: 6 }}>
          {walkWindows.map((w, i) => (
            <div key={i} style={{ background: C.bg, borderRadius: 8, padding: "7px 8px", border: `1px solid ${C.line}15` }}>
              <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, fontWeight: 600 }}>
                {fmtTimeShort(w.time)}
              </div>
              <div style={{ fontSize: 10, color: C.muted, marginTop: 1 }}>
                {Math.round(w.temp)}° · UV {w.uv.toFixed(1)}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic" }}>No safe windows in next 24h</div>
      )}
    </div>
  );
}

function ShiftStrip({ C, shifts, now }) {
  // 24 hourly cells starting from current hour, showing who's on
  const startMins = now.getHours() * 60 + now.getMinutes();
  const cells = [];
  for (let i = 0; i < 24; i++) {
    const cellHour = (now.getHours() + i) % 24;
    const cellMins = cellHour * 60 + 30; // mid-hour
    let parent = "Mommy";
    for (const p of ["Mommy", "Daddy"]) {
      for (const s of shifts[p]) {
        const a = toMin(s.start);
        const b = toMin(s.end);
        const inShift = a < b ? cellMins >= a && cellMins < b : cellMins >= a || cellMins < b;
        if (inShift) { parent = p; break; }
      }
    }
    cells.push({ hour: cellHour, parent });
  }

  return (
    <div style={{ background: C.paper, borderRadius: 12, padding: 14, border: `1px solid ${C.line}15` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontSize: 12, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
          next 24 hours →
        </div>
        <div style={{ display: "flex", gap: 12, fontSize: 11, color: C.muted }}>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ width: 10, height: 10, background: C.mommy, borderRadius: 2 }} /> Mommy
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ width: 10, height: 10, background: C.daddy, borderRadius: 2 }} /> Daddy
          </span>
        </div>
      </div>

      {/* Hour blocks */}
      <div style={{ display: "flex", height: 32, borderRadius: 6, overflow: "hidden", border: `1px solid ${C.line}11`, marginBottom: 4 }}>
        {cells.map((c, i) => (
          <div key={i} style={{
            flex: 1,
            background: c.parent === "Mommy" ? C.mommy : C.daddy,
            opacity: 0.85,
            position: "relative",
            borderRight: i < 23 ? `1px solid ${C.bg}55` : "none",
          }}>
            {i === 0 && (
              <div style={{
                position: "absolute", top: -4, left: 0, bottom: -4, width: 2,
                background: C.accent, boxShadow: `0 0 8px ${C.accent}`,
              }} />
            )}
          </div>
        ))}
      </div>

      {/* Hour labels */}
      <div style={{ display: "flex", fontSize: 9, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
        {cells.map((c, i) => (
          <div key={i} style={{ flex: 1, textAlign: "center" }}>
            {i % 3 === 0 ? (
              c.hour === 0 ? "12a" :
              c.hour === 12 ? "12p" :
              c.hour < 12 ? `${c.hour}a` : `${c.hour - 12}p`
            ) : ""}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 10, fontSize: 11, color: C.muted, fontStyle: "italic" }}>
        ↑ each block = 1 hour. Orange line marks <strong style={{ color: C.accent }}>now</strong>.
      </div>
    </div>
  );
}

function LogView({ C, events, removeEvent, updateEvent, now, onOpenBathLog }) {
  const [editing, setEditing] = useState(null); // event being edited
  // v05.05bt25 — show bath_skipped events in journal (even though silent)
  // so users can see + undo their "no bath tonight" decision. Other silent
  // events (wake_confirmed) stay hidden.
  const visibleEvents = events.filter(e => !e.silent || e.type === "bath_skipped");
  const sorted = [...visibleEvents].sort((a, b) => new Date(b.ts) - new Date(a.ts));
  const grouped = {};
  for (const e of sorted) {
    const key = new Date(e.ts).toDateString();
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(e);
  }
  return (
    <div style={{ marginTop: 14 }}>
      <Section C={C} title={`Full journal · ${visibleEvents.length} entries`}>
        {Object.keys(grouped).length === 0 ? (
          <div style={{ color: C.muted, fontStyle: "italic", padding: 20, fontSize: 14, textAlign: "center" }}>
            Nothing logged yet.
          </div>
        ) : Object.entries(grouped).map(([day, evs]) => {
          const dayDate = new Date(day);
          const isToday = dayDate.toDateString() === now.toDateString();
          const isYesterday = dayDate.toDateString() === new Date(now.getTime() - 86400000).toDateString();
          const dayLabel = isToday ? "Today"
            : isYesterday ? "Yesterday"
            : dayDate.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
          const safeKey = day.replace(/[^a-z0-9]/gi, '');

          // Today renders un-collapsed; older days wrap in <details> so the
          // journal isn't an info wall on first load.
          const dayHeader = (
            <div style={{
              display: "flex", alignItems: "baseline", gap: 8,
              fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic",
              fontSize: 18, color: C.muted,
            }}>
              {!isToday && (
                <ChevronRight size={12} className={`journal-chev-${safeKey}`} style={{ transition: "transform 0.2s", flexShrink: 0, alignSelf: "center" }} />
              )}
              <span>{dayLabel}</span>
              <span style={{ fontStyle: "normal", fontSize: 11, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
                · {evs.length} events
              </span>
            </div>
          );

          const dayBody = (
            <div style={{ background: C.paper, borderRadius: 12, overflow: "hidden", border: `1px solid ${C.line}15`, marginTop: 8 }}>
              {evs.map((e, i) => {
                // v05.05bt25 — bath_skipped rows are special: tapping them
                // opens the bath logger (so the user can change their mind).
                // The Option-2 logic in addEvent will auto-remove this skip
                // event when the bath is logged.
                const isSkippedBath = e.type === "bath_skipped";
                const rowOnClick = isSkippedBath
                  ? () => onOpenBathLog && onOpenBathLog()
                  : () => setEditing(e);
                return (
                <div key={e.id} style={{
                  display: "flex", alignItems: "center", gap: 10,
                  borderTop: i === 0 ? "none" : `1px solid ${C.line}10`,
                  opacity: isSkippedBath ? 0.7 : 1,
                  fontStyle: isSkippedBath ? "italic" : "normal",
                }}>
                  <button
                    onClick={rowOnClick}
                    style={{
                      flex: 1, display: "flex", alignItems: "center", gap: 10,
                      padding: "10px 14px",
                      background: "transparent", border: "none", cursor: "pointer",
                      fontFamily: "inherit", textAlign: "left",
                    }}>
                    <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.muted, minWidth: 56 }}>
                      {fmtTimeShort(new Date(e.ts))}
                    </span>
                    <span style={{ flex: 1, fontSize: 13, color: C.ink }}>
                      {e.type === "feed" && (() => {
                        // v05.05bt68: leading ⚠ removed — feedBottleSuffix
                        // now appends a more specific reconcile message at
                        // the end ("⚠ no bottle picked" / "⚠ X oz unallocated").
                        const base = `Feed${e.oz ? ` · ${e.oz}oz` : ""}${e.source ? ` ${e.source}` : ""}`;
                        return `${base}${feedBottleSuffix(e)}`;
                      })()}
                      {e.type === "breastfeed" && `Breastfed${e.totalDurationMin ? ` · ${e.totalDurationMin}m` : ""}${(e.leftMin || e.rightMin) ? ` (L${e.leftMin || 0}/R${e.rightMin || 0})` : ""}`}
                      {e.type === "pump" && (() => {
                        const isPower = e.pumpType === "power";
                        const prefix = isPower ? "⚡ Power pump" : "Pump";
                        const labelStr = e.bottleLabel ? ` · Bottle ${e.bottleLabel}` : "";
                        const base = `${prefix}${e.oz ? ` · ${e.oz}oz` : ""}${e.durationMin ? ` · ${e.durationMin}m` : ""}${labelStr}`;
                        // Append start–end range if we have duration. mode
                        // tells us whether ts is the start or end of the
                        // session; we compute the missing edge from durationMin.
                        if (!e.durationMin) return base;
                        const ts = new Date(e.ts);
                        if (isNaN(ts.getTime())) return base;
                        const isEnd = e.mode === "end";
                        const start = isEnd ? new Date(ts.getTime() - e.durationMin * 60000) : ts;
                        const end = isEnd ? ts : new Date(ts.getTime() + e.durationMin * 60000);
                        return `${base} (${fmtTimeShort(start)}–${fmtTimeShort(end)})`;
                      })()}
                      {e.type === "diaper" && `Diaper · ${diaperLabel(e.notes)}${e.pooSize === "lots" ? " 💩💩💩" : e.pooSize === "tiny" ? " · tiny" : ""}`}
                      {e.type === "sleep_down" && `Down for sleep${e.estimated ? " (est.)" : ""}`}
                      {e.type === "sleep_up" && "Awake"}
                      {/* v05.05bt112 — journal line now spells out "Bath" so
                          the entry reads cleanly, and surfaces the book toggle
                          (📖 + book) when withBook is true. Previously the
                          journal showed only the bath subtype label and
                          dropped the book indicator entirely. */}
                      {e.type === "bath" && (() => {
                        const info = BATH_TYPES[e.bathType];
                        const bookTag = e.withBook ? ` · 📖 book` : "";
                        return `${info?.icon || "🛁"} Bath · ${info?.label || "bath"}${bookTag}`;
                      })()}
                      {e.type === "bath_skipped" && "🛁 No bath tonight"}
                      {e.type === "skincare" && `${e.routine === "AM" ? "☀️" : "🌙"} ${e.routine} routine`}
                      {e.type === "activity" && (() => {
                        const a = ACTIVITIES.find(x => x.v === e.activityType);
                        return `${a?.emoji || "⭐"} ${a?.l || "Activity"}${e.durationMin ? ` · ${e.durationMin}m` : ""}`;
                      })()}
                      {e.type === "takeover" && `↔ ${e.coveringParent} covered ${e.originalParent}${e.durationMin ? ` · ${e.durationMin}m` : ""}`}
                    </span>
                    {/* v05.05bt36: prediction-accuracy chip.
                        Renders inline only when the event captured a
                        prediction snapshot at log time (feed / breastfeed /
                        sleep_down with sufficient prior data). Three tones:
                          hit  = within 10m → sage green ("✓ on time" or "+8m late")
                          near = 10–25m off → gold
                          miss = >25m off  → muted (still informative but visually quiet) */}
                    {e._predictionDeltaMin != null && (() => {
                      const fmt = formatPredictionDelta(e._predictionDeltaMin);
                      if (!fmt) return null;
                      const toneColor = fmt.tone === "hit" ? "#5C8E5C"
                        : fmt.tone === "near" ? C.gold
                        : C.muted;
                      const toneBg = fmt.tone === "hit" ? "#5C8E5C18"
                        : fmt.tone === "near" ? `${C.gold}18`
                        : `${C.muted}10`;
                      return (
                        <span
                          title={e._predictionAt
                            ? `Predicted: ${fmtTimeShort(new Date(e._predictionAt))}`
                            : "Prediction snapshot"}
                          style={{
                            fontSize: 9, fontWeight: 600,
                            fontFamily: "'JetBrains Mono', monospace",
                            color: toneColor, background: toneBg,
                            padding: "2px 6px", borderRadius: 6,
                            letterSpacing: "0.02em",
                            whiteSpace: "nowrap", flexShrink: 0,
                            marginRight: 2,
                          }}>
                          {fmt.label}
                        </span>
                      );
                    })()}
                    {isSkippedBath ? (
                      <span style={{
                        fontSize: 10, color: C.accent,
                        fontFamily: "'JetBrains Mono', monospace",
                        fontStyle: "normal", fontWeight: 600,
                        whiteSpace: "nowrap",
                      }}>
                        ↻ undo · log bath
                      </span>
                    ) : (
                      <Edit3 size={11} color={C.muted} style={{ opacity: 0.4 }} />
                    )}
                  </button>
                  <button onClick={(ev) => { ev.stopPropagation(); removeEvent(e.id); }} style={{
                    background: "transparent", border: "none", color: C.muted, cursor: "pointer",
                    padding: "10px 14px 10px 4px", opacity: 0.5,
                  }}>
                    <Trash2 size={13} />
                  </button>
                </div>
                );
              })}
            </div>
          );

          if (isToday) {
            return (
              <div key={day} style={{ marginBottom: 20 }}>
                {dayHeader}
                {dayBody}
              </div>
            );
          }
          return (
            <details key={day} style={{ marginBottom: 14 }}>
              <summary style={{ cursor: "pointer", listStyle: "none" }}>
                {dayHeader}
              </summary>
              <style>{`details[open] .journal-chev-${safeKey} { transform: rotate(90deg); }`}</style>
              {dayBody}
            </details>
          );
        })}
      </Section>

      {editing && (
        <EditEventModal
          C={C}
          event={editing}
          onClose={() => setEditing(null)}
          onSave={(updated) => {
            // v05.05bt91: when a feed event gets a bottleLabel added during
            // reconciliation edit, drain the matching bottle(s) from
            // inventory. Trigger conditions (all must hold):
            //   • feed event
            //   • label added during this edit (event had none before)
            //   • inventoryReconcileNeeded was true on the original
            //   • event has positive oz
            // Behavior: match by label case-insensitively, drain oldest
            // matching bottles first up to feed oz. If fully drained, clear
            // reconcile flag. If partial, keep flag with updated
            // unallocatedOz. If no match, no drain — label stored as
            // notation only.
            if (updated.type === "feed"
                && updated.bottleLabel
                && !editing.bottleLabel
                && editing.inventoryReconcileNeeded
                && Number(updated.oz) > 0) {
              const target = updated.bottleLabel.toUpperCase();
              const sorted = [...inventory].sort(
                (a, b) => new Date(a.pumpedAt) - new Date(b.pumpedAt)
              );
              let remaining = Number(updated.oz);
              const newInventory = [];
              let drained = 0;
              for (const b of sorted) {
                if (remaining > 0 && (b.bottleLabel || "").toUpperCase() === target) {
                  const take = Math.min(b.oz, remaining);
                  remaining -= take;
                  drained += take;
                  const newOz = b.oz - take;
                  if (newOz > 0.05) newInventory.push({ ...b, oz: newOz });
                  // else: bottle emptied, drop
                } else {
                  newInventory.push(b);
                }
              }
              if (drained > 0) {
                setInventory(newInventory);
                console.log(`[reconcile] drained ${drained.toFixed(1)}oz from bottle(s) labeled '${target}' for feed ${editing.id}`);
              }
              if (remaining <= 0.05) {
                // Fully reconciled
                updated.inventoryReconcileNeeded = false;
                updated.reconcileReason = null;
                updated.unallocatedOz = 0;
              } else if (drained > 0) {
                // Partial — keep flag, update shortfall amount
                updated.unallocatedOz = Math.round(remaining * 10) / 10;
                updated.reconcileReason = "shortfall";
              }
              // else: no match found, label stored without drain
            }
            updateEvent(editing.id, updated);
            setEditing(null);
          }}
          onDelete={() => {
            removeEvent(editing.id);
            setEditing(null);
          }}
        />
      )}
    </div>
  );
}

function EditEventModal({ C, event, onClose, onSave, onDelete }) {
  // Local edit state — start with the existing values
  const [tsLocal, setTsLocal] = useState(() => safeDatetimeLocal(event.ts));
  const [oz, setOz] = useState(event.oz || 0);
  const [source, setSource] = useState(event.source || "BM");
  const [durationMin, setDurationMin] = useState(event.durationMin || 0);
  const [diaperKind, setDiaperKind] = useState(event.notes || "wet");
  const [leftMin, setLeftMin] = useState(event.leftMin || 0);
  const [rightMin, setRightMin] = useState(event.rightMin || 0);
  // Pump-specific: support editing as start+end time (range) or start+duration.
  // Default to "range" since it matches how users naturally log pumping.
  // endTsLocal lazily computed from event.ts + event.durationMin on mount.
  const [pumpEditMode, setPumpEditMode] = useState("range");
  const [endTsLocal, setEndTsLocal] = useState(() => {
    if (event.type !== "pump" || !event.durationMin) return "";
    const start = new Date(event.ts);
    if (isNaN(start.getTime())) return "";
    const end = new Date(start.getTime() + Number(event.durationMin) * 60000);
    return safeDatetimeLocal(end);
  });
  // v05.05bt22: bottle label editable on pump events. The label originally
  // gets set during the FinishPumpModal flow, but if it was missed (e.g.
  // backfilled pump, retroactive entry), users want to add/correct it here.
  // We persist BOTH on the pump event AND on the matching inventory bottle
  // (linked by ts ↔ pumpedAt) so the label propagates everywhere.
  const [bottleLabel, setBottleLabel] = useState(event.bottleLabel || "");
  // v05.05bt89: same affordance for FEED events. A feed logged without an
  // explicit bottle pick (or with a shortfall) carries inventoryReconcileNeeded
  // and reconcileReason fields; previously the only resolution path was the
  // "Mark resolved" button which cleared the flag but lost the attribution.
  // Now the edit form has a bottle-label input so the user can attribute the
  // feed to a specific bottle by name (A/B/1/2/etc) at the same time — or
  // independently, since attributing the bottle is useful even when the
  // reconcile is already resolved.
  const [feedBottleLabel, setFeedBottleLabel] = useState(event.bottleLabel || "");

  const submit = () => {
    const ts = new Date(tsLocal).toISOString();
    const updated = { ...event, ts };
    if (event.type === "feed") {
      updated.oz = Number(oz);
      updated.source = source;
      // v05.05bt89: persist bottle label on feed events
      updated.bottleLabel = feedBottleLabel.trim() || null;
    } else if (event.type === "pump") {
      updated.oz = Number(oz);
      // If editing in start+end mode, recompute duration from the latest
      // tsLocal + endTsLocal (covers the case where the user changed the
      // start time after picking an end time). If in duration mode, just
      // trust the durationMin field.
      if (pumpEditMode === "range" && endTsLocal) {
        const s = new Date(tsLocal);
        const e = new Date(endTsLocal);
        if (!isNaN(s.getTime()) && !isNaN(e.getTime())) {
          updated.durationMin = Math.max(0, Math.round((e - s) / 60000));
        } else {
          updated.durationMin = Number(durationMin);
        }
      } else {
        updated.durationMin = Number(durationMin);
      }
      // v05.05bt22: persist bottle label
      updated.bottleLabel = bottleLabel.trim() || null;
    } else if (event.type === "diaper") {
      updated.notes = diaperKind;
    } else if (event.type === "breastfeed") {
      updated.leftMin = Number(leftMin);
      updated.rightMin = Number(rightMin);
      updated.totalDurationMin = Number(leftMin) + Number(rightMin);
    } else if (event.type === "activity") {
      updated.durationMin = Number(durationMin);
    } else if (event.type === "takeover") {
      updated.durationMin = Number(durationMin);
    }
    onSave(updated);
  };

  const titles = {
    feed: "Edit feed",
    breastfeed: "Edit breastfeed",
    pump: "Edit pump",
    diaper: "Edit diaper change",
    sleep_down: "Edit sleep-down time",
    sleep_up: "Edit wake time",
    bath: "Edit bath",
    skincare: "Edit skincare routine",
    activity: "Edit activity",
    takeover: "Edit takeover",
  };

  return (
    <ModalShell C={C} onClose={onClose} title={titles[event.type] || "Edit event"}>
      <Field C={C} label="When?">
        <input
          type="datetime-local"
          value={tsLocal}
          onChange={e => setTsLocal(e.target.value)}
          style={{
            width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
            borderRadius: 8, fontSize: 14, background: C.bg, color: C.ink,
            fontFamily: "inherit",
          }}
        />
      </Field>

      {event.type === "feed" && (
        <>
          {event.inventoryReconcileNeeded && (
            <div style={{
              marginBottom: 14, padding: 12,
              background: `${C.gold}15`,
              border: `1px solid ${C.gold}55`,
              borderRadius: 10,
            }}>
              <div style={{
                fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase",
                color: C.gold, fontWeight: 700, marginBottom: 4,
              }}>
                ⚠ Inventory mismatch
              </div>
              <div style={{ fontSize: 12, color: C.ink, lineHeight: 1.5, marginBottom: 8 }}>
                This feed was logged without picking a bottle from inventory. If you've since added the missing bottle, mark this resolved.
              </div>
              <button onClick={() => onSave({ ...event, inventoryReconcileNeeded: false })} style={{
                background: C.gold, color: "#1F1B16", border: "none",
                borderRadius: 6, padding: "6px 12px",
                fontSize: 11, fontWeight: 600, cursor: "pointer",
                fontFamily: "inherit",
              }}>
                Mark resolved (clear ⚠)
              </button>
            </div>
          )}
          <Field C={C} label="Volume (oz)">
            <BigOzPicker C={C} value={oz} onChange={setOz} />
          </Field>
          <Field C={C} label="Source">
            <SegControl C={C} value={source} onChange={setSource} options={[
              { v: "BM", l: "Breast milk" },
              { v: "BM-thawed", l: "BM (thawed)" },
              { v: "Formula", l: "Formula" },
              { v: "BM+Formula", l: "Mix" },
            ]} />
          </Field>
          {/* v05.05bt89: bottle-label field on feeds. Useful for
              attributing a feed to a specific bottle when the reconcile
              flag is set and the original log didn't pick one, OR for
              correcting/adding a label after the fact even on resolved
              feeds. Same shape as the pump-event field so the
              feedBottleSuffix helper renders it consistently. */}
          <Field C={C} label="Bottle label (optional)">
            <input
              type="text"
              value={feedBottleLabel}
              onChange={e => setFeedBottleLabel(e.target.value.slice(0, 4).toUpperCase())}
              placeholder="A, B, 1, 2…"
              maxLength={4}
              style={{
                width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                borderRadius: 8, fontSize: 14, background: C.bg, color: C.ink,
                fontFamily: "'JetBrains Mono', monospace", letterSpacing: "0.05em",
              }}
            />
            <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic", marginTop: 6, lineHeight: 1.4 }}>
              Attribute this feed to a specific bottle. Helps after-the-fact reconciliation.
            </div>
          </Field>
        </>
      )}

      {event.type === "pump" && (() => {
        // Pump editing supports two mental models:
        //  1) Start time + duration  → "I started at 6am and pumped for 30min"
        //  2) Start time + end time  → "I pumped 6:00–6:30am"
        // The user reports thinking in (2) — which matches how times are
        // logged in bulk-import format. We default to (2) but offer a
        // toggle so they can pick whichever feels natural for that edit.
        // Compute end time as a derived datetime-local string from
        // (tsLocal + durationMin) so toggling between modes preserves data.
        const computeEndFromStart = (startStr, dur) => {
          if (!startStr || !dur) return startStr;
          const start = new Date(startStr);
          if (isNaN(start.getTime())) return startStr;
          const end = new Date(start.getTime() + Number(dur) * 60000);
          return safeDatetimeLocal(end);
        };
        const computeDurFromRange = (startStr, endStr) => {
          if (!startStr || !endStr) return 0;
          const s = new Date(startStr);
          const e = new Date(endStr);
          if (isNaN(s.getTime()) || isNaN(e.getTime())) return 0;
          const mins = Math.round((e - s) / 60000);
          return Math.max(0, mins);
        };

        return (
          <>
            <Field C={C} label="Volume (oz)">
              <BigOzPicker C={C} value={oz} onChange={setOz} />
            </Field>

            {/* Mode toggle — start+end (default) vs start+duration */}
            <div style={{ marginBottom: 10 }}>
              <SegControl C={C} value={pumpEditMode} onChange={setPumpEditMode} options={[
                { v: "range", l: "Start–End" },
                { v: "duration", l: "Duration" },
              ]} />
            </div>

            {pumpEditMode === "range" ? (
              <Field C={C} label="End time">
                <input
                  type="datetime-local"
                  value={endTsLocal || computeEndFromStart(tsLocal, durationMin)}
                  onChange={e => {
                    const newEnd = e.target.value;
                    setEndTsLocal(newEnd);
                    // Keep durationMin in sync so saving uses an accurate value
                    setDurationMin(computeDurFromRange(tsLocal, newEnd));
                  }}
                  style={{
                    width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                    borderRadius: 8, fontSize: 14, background: C.bg, color: C.ink,
                    fontFamily: "inherit",
                  }}
                />
                {durationMin > 0 && (
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 6, fontStyle: "italic" }}>
                    duration: {durationMin} min
                  </div>
                )}
              </Field>
            ) : (
              <Field C={C} label="Duration (min)">
                <input
                  type="number" inputMode="numeric" min="1" max="120"
                  value={durationMin}
                  onChange={e => {
                    const newDur = e.target.value;
                    setDurationMin(newDur);
                    // Keep endTsLocal in sync
                    setEndTsLocal(computeEndFromStart(tsLocal, newDur));
                  }}
                  style={{
                    width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                    borderRadius: 8, fontSize: 18, background: C.bg, color: C.ink,
                    fontFamily: "'Cormorant Garamond', serif", fontWeight: 500,
                  }}
                />
                {tsLocal && durationMin > 0 && (() => {
                  const endStr = computeEndFromStart(tsLocal, durationMin);
                  const endDate = new Date(endStr);
                  if (isNaN(endDate.getTime())) return null;
                  const pad = (n) => String(n).padStart(2, "0");
                  const period = endDate.getHours() >= 12 ? "pm" : "am";
                  const h12 = endDate.getHours() % 12 === 0 ? 12 : endDate.getHours() % 12;
                  return (
                    <div style={{ fontSize: 11, color: C.muted, marginTop: 6, fontStyle: "italic" }}>
                      ends at {h12}:{pad(endDate.getMinutes())}{period}
                    </div>
                  );
                })()}
              </Field>
            )}

            {/* v05.05bt22: bottle label editor. Useful when the label was
                missed during the original FinishPumpModal flow, or when
                backfilling pumps. Persisted on both the pump event and
                the matching inventory bottle. */}
            <Field C={C} label="Bottle label (optional)">
              <input
                type="text"
                value={bottleLabel}
                onChange={e => setBottleLabel(e.target.value.toUpperCase().slice(0, 3))}
                placeholder="e.g. A"
                maxLength={3}
                style={{
                  width: "100%", padding: 10, fontSize: 16,
                  background: C.bg, border: `1px solid ${C.line}33`,
                  borderRadius: 8, color: C.ink, outline: "none",
                  fontFamily: "'Cormorant Garamond', serif",
                  letterSpacing: "0.1em", textTransform: "uppercase",
                }}
              />
              <div style={{ fontSize: 11, color: C.muted, marginTop: 4, fontStyle: "italic" }}>
                Sharpie label on the bottle, if any. Helps identify which bottle is which.
              </div>
            </Field>
          </>
        );
      })()}

      {event.type === "diaper" && (
        <Field C={C} label="Type">
          <SegControl C={C} value={diaperKind} onChange={setDiaperKind} options={[
            { v: "wet", l: "Pee" },
            { v: "dirty", l: "Poo" },
            { v: "both", l: "Both" },
          ]} />
        </Field>
      )}

      {event.type === "breastfeed" && (
        <>
          <Field C={C} label="Left side (min)">
            <input
              type="number" inputMode="numeric" min="0" max="60"
              value={leftMin}
              onChange={e => setLeftMin(e.target.value)}
              style={{
                width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                borderRadius: 8, fontSize: 18, background: C.bg, color: C.ink,
                fontFamily: "'Cormorant Garamond', serif", fontWeight: 500,
              }}
            />
          </Field>
          <Field C={C} label="Right side (min)">
            <input
              type="number" inputMode="numeric" min="0" max="60"
              value={rightMin}
              onChange={e => setRightMin(e.target.value)}
              style={{
                width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                borderRadius: 8, fontSize: 18, background: C.bg, color: C.ink,
                fontFamily: "'Cormorant Garamond', serif", fontWeight: 500,
              }}
            />
          </Field>
          <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic", marginTop: -6, marginBottom: 12 }}>
            Total: {Number(leftMin) + Number(rightMin)} min
          </div>
        </>
      )}

      {event.type === "activity" && (
        <Field C={C} label="Duration (min)">
          <input
            type="number" inputMode="numeric" min="1" max="240"
            value={durationMin}
            onChange={e => setDurationMin(e.target.value)}
            style={{
              width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
              borderRadius: 8, fontSize: 18, background: C.bg, color: C.ink,
              fontFamily: "'Cormorant Garamond', serif", fontWeight: 500,
            }}
          />
        </Field>
      )}

      {event.type === "takeover" && (
        <>
          <Field C={C} label="Coverage duration (min)">
            <input
              type="number" inputMode="numeric" min="1" max="480"
              value={durationMin}
              onChange={e => setDurationMin(e.target.value)}
              style={{
                width: "100%", padding: "10px 12px", border: `1px solid ${C.line}33`,
                borderRadius: 8, fontSize: 18, background: C.bg, color: C.ink,
                fontFamily: "'Cormorant Garamond', serif", fontWeight: 500,
              }}
            />
            <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic", marginTop: 6, lineHeight: 1.5 }}>
              <strong>{event.coveringParent}</strong> covered <strong>{event.originalParent}</strong> for this many minutes. Editing this updates the time bank and today's plan automatically.
            </div>
          </Field>
        </>
      )}

      {(event.type === "sleep_down" || event.type === "sleep_up" || event.type === "bath" || event.type === "skincare") && (
        <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic", marginBottom: 12 }}>
          Only the time can be edited for this event type.
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 8 }}>
        <button onClick={onDelete} style={{
          background: "transparent", color: C.accent,
          border: `1px solid ${C.accent}55`, borderRadius: 10,
          padding: 12, fontSize: 13, fontWeight: 500, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 5,
        }}>
          <Trash2 size={13} /> Delete
        </button>
        <SubmitButton C={C} onClick={submit}>Save changes</SubmitButton>
      </div>
    </ModalShell>
  );
}

// ---- Day plan card -----------------------------------------------------
// Shows ONE day's coverage: the per-parent shift grid + auto-swap
// adjustments + commitments, all in one place. Used inside the unified
// "Day plan" section for both Today and Tomorrow.
//
// Props:
//   C          — palette
//   label      — "Today" or "Tomorrow" or any other day label
//   subLabel   — date string, e.g. "Tue, May 6"
//   defaultOpen — initial expand state (true for today, false for tomorrow)
//   shiftBlocks — { Mommy: [...], Daddy: [...] } projected for this day
//   daySwaps   — list of auto-swap adjustments for the day
//   commitments — meetings/commitments scheduled for the day
//   onRemoveCommitment — for tap-to-delete on commitments
//   onAddCommitment — only shown when this is "today" (you can add for any
//                    day really, but the affordance lives on today's card)
//   showAddButton — boolean, whether to show "Add commitment" button
//
// Visual hierarchy:
//   1. Day header with chevron (clickable to collapse/expand)
//   2. (When open) Shifts grid · auto-swap summary · commitments list · add button
// ---- DayPlanShiftStrip --------------------------------------------------
// Renders the day's shift plan as a horizontal hour-block bar mirroring the
// landing-page ShiftStrip treatment. Unlike the landing-page strip (rolling
// next-24h), this strip shows midnight→midnight of a specific calendar day
// (today or tomorrow). Carve/cover/conflict annotations on the slices get
// layered on as visual indicators so changes pop without needing to read
// the auto-adjustments log.
function DayPlanShiftStrip({ C, shiftBlocks, commitments, isToday, now }) {
  // Build 24 hourly cells from 00:00 → 24:00 of the target calendar day.
  // Each cell asks: who's on duty for that hour, and is the slice they're
  // in carved or conflicting?
  const cells = [];
  for (let h = 0; h < 24; h++) {
    const cellMins = h * 60 + 30; // mid-hour for slot lookup
    let parent = null;
    let coveringFor = null;
    let isConflict = false;
    let isCarved = false;
    for (const p of ["Mommy", "Daddy"]) {
      for (const s of (shiftBlocks?.[p] || [])) {
        const a = toMin(s.start);
        const b = toMin(s.end);
        const inShift = a < b ? cellMins >= a && cellMins < b : cellMins >= a || cellMins < b;
        if (inShift) {
          parent = p;
          coveringFor = s._coveringFor || null;
          isConflict = !!s._conflict;
          isCarved = !!s._isCarvedSlice || !!s._isCarvedFree;
          break;
        }
      }
      if (parent) break;
    }
    cells.push({ hour: h, parent, coveringFor, isConflict, isCarved });
  }

  // Compute commitment marks — small ticks on top of the strip at the
  // start time of each commitment for the visible day. Time is in minutes
  // since midnight (0–1440).
  const commitmentMarks = (commitments || []).map(m => {
    const start = new Date(m.start);
    const end = new Date(m.end);
    // Use local time for the day — these meetings are stored as ISO UTC
    // but we display at the day's local-time scale.
    const startMins = start.getHours() * 60 + start.getMinutes();
    const endMins = end.getHours() * 60 + end.getMinutes();
    return {
      startPct: (startMins / 1440) * 100,
      widthPct: Math.max(0.5, ((endMins - startMins) / 1440) * 100),
      parent: m.parent,
      level: m.level,
      label: m.label,
    };
  });

  const nowPct = isToday ? ((now.getHours() * 60 + now.getMinutes()) / 1440) * 100 : null;

  return (
    <div style={{
      background: C.bg, borderRadius: 10, padding: 12,
      border: `1px solid ${C.line}12`, marginBottom: 10,
    }}>
      {/* Legend row — Mommy / Daddy / covering / now */}
      <div style={{
        display: "flex", justifyContent: "space-between", alignItems: "center",
        marginBottom: 8, flexWrap: "wrap", gap: 6,
      }}>
        <div style={{
          display: "flex", gap: 10, fontSize: 10, color: C.muted,
          letterSpacing: "0.04em",
        }}>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ width: 10, height: 10, background: C.mommy, borderRadius: 2 }} /> Mommy
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ width: 10, height: 10, background: C.daddy, borderRadius: 2 }} /> Daddy
          </span>
        </div>
        <div style={{ fontSize: 10, color: C.muted, fontStyle: "italic" }}>
          ↻ = covered · ! = conflict
        </div>
      </div>

      {/* Commitment ticks above the strip — small lines at each meeting time */}
      {commitmentMarks.length > 0 && (
        <div style={{ position: "relative", height: 8, marginBottom: 2 }}>
          {commitmentMarks.map((m, i) => {
            const cColor = m.parent === "Mommy" ? C.mommy : C.daddy;
            const lvlBorder = m.level === "red" ? "#C44545" : m.level === "yellow" ? C.gold : "#5C8E5C";
            return (
              <div
                key={i}
                title={`${m.parent} · ${m.label}`}
                style={{
                  position: "absolute",
                  left: `${m.startPct}%`,
                  width: `${m.widthPct}%`,
                  bottom: 0,
                  height: 6,
                  background: cColor,
                  border: `1px solid ${lvlBorder}`,
                  borderRadius: 2,
                }}
              />
            );
          })}
        </div>
      )}

      {/* Hour blocks */}
      <div style={{
        position: "relative",
        display: "flex", height: 32, borderRadius: 6, overflow: "hidden",
        border: `1px solid ${C.line}11`, marginBottom: 4,
      }}>
        {cells.map((c, i) => {
          // Determine block color and emphasis. Carved/covered slots get a
          // darker tint + outline so they pop against the regular slice color.
          const baseColor = c.parent === "Mommy" ? C.mommy : c.parent === "Daddy" ? C.daddy : C.muted;
          const isHighlighted = c.isCarved || c.coveringFor || c.isConflict;
          return (
            <div key={i} style={{
              flex: 1,
              background: baseColor,
              opacity: isHighlighted ? 1 : 0.8,
              position: "relative",
              borderRight: i < 23 ? `1px solid ${C.bg}55` : "none",
              outline: c.isConflict
                ? `2px solid ${C.accent}`
                : isHighlighted
                ? `1.5px solid ${C.ink}`
                : "none",
              outlineOffset: -2,
              zIndex: isHighlighted ? 2 : 1,
            }}>
              {/* Indicator letter on top of the block when carved/conflict */}
              {c.isConflict ? (
                <div style={{
                  position: "absolute", top: 2, left: 0, right: 0,
                  textAlign: "center", fontSize: 11, fontWeight: 700,
                  color: "#fff", textShadow: "0 1px 2px rgba(0,0,0,0.4)",
                  pointerEvents: "none",
                }}>!</div>
              ) : isHighlighted ? (
                <div style={{
                  position: "absolute", top: 2, left: 0, right: 0,
                  textAlign: "center", fontSize: 10, fontWeight: 700,
                  color: "#fff", textShadow: "0 1px 2px rgba(0,0,0,0.4)",
                  pointerEvents: "none",
                }}>↻</div>
              ) : null}
            </div>
          );
        })}
        {/* Now line — only on Today's strip */}
        {nowPct !== null && (
          <div style={{
            position: "absolute", top: -3, bottom: -3,
            left: `${nowPct}%`,
            width: 2,
            background: C.accent,
            boxShadow: `0 0 8px ${C.accent}`,
            zIndex: 3,
          }} />
        )}
      </div>

      {/* Hour labels every 3h */}
      <div style={{
        display: "flex", fontSize: 9, color: C.muted,
        fontFamily: "'JetBrains Mono', monospace",
      }}>
        {cells.map((c, i) => (
          <div key={i} style={{ flex: 1, textAlign: "center" }}>
            {i % 3 === 0 ? (
              c.hour === 0 ? "12a" :
              c.hour === 12 ? "12p" :
              c.hour < 12 ? `${c.hour}a` : `${c.hour - 12}p`
            ) : ""}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 8, fontSize: 10, color: C.muted, fontStyle: "italic" }}>
        ↑ each block = 1 hour · highlighted blocks = adjusted shifts
        {isToday && <> · orange line marks <strong style={{ color: C.accent }}>now</strong></>}
        {commitmentMarks.length > 0 && <> · bars above show commitments</>}
      </div>
    </div>
  );
}

// ---- DayPlanCard -------------------------------------------------------
function DayPlanCard({
  C, label, subLabel, defaultOpen,
  shiftBlocks, daySwaps, commitments,
  onRemoveCommitment, onEditCommitment, onAddCommitment, showAddButton,
  isToday,
  now,
  // Controlled-open mode: when controlledOpen + setControlledOpen are
  // provided, this component delegates open state to the parent. This
  // lets the peek strip toggle a specific day's card from outside.
  controlledOpen, setControlledOpen,
}) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = controlledOpen !== undefined && setControlledOpen !== undefined;
  const open = isControlled ? controlledOpen : internalOpen;
  const setOpen = isControlled ? setControlledOpen : setInternalOpen;

  const totalCommits = commitments?.length || 0;
  const swapCount = daySwaps?.length || 0;
  const headerColor = isToday ? C.accent : C.mommy;

  return (
    <div id={isToday ? "dayplan-today" : "dayplan-tomorrow"} style={{
      background: C.paper,
      borderRadius: 12,
      border: `1px solid ${C.line}15`,
      borderLeft: `4px solid ${headerColor}`,
      marginBottom: 10,
      overflow: "hidden",
      scrollMarginTop: 80,
    }}>
      {/* Header — always visible. Tappable to expand/collapse. */}
      <button
        onClick={() => setOpen(o => !o)}
        style={{
          width: "100%",
          background: "transparent",
          border: "none",
          padding: "12px 14px",
          cursor: "pointer",
          fontFamily: "inherit",
          textAlign: "left",
          display: "flex", alignItems: "center", gap: 10,
        }}>
        <ChevronRight
          size={14}
          color={C.muted}
          style={{
            flexShrink: 0,
            transition: "transform 0.2s",
            transform: open ? "rotate(90deg)" : "rotate(0deg)",
          }}
        />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            fontFamily: "'Cormorant Garamond', serif",
            fontSize: 19, fontWeight: 600, fontStyle: "italic",
            color: headerColor, lineHeight: 1.1,
          }}>
            {label}
          </div>
          <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>
            {subLabel}
          </div>
        </div>
        <div style={{
          display: "flex", gap: 6, alignItems: "center",
          fontSize: 11, color: C.muted,
        }}>
          {totalCommits > 0 && (
            <span style={{
              background: `${C.accent}18`, color: C.accent,
              padding: "2px 8px", borderRadius: 999,
              fontWeight: 600, fontSize: 10, letterSpacing: "0.04em",
            }}>
              {totalCommits} {totalCommits === 1 ? "commitment" : "commitments"}
            </span>
          )}
          {swapCount > 0 && (
            <span style={{
              background: `${C.gold}18`, color: C.gold,
              padding: "2px 8px", borderRadius: 999,
              fontWeight: 600, fontSize: 10, letterSpacing: "0.04em",
            }}>
              ↻ {swapCount}
            </span>
          )}
        </div>
      </button>

      {/* Body — only when open */}
      {open && (
        <div style={{ padding: "0 14px 14px" }}>
          {/* v05.05bt27: replaced the bar graphic (DayPlanShiftStrip) with
              the same two-column shift list rendering used on the landing
              page's Today's Plan card. Annotation indicators (+/↔/↩/⚖/⏸)
              appear to the left of each adjusted shift; bold weight
              indicates a moved/repayment/takeover shift. The pulsing
              current-block dot only renders for today, never tomorrow. */}
          <div style={{
            border: `1px solid ${C.line}15`,
            borderRadius: 8,
            overflow: "hidden",
            marginBottom: 12,
          }}>
            <ShiftListGrid
              C={C}
              shifts={shiftBlocks}
              swaps={daySwaps}
              isToday={isToday}
              now={now}
            />
          </div>

          {/* Auto-swap summary — collapsed by default. Header shows just
              the count chip; tap to expand and see why each adjustment
              happened. The shifts grid above already has + indicators
              showing WHERE the changes are; this section answers WHY. */}
          {swapCount > 0 && (
            <details style={{
              background: `${C.accent}10`,
              border: `1px solid ${C.accent}30`,
              borderRadius: 8, marginBottom: 10,
              fontSize: 11, color: C.ink, lineHeight: 1.5,
            }}>
              <summary style={{
                padding: "6px 10px", cursor: "pointer", listStyle: "none",
                display: "flex", alignItems: "center", gap: 6,
                fontSize: 10, letterSpacing: "0.18em", textTransform: "uppercase",
                color: C.accent, fontWeight: 700,
              }}>
                <ChevronRight size={11} className={`autoswap-chevron-${label.toLowerCase()}`} style={{ transition: "transform 0.2s" }} />
                <span>↻ {swapCount} auto-adjustment{swapCount === 1 ? "" : "s"}</span>
                <span style={{ marginLeft: "auto", color: C.muted, fontSize: 9, fontWeight: 500, letterSpacing: "0.06em", textTransform: "none", fontStyle: "italic" }}>
                  tap to see why
                </span>
              </summary>
              <style>{`details[open] .autoswap-chevron-${label.toLowerCase()} { transform: rotate(90deg); }`}</style>
              <div style={{ padding: "0 10px 8px" }}>
                {daySwaps.map((sw, i) => {
                  const cColor = sw.coveringParent === "Mommy" ? C.mommy : sw.coveringParent === "Daddy" ? C.daddy : C.muted;
                  const oColor = sw.originalParent === "Mommy" ? C.mommy : C.daddy;
                  return (
                    <div key={i} style={{ display: "flex", alignItems: "center", gap: 5, padding: "2px 0", flexWrap: "wrap" }}>
                      {sw.blocked ? (
                        <>
                          <span style={{ color: C.accent, fontWeight: 600 }}>!</span>
                          <span style={{ color: oColor, fontWeight: 600 }}>{sw.originalParent}</span>
                          <span style={{ color: C.muted }}>blocked at</span>
                          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10 }}>{fmtShiftRange(sw.shift)}</span>
                        </>
                      ) : (
                        <>
                          <span style={{ color: cColor, fontWeight: 600 }}>+</span>
                          <span style={{ color: cColor, fontWeight: 600 }}>{sw.coveringParent}</span>
                          <span style={{ color: C.muted }}>covers</span>
                          <span style={{ color: oColor, fontWeight: 600 }}>{sw.originalParent}'s</span>
                          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10 }}>{fmtShiftRange(sw.shift)}</span>
                          {sw.reason && <span style={{ color: C.muted, fontStyle: "italic" }}>· {sw.reason}</span>}
                        </>
                      )}
                    </div>
                  );
                })}
              </div>
            </details>
          )}

          {/* Commitments */}
          {totalCommits > 0 ? (
            <>
              <div style={{ fontSize: 9, letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontWeight: 600, marginBottom: 6 }}>
                Commitments
              </div>
              <div style={{ display: "grid", gap: 6, marginBottom: showAddButton ? 10 : 0 }}>
                {commitments.map(m => (
                  <MeetingRow key={m.id} m={m} C={C}
                    onRemove={() => onRemoveCommitment(m.id)}
                    onEdit={onEditCommitment ? () => onEditCommitment(m) : undefined} />
                ))}
              </div>
            </>
          ) : (
            <div style={{
              color: C.muted, fontSize: 11, fontStyle: "italic",
              textAlign: "center", padding: "6px 0",
              marginBottom: showAddButton ? 8 : 0,
            }}>
              No commitments {isToday ? "today" : "logged for this day"} yet.
            </div>
          )}

          {/* Add button — only shown when caller wants it */}
          {showAddButton && (
            <button onClick={onAddCommitment} style={{
              width: "100%",
              background: "transparent",
              color: C.accent,
              border: `1px dashed ${C.accent}55`,
              borderRadius: 8, padding: "8px 12px",
              fontSize: 12, fontWeight: 600, cursor: "pointer",
              display: "flex", alignItems: "center", justifyContent: "center", gap: 5,
              fontFamily: "inherit",
            }}>
              <Plus size={12} /> Add commitment
            </button>
          )}
        </div>
      )}
    </div>
  );
}

// ---- Upcoming section --------------------------------------------------
// Collapsible list of commitments beyond tomorrow, with filter pills:
//   "All"        — everything beyond tomorrow
//   "Next 7"     — commitments in the next 7 days from now
//   "Next 30"    — commitments in the next 30 days from now
//   "Beyond"     — anything past 30 days
// Total count badge in header always shows total — filters scope the
// visible items but don't hide the bigger picture.
function UpcomingSection({ C, allFuture, sevenDaysOut, thirtyDaysOut, onRemoveMeeting, onEditMeeting, externalOpen, externalFilter, onExternalOpenHandled }) {
  const [filter, setFilter] = useState("all"); // "all" | "week" | "month" | "beyond"
  const detailsRef = useRef(null);

  // When the parent fires externalOpen (e.g. peek strip tap), open the
  // details element and (optionally) set the filter, then notify the parent
  // so it can clear its trigger flag.
  useEffect(() => {
    if (!externalOpen) return;
    if (detailsRef.current) detailsRef.current.open = true;
    if (externalFilter) setFilter(externalFilter);
    // Scroll the section into view
    if (detailsRef.current) {
      detailsRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    onExternalOpenHandled && onExternalOpenHandled();
  }, [externalOpen, externalFilter, onExternalOpenHandled]);

  const filtered = useMemo(() => {
    if (filter === "all") return allFuture;
    if (filter === "week") return allFuture.filter(m => new Date(m.start) <= sevenDaysOut);
    if (filter === "month") return allFuture.filter(m => new Date(m.start) <= thirtyDaysOut);
    if (filter === "beyond") return allFuture.filter(m => new Date(m.start) > thirtyDaysOut);
    return allFuture;
  }, [allFuture, filter, sevenDaysOut, thirtyDaysOut]);

  // Group filtered items by date for date-section headings. Within each
  // day's bucket, items are sorted by start time so the day reads
  // chronologically (9am → 11am → 4pm) rather than insertion order. The
  // outer Object.entries sort orders dates ascending.
  const sortedDateGroups = useMemo(() => {
    const byDate = {};
    for (const m of filtered) {
      const dt = new Date(m.start);
      const key = dt.toISOString().slice(0, 10);
      if (!byDate[key]) byDate[key] = { date: dt, items: [] };
      byDate[key].items.push(m);
    }
    // Sort items inside each day chronologically
    for (const key of Object.keys(byDate)) {
      byDate[key].items.sort((a, b) => new Date(a.start) - new Date(b.start));
    }
    return Object.entries(byDate).sort(([a], [b]) => a.localeCompare(b));
  }, [filtered]);

  // Counts per filter for badge labels
  const counts = useMemo(() => ({
    all: allFuture.length,
    week: allFuture.filter(m => new Date(m.start) <= sevenDaysOut).length,
    month: allFuture.filter(m => new Date(m.start) <= thirtyDaysOut).length,
    beyond: allFuture.filter(m => new Date(m.start) > thirtyDaysOut).length,
  }), [allFuture, sevenDaysOut, thirtyDaysOut]);

  const FILTERS = [
    { v: "all",    l: "All" },
    { v: "week",   l: "Next 7d" },
    { v: "month",  l: "Next 30d" },
    { v: "beyond", l: "Beyond" },
  ];

  return (
    <details ref={detailsRef} id="upcoming-section" open style={{
      background: C.paper, borderRadius: 12,
      border: `1px solid ${C.line}15`, marginTop: 14,
      overflow: "hidden",
      scrollMarginTop: 80,
    }}>
      <summary style={{
        padding: "12px 14px", cursor: "pointer",
        fontSize: 14, fontWeight: 600, color: C.ink,
        display: "flex", alignItems: "center", gap: 8,
        listStyle: "none",
      }}>
        <ChevronRight size={14} style={{ transition: "transform 0.2s" }} className="upcoming-chevron" />
        <span>Upcoming · {allFuture.length} commitment{allFuture.length === 1 ? "" : "s"}</span>
        <span style={{ marginLeft: "auto", fontSize: 11, color: C.muted, fontWeight: 500 }}>
          next: {allFuture[0] && new Date(allFuture[0].start).toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" })}
        </span>
      </summary>
      <style>{`details[open] .upcoming-chevron { transform: rotate(90deg); }`}</style>
      <div style={{ padding: "0 14px 14px" }}>
        {/* Filter pills */}
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8, marginBottom: 12 }}>
          {FILTERS.map(f => {
            const active = filter === f.v;
            const count = counts[f.v];
            return (
              <button
                key={f.v}
                onClick={() => setFilter(f.v)}
                style={{
                  background: active ? C.accent : "transparent",
                  color: active ? "#fff" : C.ink,
                  border: `1px solid ${active ? C.accent : C.line + "40"}`,
                  borderRadius: 999, padding: "5px 11px",
                  fontSize: 11, fontWeight: 600, cursor: "pointer",
                  fontFamily: "inherit",
                  display: "inline-flex", alignItems: "center", gap: 5,
                }}>
                {f.l}
                <span style={{
                  fontSize: 10, opacity: active ? 0.85 : 0.6,
                  fontFamily: "'JetBrains Mono', monospace", fontWeight: 500,
                }}>
                  {count}
                </span>
              </button>
            );
          })}
        </div>

        {/* Filtered date groups */}
        {sortedDateGroups.length === 0 ? (
          <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic", textAlign: "center", padding: "12px 0" }}>
            Nothing in this window.
          </div>
        ) : sortedDateGroups.map(([key, { date, items }]) => (
          <div key={key} style={{ marginBottom: 10 }}>
            <div style={{
              fontSize: 10, letterSpacing: "0.18em", textTransform: "uppercase",
              color: C.muted, fontWeight: 700, marginBottom: 6,
              paddingBottom: 4, borderBottom: `1px solid ${C.line}15`,
            }}>
              {date.toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" })}
            </div>
            <div style={{ display: "grid", gap: 6 }}>
              {items.map(m => (
                <MeetingRow key={m.id} m={m} C={C}
                  onRemove={() => onRemoveMeeting(m.id)}
                  onEdit={onEditMeeting ? () => onEditMeeting(m) : undefined} />
              ))}
            </div>
          </div>
        ))}
      </div>
    </details>
  );
}

// v05.05bt50 — DayInLifeCard. Extracted from AnalyticsSection (where it
// lived in bt48–bt49) and moved to the Schedule tab as the headline card.
// Why move: the Schedule tab is where time-based household info lives
// (parents' shifts, meetings, coverage); Solène's typical day is the
// same conceptual category, so putting baby + parents on one surface
// makes Schedule the unified household-time view. Wellness was the
// wrong home — that tab is full of statistical cards (sleep trace,
// prediction accuracy, nap quality histograms); Day-in-Life is
// descriptive, not analytical, so it was the odd card out there.
//
// Behavior: COLLAPSED by default. Tap the header to expand and reveal
// the full schedule; tap again to collapse. When collapsed, shows a
// single-line teaser ("8:00a wake → 9:30p bedtime · 3 naps") plus a
// chevron that rotates 90° on expand. The Sun icon — chosen for the
// dawn-to-dusk arc this card represents — sits on the left of the
// header, gold-tinted to match the card's accent color.
function DayInLifeCard({ C, events, now }) {
  const [expanded, setExpanded] = useState(false);
  const window14 = events.filter(e =>
    new Date(e.ts) >= new Date(now.getTime() - 14 * 86400000) && !e.silent
  );
  const days = {};
  for (const e of window14) {
    const d = new Date(e.ts);
    const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    if (!days[dk]) days[dk] = [];
    days[dk].push(e);
  }
  const wakes = [], baths = [], bedtimes = [];
  const napsPerDay = [];
  for (const dk in days) {
    const dayEv = days[dk].sort((a, b) => new Date(a.ts) - new Date(b.ts));
    const wake = dayEv.find(e => e.type === "sleep_up" &&
      new Date(e.ts).getHours() >= 5 && new Date(e.ts).getHours() < 12);
    if (wake) wakes.push(new Date(wake.ts));
    const bath = dayEv.find(e => e.type === "bath");
    if (bath) baths.push(new Date(bath.ts));
    const bedtime = dayEv.filter(e => e.type === "sleep_down" &&
      new Date(e.ts).getHours() >= 18).slice(-1)[0];
    if (bedtime) bedtimes.push(new Date(bedtime.ts));
    const napCount = dayEv.filter(e => e.type === "sleep_down" &&
      new Date(e.ts).getHours() >= 6 && new Date(e.ts).getHours() < 19).length;
    napsPerDay.push(napCount);
  }
  // Insufficient data fallback
  if (wakes.length < 3) {
    return (
      <div style={{
        background: C.paper, borderRadius: 12, padding: 14, marginBottom: 12,
        border: `1px solid ${C.line}30`,
      }}>
        <div style={{
          fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase",
          color: C.muted, fontWeight: 600, marginBottom: 6,
          display: "flex", alignItems: "center", gap: 6,
        }}>
          <Sun size={12} color={C.gold} />
          A day in Solène's life
        </div>
        <div style={{ fontSize: 13, color: C.muted, fontStyle: "italic", lineHeight: 1.5 }}>
          Not enough data yet to draw her typical day. Check back after a few more days of logging.
        </div>
      </div>
    );
  }
  // Helpers
  const medianMin = (dates) => {
    const minutes = dates.map(d => d.getHours() * 60 + d.getMinutes()).sort((a, b) => a - b);
    return minutes[Math.floor(minutes.length / 2)];
  };
  const fmtT = (m, withAP = true) => {
    const mod = ((m % 1440) + 1440) % 1440;
    const h12 = Math.floor(mod / 60) % 12 || 12;
    const ap = mod >= 720 ? "p" : "a";
    return `${h12}:${String(mod % 60).padStart(2, "0")}${withAP ? ap : ""}`;
  };
  const fmtRange = (from, to) => {
    if (to == null) return fmtT(from);
    const fromAP = ((from % 1440) + 1440) % 1440 >= 720 ? "p" : "a";
    const toAP = ((to % 1440) + 1440) % 1440 >= 720 ? "p" : "a";
    if (fromAP === toAP) return `${fmtT(from, false)}–${fmtT(to)}`;
    return `${fmtT(from)}–${fmtT(to)}`;
  };
  const wakeStart = medianMin(wakes);
  const bathStart = baths.length >= 2 ? medianMin(baths) : null;
  const bedtimeStart = medianMin(bedtimes);
  const sleepEvs = window14
    .filter(e => e.type === "sleep_up" || e.type === "sleep_down")
    .sort((a, b) => new Date(a.ts) - new Date(b.ts));
  const wakeWindows = [];
  for (let i = 0; i < sleepEvs.length - 1; i++) {
    if (sleepEvs[i].type === "sleep_up" && sleepEvs[i + 1].type === "sleep_down") {
      const w = (new Date(sleepEvs[i + 1].ts) - new Date(sleepEvs[i].ts)) / 60000;
      if (w >= 30 && w <= 240) wakeWindows.push(w);
    }
  }
  wakeWindows.sort((a, b) => a - b);
  const medWakeWindow = wakeWindows.length
    ? Math.round(wakeWindows[Math.floor(wakeWindows.length / 2)])
    : 90;
  const sleepPairs = [];
  let openSleep = null;
  for (const e of sleepEvs) {
    if (e.type === "sleep_down") openSleep = e;
    else if (e.type === "sleep_up" && openSleep) {
      const d = (new Date(e.ts) - new Date(openSleep.ts)) / 60000;
      const h = new Date(openSleep.ts).getHours();
      if (d > 5 && d < 240 && h >= 6 && h < 19) sleepPairs.push(d);
      openSleep = null;
    }
  }
  sleepPairs.sort((a, b) => a - b);
  const medNapDur = sleepPairs.length
    ? Math.round(sleepPairs[Math.floor(sleepPairs.length / 2)])
    : 60;
  const napsAvg = napsPerDay.length
    ? Math.round(napsPerDay.reduce((s, n) => s + n, 0) / napsPerDay.length)
    : 3;
  const napsCount = Math.max(1, Math.min(5, napsAvg));
  const FEED_DUR = 25;
  const WAKE_TO_FEED = 5;
  const BATH_DUR = 15;
  const blocks = [];
  let t = wakeStart;
  blocks.push({ from: t, to: t + WAKE_TO_FEED, label: "Wake up" });
  t += WAKE_TO_FEED;
  blocks.push({ from: t, to: t + FEED_DUR, label: "Feed", detail: "+ diaper change" });
  t += FEED_DUR;
  for (let n = 0; n < napsCount; n++) {
    const playDur = Math.max(15, medWakeWindow - FEED_DUR);
    blocks.push({ from: t, to: t + playDur, label: "Awake / play" });
    t += playDur;
    const napLabel = (napsCount >= 3 && n === Math.floor((napsCount - 1) / 2))
      ? "Nap (often longest)" : "Nap";
    blocks.push({ from: t, to: t + medNapDur, label: napLabel });
    t += medNapDur;
    const wouldOvershoot = bathStart != null && t + FEED_DUR > bathStart - 30;
    if (!wouldOvershoot && n < napsCount - 1) {
      blocks.push({ from: t, to: t + FEED_DUR, label: "Feed", detail: "+ diaper change" });
      t += FEED_DUR;
    }
  }
  if (bathStart != null) {
    if (t < bathStart) {
      blocks.push({ from: t, to: bathStart, label: "Awake / wind down" });
      t = bathStart;
    }
    blocks.push({ from: bathStart, to: bathStart + BATH_DUR, label: "Bath" });
    t = bathStart + BATH_DUR;
  }
  if (t + FEED_DUR <= bedtimeStart) {
    blocks.push({ from: t, to: t + FEED_DUR, label: "Last feed" });
    t += FEED_DUR;
  }
  if (t < bedtimeStart) {
    blocks.push({ from: t, to: bedtimeStart, label: "Wind down" });
    t = bedtimeStart;
  }
  blocks.push({ from: bedtimeStart, to: null, label: "Bedtime", detail: "down for the night" });
  // Collapsed-state teaser line
  const teaser = `${fmtT(wakeStart)} wake → ${fmtT(bedtimeStart)} bedtime · ${napsCount} nap${napsCount === 1 ? "" : "s"}`;
  return (
    <div style={{
      background: `linear-gradient(135deg, ${C.gold}10, ${C.paper})`,
      borderRadius: 12, marginBottom: 12,
      border: `1px solid ${C.gold}30`,
      overflow: "hidden",
    }}>
      <button onClick={() => setExpanded(v => !v)} style={{
        width: "100%", border: "none", background: "transparent",
        padding: "12px 14px", textAlign: "left", cursor: "pointer",
        fontFamily: "inherit",
        display: "flex", alignItems: "center", gap: 10,
      }}>
        <Sun size={18} color={C.gold} style={{ flexShrink: 0 }} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
            <span style={{
              fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase",
              color: C.gold, fontWeight: 700,
            }}>
              A day in Solène's life
            </span>
            <span style={{
              fontSize: 9, fontWeight: 600, color: C.muted,
              background: `${C.line}15`, padding: "2px 7px", borderRadius: 8,
              letterSpacing: "0.04em",
            }}>
              for caregivers
            </span>
          </div>
          <div style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 11, color: C.muted, marginTop: 3,
            letterSpacing: "0.02em",
          }}>
            {teaser}
          </div>
        </div>
        <ChevronRight size={18} color={C.muted} style={{
          flexShrink: 0,
          transform: expanded ? "rotate(90deg)" : "rotate(0deg)",
          transition: "transform 0.18s ease",
        }} />
      </button>
      {expanded && (
        <div style={{ padding: "0 14px 14px" }}>
          <div style={{
            fontFamily: "'Cormorant Garamond', serif", fontSize: 13,
            fontStyle: "italic", color: C.muted, marginBottom: 10, lineHeight: 1.4,
          }}>
            Simulated from her last 14 days. Times shift naturally — use as a guide, not a clock.
          </div>
          <div style={{ display: "flex", flexDirection: "column" }}>
            {blocks.map((b, i) => (
              <div key={i} style={{
                display: "grid", gridTemplateColumns: "100px 1fr",
                gap: 12, padding: "9px 0",
                borderBottom: i === blocks.length - 1 ? "none" : `1px solid ${C.line}18`,
                alignItems: "baseline",
              }}>
                <div style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 11, color: C.gold, fontWeight: 600,
                  letterSpacing: "0.02em", whiteSpace: "nowrap",
                }}>
                  {fmtRange(b.from, b.to)}
                </div>
                <div>
                  <div style={{
                    fontFamily: "'Cormorant Garamond', serif",
                    fontSize: 16, color: C.ink, fontStyle: "italic",
                    fontWeight: 500, lineHeight: 1.2,
                  }}>
                    {b.label}
                  </div>
                  {b.detail && (
                    <div style={{
                      fontSize: 11, color: C.muted, marginTop: 2, lineHeight: 1.4,
                    }}>
                      {b.detail}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
          <div style={{
            fontSize: 9, color: C.muted, fontStyle: "italic",
            marginTop: 10, lineHeight: 1.4,
            padding: "6px 10px",
            background: `${C.line}10`, borderRadius: 6,
            borderLeft: `2px solid ${C.line}40`,
          }}>
            Built from medians: wake window {medWakeWindow}m · nap {medNapDur}m · {napsCount} naps/day · feed every ~{Math.round(medWakeWindow + FEED_DUR)}m. Sample: {wakes.length} mornings logged.
          </div>
        </div>
      )}
    </div>
  );
}

// v05.05bt51 — SundayRoutineCard. First *family scenario* routine: an
// orchestrated Sunday-morning template anchored on "leave for church by
// 9:20a," with parent and baby components stacked in the order they need
// to happen. Computed live: change a duration in SUNDAY_ROUTINE and
// every time block + the bedtime math updates. The rendering is split
// into three actor-sections (Solène / Mommy / Daddy) with their own
// timelines, plus a sleep-planning footer that walks the wake-up time
// back to a recommended bedtime per parent (with a warning when the
// recommendation conflicts with a parent's stated chronotype).
// v05.05bt52 — SundayRoutineCard. Updated config + Solène wake from
// data + pump component + expanded Solène morning routine. Replaces
// bt51's hardcoded 8:00a wake with a median-morning-wake computed live
// from the user's actual sleep_up events (last 14 days), with fallback
// to 8:00 if there isn't enough data yet.
const SUNDAY_ROUTINE = {
  name: "Sunday morning",
  anchorTimeMin: 9 * 60 + 20,           // leave by 9:20a
  driveBufferMin: 30,                   // drive to church (was 15 in bt51)
  babyComponents: [
    { id: "feed",         label: "Feed",                                      dur: 25 },
    { id: "bath",         label: "Bath",                                      dur: 10, joint: ["Mommy", "Daddy"] },
    { id: "diaper_lotion",label: "Diaper change + lotion / oil",              dur: 10 },
    { id: "hair",         label: "Hair combed / styled",                      dur: 10 },
    { id: "dress",        label: "Get dressed",                               dur: 5  },
    { id: "play",         label: "Play / chill",                              dur: null },
    { id: "carseat",      label: "Car seat + load up",                        dur: 10 },
  ],
  parents: {
    Mommy: {
      label: "Mommy",
      components: [
        { id: "face",      label: "Face — wash, serum, lotion",              dur: 15, alone: true },
        { id: "hair",      label: "Hair — flat iron + extensions",            dur: 20, alone: true },
        { id: "makeup",    label: "Makeup",                                   dur: 18, alone: true },
        { id: "dress",     label: "Get dressed",                              dur: 15, alone: true },
        // Pump runs IN PARALLEL with Solène's first feed (Daddy feeds the
        // baby while Mommy pumps), so it does NOT extend Mommy's required
        // pre-wake alone-time block. Marked specially with parallelWithBabyFeed.
        { id: "pump",      label: "Pump",                                     dur: 20, parallelWithBabyFeed: true },
        // afterPump: scheduled sequentially right after pump ends (typical
        // Sunday flow: Mommy finishes pumping → cleans up → does final
        // ancillary tasks while Daddy handles Solène's bath/lotion/hair).
        { id: "ancillary", label: "Deodorant, teeth, perfume",                dur: 15, afterPump: true },
        { id: "bag",       label: "Diaper bag check",                         dur: 5,  afterPump: true },
      ],
      sleepTargetH: 8,
      chronotypeNote: "night owl — earlier wake is a stretch",
    },
    Daddy: {
      label: "Daddy",
      components: [
        { id: "shower", label: "Shower (incl. face)",                         dur: 20, alone: true },
        { id: "dress",  label: "Get dressed",                                 dur: 20 },
      ],
      sleepTargetH: 7,
      hardFadeMin: 22 * 60 + 30,        // fades at 10:30p
    },
  },
  notes: [
    "Pictures: post-church works — no pre-church buffer to spare.",
  ],
};

function SundayRoutineCard({ C, events, now }) {
  const [expanded, setExpanded] = useState(false);
  const [actorFilter, setActorFilter] = useState("all");
  // v05.05bt79 — actual-wake override. Routines schedule backward from
  // Solène's median wake (so each parent finishes alone-time exactly when
  // she wakes up). But mornings don't always match the median — sometimes
  // you wake at 7:15 instead of 6:30 and have to make up time. This state
  // is the parent's actual wake-up minute (today), and when set, the
  // pre-wake routine reflows from there. If totalAlone exceeds the time
  // available before Solène wakes, alone-time blocks compress
  // proportionally and a warning banner appears so the user can see what
  // got cut. Default null = use natural schedule (alone time ends exactly
  // when Solène wakes, parent wake = babyWakeMin - totalAlone).
  const [actualWakeMin, setActualWakeMin] = useState(null);
  const r = SUNDAY_ROUTINE;

  // ===== Compute Solène's median morning wake from her actual data =====
  const computedWakeMin = (() => {
    if (!events || events.length === 0) return null;
    const cutoff = new Date(now.getTime() - 14 * 86400000);
    const wakes = events
      .filter(e => e.type === "sleep_up" && !e.silent && new Date(e.ts) >= cutoff)
      .filter(e => {
        const h = new Date(e.ts).getHours();
        return h >= 5 && h < 12;
      })
      .map(e => new Date(e.ts));
    // Group by day so we only count one morning wake per day
    const byDay = {};
    for (const d of wakes) {
      const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
      if (!byDay[dk] || d < byDay[dk]) byDay[dk] = d;
    }
    const dayWakes = Object.values(byDay);
    if (dayWakes.length < 3) return null;
    const minutes = dayWakes.map(d => d.getHours() * 60 + d.getMinutes()).sort((a, b) => a - b);
    return minutes[Math.floor(minutes.length / 2)];
  })();
  const babyWakeMin = computedWakeMin != null ? computedWakeMin : 8 * 60;
  const wakeSource = computedWakeMin != null ? "from data" : "fallback (need 3+ mornings)";

  // ===== Helpers =====
  const fmtT = (m, withAP = true) => {
    const mod = ((m % 1440) + 1440) % 1440;
    const h12 = Math.floor(mod / 60) % 12 || 12;
    const ap = mod >= 720 ? "p" : "a";
    return `${h12}:${String(mod % 60).padStart(2, "0")}${withAP ? ap : ""}`;
  };
  const fmtRange = (from, to) => {
    if (to == null) return fmtT(from);
    const fromAP = ((from % 1440) + 1440) % 1440 >= 720 ? "p" : "a";
    const toAP = ((to % 1440) + 1440) % 1440 >= 720 ? "p" : "a";
    if (fromAP === toAP) return `${fmtT(from, false)}–${fmtT(to)}`;
    return `${fmtT(from)}–${fmtT(to)}`;
  };

  // ===== Solène's timeline (forward from babyWakeMin) =====
  const babyBlocks = [];
  let bt = babyWakeMin;
  babyBlocks.push({ from: bt, to: bt, label: "Wake up" });
  for (const c of r.babyComponents) {
    if (c.dur === null) {
      babyBlocks.push({ ...c, from: null, to: null, _flexible: true });
      continue;
    }
    babyBlocks.push({ ...c, from: bt, to: bt + c.dur });
    bt += c.dur;
  }
  // Resolve flexible play block — fills gap between previous block end and carseat start
  const carseatBlock = babyBlocks[babyBlocks.length - 1];
  carseatBlock.to = r.anchorTimeMin;
  carseatBlock.from = r.anchorTimeMin - carseatBlock.dur;
  const playBlock = babyBlocks.find(b => b._flexible);
  if (playBlock) {
    // Find the block that comes before play (last non-flexible block before carseat)
    const playIdx = babyBlocks.indexOf(playBlock);
    const prevBlock = babyBlocks[playIdx - 1];
    playBlock.from = prevBlock.to;
    playBlock.to = carseatBlock.from;
    playBlock.dur = playBlock.to - playBlock.from;
  }
  // Find the feed block (for parallel-pump scheduling)
  const feedBlock = babyBlocks.find(b => b.id === "feed");

  // Capacity check: does the schedule actually fit?
  const totalFixedBabyMin = r.babyComponents
    .filter(c => c.dur !== null)
    .reduce((s, c) => s + c.dur, 0);
  const availableForBaby = r.anchorTimeMin - babyWakeMin;
  const isTight = availableForBaby - totalFixedBabyMin < 10;
  const isOverbooked = availableForBaby < totalFixedBabyMin;

  // ===== Each parent's timeline =====
  const parentTimelines = {};
  // v05.05bt79: track which parents had their alone-time compressed because
  // actualWakeMin was set later than the natural wakeMin. Surfaced in a
  // warning banner so the user knows what got cut.
  const compressionWarnings = [];
  for (const [name, p] of Object.entries(r.parents)) {
    const aloneComps = p.components.filter(c => c.alone);
    const flexComps = p.components.filter(c => !c.alone && !c.parallelWithBabyFeed && !c.afterPump);
    const parallelComps = p.components.filter(c => c.parallelWithBabyFeed);
    const afterPumpComps = p.components.filter(c => c.afterPump);
    const totalAlone = aloneComps.reduce((s, c) => s + c.dur, 0);
    // Natural wake = exactly enough alone-time to finish at babyWakeMin.
    // If actualWakeMin is set AND it's later than natural, we have to
    // compress to still finish by babyWakeMin. If it's earlier or equal,
    // just use it as-is (parent has buffer).
    const naturalWakeMin = babyWakeMin - totalAlone;
    let wakeMin = naturalWakeMin;
    let compressionRatio = 1;
    if (actualWakeMin != null) {
      wakeMin = actualWakeMin;
      const availableMin = babyWakeMin - actualWakeMin;
      if (availableMin < totalAlone && totalAlone > 0) {
        // Compress proportionally — every alone block keeps its share but
        // duration scales by availableMin/totalAlone. Floor at 0 so a
        // crazy-late wake doesn't go negative.
        compressionRatio = Math.max(0, availableMin) / totalAlone;
        const lostMin = totalAlone - Math.max(0, availableMin);
        compressionWarnings.push({ parent: name, lostMin, ratio: compressionRatio });
      }
    }
    const blocks = [];
    let t = wakeMin;
    for (const c of aloneComps) {
      const dur = Math.max(1, Math.round(c.dur * compressionRatio));
      blocks.push({ ...c, from: t, to: t + dur, _origDur: c.dur, _compressed: compressionRatio < 1 });
      t += dur;
    }
    // Schedule parallel components (e.g. pump) during Solène's feed window
    const parallelBlocks = parallelComps.map(c => ({
      ...c,
      from: feedBlock.from,
      to: feedBlock.from + c.dur,
    }));
    const pumpEnd = parallelBlocks.length
      ? parallelBlocks[parallelBlocks.length - 1].to
      : feedBlock.to;
    let afterPumpT = pumpEnd;
    const afterPumpBlocks = afterPumpComps.map(c => {
      const block = { ...c, from: afterPumpT, to: afterPumpT + c.dur };
      afterPumpT += c.dur;
      return block;
    });
    parentTimelines[name] = {
      wakeMin, blocks, parallelBlocks, afterPumpBlocks, flexComps, totalAlone,
      totalFlex: flexComps.reduce((s, c) => s + c.dur, 0),
      compressionRatio,
    };
  }

  // ===== Bedtime math =====
  const computeBedtime = (wakeMin, sleepTargetH) => {
    const bedMin = wakeMin - sleepTargetH * 60;
    return ((bedMin % 1440) + 1440) % 1440;
  };

  // ===== Build unified timeline (sorted by time, color-coded by actor) =====
  // v05.05bt53: replaces the bt52 actor-grouped rendering with a single
  // chronological timeline. Each row inherits its color from the actor
  // performing the activity (gold = Solène, mauve = Mommy, slate = Daddy).
  // Labels are rewritten to be unambiguous in isolation: "Bath" becomes
  // "Bath Solène," "Hair" disambiguates between Mommy's and Solène's by
  // explicit prefix, etc. — so when the rows interleave, every row reads
  // self-evidently without needing actor headers.
  const SOLENE_LABELS = {
    feed:          "Feed Solène",
    bath:          "Bath Solène",
    diaper_lotion: "Diaper change + lotion for Solène",
    hair:          "Style Solène's hair",
    dress:         "Dress Solène",
    play:          "Solène plays / chills",
    carseat:       "Solène into car seat + load up",
  };
  const MOMMY_LABELS = {
    face:      "Mommy: face — wash, serum, lotion",
    hair:      "Mommy: hair — flat iron + extensions",
    makeup:    "Mommy does makeup",
    dress:     "Mommy gets dressed",
    pump:      "Mommy pumps",
    ancillary: "Mommy: deodorant, teeth, perfume",
    bag:       "Mommy: diaper bag check",
  };
  const DADDY_LABELS = {
    shower: "Daddy showers (incl. face)",
    dress:  "Daddy gets dressed",
  };
  const allBlocks = [];
  // Solène's blocks
  for (const b of babyBlocks) {
    if (b.from == null) continue;
    if (b.from === b.to && b.label === "Wake up") {
      // First wake row — synthetic, zero-duration marker
      allBlocks.push({
        from: b.from, to: null,
        label: "Solène wakes",
        accentColor: C.gold,
        actor: "Solène",
        actors: ["Solène"],
        actorPriority: 0,
      });
      continue;
    }
    // v05.05bt62: joint activities (e.g. bath) carry parent assists into
    // the actors[] array. Bath gets a "Mommy + Daddy" detail line and is
    // visible in all three filter modes (Solène, Mommy, Daddy).
    const joint = b.joint || null;
    const actors = ["Solène", ...(joint || [])];
    const detail = joint && joint.length === 2 ? "Mommy + Daddy together" : (joint && joint.length === 1 ? `${joint[0]} bathes Solène` : null);
    allBlocks.push({
      from: b.from, to: b.to,
      label: SOLENE_LABELS[b.id] || b.label,
      detail,
      accentColor: C.gold,
      actor: "Solène",
      actors,
      actorPriority: 0,
      isJoint: !!joint,
    });
  }
  // Mommy's alone-time blocks
  for (const b of parentTimelines.Mommy.blocks) {
    allBlocks.push({
      from: b.from, to: b.to,
      label: MOMMY_LABELS[b.id] || b.label,
      accentColor: C.mommy,
      actor: "Mommy",
      actors: ["Mommy"],
      actorPriority: 1,
    });
  }
  // Mommy's pump (parallel with Solène's feed)
  for (const b of parentTimelines.Mommy.parallelBlocks) {
    allBlocks.push({
      from: b.from, to: b.to,
      label: MOMMY_LABELS[b.id] || b.label,
      detail: "parallel with Solène's feed (Daddy on baby)",
      accentColor: C.mommy,
      actor: "Mommy",
      actors: ["Mommy"],
      actorPriority: 1,
    });
  }
  // Mommy's afterPump tasks (deodorant/teeth/perfume, diaper bag check)
  for (const b of parentTimelines.Mommy.afterPumpBlocks) {
    allBlocks.push({
      from: b.from, to: b.to,
      label: MOMMY_LABELS[b.id] || b.label,
      detail: b.id === "ancillary" ? "Daddy on Solène (hair / dress)" : null,
      accentColor: C.mommy,
      actor: "Mommy",
      actors: ["Mommy"],
      actorPriority: 1,
    });
  }
  // Daddy's alone-time (shower) — placed at his alone-time block
  for (const b of parentTimelines.Daddy.blocks) {
    allBlocks.push({
      from: b.from, to: b.to,
      label: DADDY_LABELS[b.id] || b.label,
      accentColor: C.daddy,
      actor: "Daddy",
      actors: ["Daddy"],
      actorPriority: 2,
    });
  }
  // Daddy's "get dressed" — schedule sequentially after his shower
  // (treats it as effectively-sequential rather than truly flexible since
  // shower → dress is the natural order). His other supporting tasks
  // remain in the flex footer.
  const daddyDressComp = r.parents.Daddy.components.find(c => c.id === "dress");
  const daddyShowerEnd = parentTimelines.Daddy.blocks.length
    ? parentTimelines.Daddy.blocks[parentTimelines.Daddy.blocks.length - 1].to
    : null;
  if (daddyDressComp && daddyShowerEnd != null) {
    allBlocks.push({
      from: daddyShowerEnd,
      to: daddyShowerEnd + daddyDressComp.dur,
      label: DADDY_LABELS[daddyDressComp.id] || daddyDressComp.label,
      accentColor: C.daddy,
      actor: "Daddy",
      actors: ["Daddy"],
      actorPriority: 2,
    });
  }
  // Sort: primary by from time, secondary by actorPriority (Solène first
  // when ties, then Mommy, then Daddy) so the most-important actor reads
  // first when several activities start at the same minute.
  allBlocks.sort((a, b) => {
    if (a.from !== b.from) return a.from - b.from;
    return a.actorPriority - b.actorPriority;
  });

  // ===== Render =====
  const teaser = `Mommy ${fmtT(parentTimelines.Mommy.wakeMin)} · Daddy ${fmtT(parentTimelines.Daddy.wakeMin)} · leave ${fmtT(r.anchorTimeMin)}`;
  const TimeRow = ({ from, to, label, detail, accentColor, isJoint }) => (
    <div style={{ display: "grid", gridTemplateColumns: "100px 1fr", gap: 10, padding: "6px 0", alignItems: "baseline", borderBottom: `1px solid ${C.line}10` }}>
      <div style={{
        fontFamily: "'JetBrains Mono', monospace", fontSize: 11,
        color: accentColor, fontWeight: 600, letterSpacing: "0.02em", whiteSpace: "nowrap",
      }}>
        {fmtRange(from, to)}
      </div>
      <div>
        <div style={{ fontSize: 13, color: C.ink, fontWeight: 500, lineHeight: 1.3, display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
          {label}
          {isJoint && (
            <span style={{
              fontSize: 8, fontWeight: 700, letterSpacing: "0.08em",
              padding: "1px 6px", borderRadius: 6,
              background: `linear-gradient(90deg, ${C.mommy}, ${C.daddy})`,
              color: "#fff", textTransform: "uppercase",
            }}>joint</span>
          )}
        </div>
        {detail && <div style={{ fontSize: 10, color: C.muted, marginTop: 2, fontStyle: "italic" }}>{detail}</div>}
      </div>
    </div>
  );

  return (
    <div style={{
      background: `linear-gradient(135deg, ${C.gold}10, ${C.paper})`,
      borderRadius: 12, marginBottom: 12,
      border: `1px solid ${C.gold}30`, overflow: "hidden",
    }}>
      <button onClick={() => setExpanded(v => !v)} style={{
        width: "100%", border: "none", background: "transparent",
        padding: "12px 14px", textAlign: "left", cursor: "pointer",
        fontFamily: "inherit", display: "flex", alignItems: "center", gap: 10,
      }}>
        <Star size={18} color={C.gold} style={{ flexShrink: 0 }} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
            <span style={{ fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase", color: C.gold, fontWeight: 700 }}>
              {r.name}
            </span>
            <span style={{
              fontSize: 9, fontWeight: 600, color: C.muted,
              background: `${C.line}15`, padding: "2px 7px", borderRadius: 8, letterSpacing: "0.04em",
            }}>
              for the family
            </span>
          </div>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.muted, marginTop: 3, letterSpacing: "0.02em" }}>
            {teaser}
          </div>
        </div>
        <ChevronRight size={18} color={C.muted} style={{
          flexShrink: 0,
          transform: expanded ? "rotate(90deg)" : "rotate(0deg)",
          transition: "transform 0.18s ease",
        }} />
      </button>
      {expanded && (
        <div style={{ padding: "0 14px 14px" }}>
          {/* Anchor bar */}
          <div style={{
            background: `${C.gold}15`, borderRadius: 8, padding: "8px 10px",
            marginBottom: 12, fontSize: 12, color: C.ink, lineHeight: 1.4,
          }}>
            <strong style={{ color: C.gold }}>⛪ Leave by {fmtT(r.anchorTimeMin)}</strong> ·
            {" "}<span style={{ color: C.muted }}>drive ~{r.driveBufferMin}min · arrival ~{fmtT(r.anchorTimeMin + r.driveBufferMin)}</span>
          </div>
          {/* Capacity warning */}
          {(isTight || isOverbooked) && (
            <div style={{
              background: `${isOverbooked ? C.accent : C.gold}15`,
              border: `1px solid ${isOverbooked ? C.accent : C.gold}40`,
              borderRadius: 8, padding: "8px 10px", marginBottom: 12,
              fontSize: 11, color: C.ink, lineHeight: 1.5,
            }}>
              <strong style={{ color: isOverbooked ? C.accent : C.gold }}>
                {isOverbooked ? "⚠ Schedule won't fit" : "⚠ Tight schedule"}
              </strong>{" "}
              — Solène's morning needs {totalFixedBabyMin}min, but only {availableForBaby}min available between her {fmtT(babyWakeMin)} wake and {fmtT(r.anchorTimeMin)} leave. {isOverbooked ? "Wake her earlier or trim the routine." : "Almost no buffer for fussiness or blowouts."}
            </div>
          )}
          {/* v05.05bt79 — actual-wake override + compression warning.
              When the parent's actual wake is later than the natural
              schedule allows, the alone-time blocks compress
              proportionally and we surface what got cut. */}
          <div style={{
            background: actualWakeMin != null ? `${C.gold}10` : C.bg,
            border: `1px solid ${actualWakeMin != null ? C.gold + "55" : C.line + "22"}`,
            borderRadius: 8, padding: "8px 12px", marginBottom: 10,
            display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10,
            flexWrap: "wrap",
          }}>
            <div style={{ fontSize: 11, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
              actual wake
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <input
                type="time"
                value={actualWakeMin != null
                  ? `${String(Math.floor(actualWakeMin / 60)).padStart(2, "0")}:${String(actualWakeMin % 60).padStart(2, "0")}`
                  : ""}
                onChange={(e) => {
                  if (!e.target.value) { setActualWakeMin(null); return; }
                  const [hh, mm] = e.target.value.split(":").map(Number);
                  if (Number.isFinite(hh) && Number.isFinite(mm)) {
                    setActualWakeMin(hh * 60 + mm);
                  }
                }}
                style={{
                  background: C.paper, color: C.ink,
                  border: `1px solid ${C.line}33`, borderRadius: 6,
                  padding: "5px 8px", fontSize: 13, fontWeight: 600,
                  fontFamily: "'JetBrains Mono', monospace",
                  outline: "none", minWidth: 90,
                }}
              />
              {actualWakeMin != null && (
                <button
                  onClick={() => setActualWakeMin(null)}
                  style={{
                    background: "transparent", border: "none",
                    color: C.muted, cursor: "pointer",
                    fontSize: 11, padding: "2px 6px",
                    fontFamily: "inherit",
                  }}>reset</button>
              )}
            </div>
          </div>

          {compressionWarnings.length > 0 && (
            <div style={{
              background: `${C.accent}10`, border: `1px solid ${C.accent}55`,
              borderRadius: 8, padding: "10px 12px", marginBottom: 10,
              fontSize: 12, lineHeight: 1.5, color: C.ink,
            }}>
              <div style={{ fontWeight: 700, color: C.accent, fontSize: 11, letterSpacing: "0.1em", textTransform: "uppercase", marginBottom: 4 }}>
                ⏱ compressed to fit
              </div>
              {compressionWarnings.map((w, i) => (
                <div key={i} style={{ marginBottom: i < compressionWarnings.length - 1 ? 4 : 0 }}>
                  <strong>{w.parent}'s</strong> alone-time cut by{" "}
                  <strong>{w.lostMin}min</strong> ({Math.round(w.ratio * 100)}% of normal duration).
                </div>
              ))}
              <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic", marginTop: 6 }}>
                Each alone block scaled proportionally so you still finish before Solène wakes at {fmtT(babyWakeMin)}.
              </div>
            </div>
          )}

          {/* Filter chips — All / Solène / Mommy / Daddy. Joint
              activities (e.g. bath) appear in any matching parent's
              filter via b.actors[]. */}
          <div style={{
            display: "flex", gap: 6, marginBottom: 10, flexWrap: "wrap",
          }}>
            {[
              { id: "all", label: "All", color: C.muted },
              { id: "Solène", label: "Solène", color: C.gold },
              { id: "Mommy", label: "Mommy", color: C.mommy },
              { id: "Daddy", label: "Daddy", color: C.daddy },
            ].map(chip => {
              const active = actorFilter === chip.id;
              return (
                <button key={chip.id} onClick={() => setActorFilter(chip.id)} style={{
                  background: active ? chip.color : "transparent",
                  color: active ? "#fff" : chip.color,
                  border: `1px solid ${chip.color}${active ? "" : "55"}`,
                  borderRadius: 14, padding: "4px 12px",
                  fontSize: 11, fontWeight: 600, cursor: "pointer",
                  fontFamily: "inherit", letterSpacing: "0.04em",
                  transition: "all 0.15s",
                }}>
                  {chip.label}
                </button>
              );
            })}
          </div>
          {/* Time-ordered timeline */}
          <div>
            {allBlocks
              .filter(b => actorFilter === "all" || (b.actors || [b.actor]).includes(actorFilter))
              .map((b, i) => (
                <TimeRow key={i}
                  from={b.from} to={b.to}
                  label={b.label}
                  detail={b.detail}
                  accentColor={b.accentColor}
                  isJoint={b.isJoint} />
              ))}
          </div>
          {/* Mommy's flex tasks footer */}
          {parentTimelines.Mommy.flexComps.length > 0 && (
            <div style={{
              fontSize: 11, color: C.muted, fontStyle: "italic",
              marginTop: 10, padding: "8px 10px",
              background: `${C.mommy}10`, borderRadius: 6, lineHeight: 1.4,
              borderLeft: `3px solid ${C.mommy}`,
            }}>
              <strong style={{ fontStyle: "normal", color: C.mommy }}>Mommy's flex tasks ({parentTimelines.Mommy.totalFlex}m):</strong>{" "}
              {parentTimelines.Mommy.flexComps.map(c => c.label.toLowerCase()).join(" · ")}
              {" "}— distributed during the {fmtT(feedBlock.to)}–{fmtT(r.anchorTimeMin)} window.
            </div>
          )}
          {/* Sleep / bedtime planning */}
          <div style={{
            marginTop: 14, padding: "12px 14px",
            background: `${C.ink}06`, borderRadius: 10, border: `1px solid ${C.line}20`,
          }}>
            <div style={{
              fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase",
              color: C.ink, fontWeight: 700, marginBottom: 8, opacity: 0.7,
            }}>
              ← Bedtime planning (Saturday night)
            </div>
            {(() => {
              const mommyBed = computeBedtime(parentTimelines.Mommy.wakeMin, r.parents.Mommy.sleepTargetH);
              return (
                <>
                  <div style={{ display: "grid", gridTemplateColumns: "84px 1fr", gap: 10, padding: "5px 0", alignItems: "baseline" }}>
                    <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 14, color: C.mommy, fontStyle: "italic", fontWeight: 600 }}>
                      Mommy
                    </div>
                    <div style={{ fontSize: 12, color: C.ink, lineHeight: 1.4 }}>
                      Bed by <strong>{fmtT(mommyBed)}</strong> for {r.parents.Mommy.sleepTargetH}h sleep
                      <div style={{ fontSize: 10, color: C.accent, marginTop: 2, fontStyle: "italic" }}>
                        ⚠ {r.parents.Mommy.chronotypeNote} — Saturday afternoon nap or earlier wind-down may help.
                      </div>
                    </div>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "84px 1fr", gap: 10, padding: "5px 0", alignItems: "baseline" }}>
                    <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 14, color: C.daddy, fontStyle: "italic", fontWeight: 600 }}>
                      Daddy
                    </div>
                    <div style={{ fontSize: 12, color: C.ink, lineHeight: 1.4 }}>
                      Plan bed by <strong>{fmtT(r.parents.Daddy.hardFadeMin)}</strong> (his usual fade)
                      <div style={{ fontSize: 10, color: "#5C8E5C", marginTop: 2, fontStyle: "italic" }}>
                        ✓ matches his pattern — gives ~{Math.round((parentTimelines.Daddy.wakeMin + 1440 - r.parents.Daddy.hardFadeMin) / 60)}h before {fmtT(parentTimelines.Daddy.wakeMin)} wake.
                      </div>
                    </div>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "84px 1fr", gap: 10, padding: "5px 0", alignItems: "baseline" }}>
                    <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 14, color: C.gold, fontStyle: "italic", fontWeight: 600 }}>
                      Solène
                    </div>
                    <div style={{ fontSize: 12, color: C.ink, lineHeight: 1.4 }}>
                      Usual <strong>9:30p</strong> bedtime — no change needed for Sunday.
                    </div>
                  </div>
                </>
              );
            })()}
          </div>
          {/* Notes */}
          <div style={{
            fontSize: 11, color: C.muted, fontStyle: "italic",
            marginTop: 12, lineHeight: 1.5,
            padding: "8px 10px",
            background: `${C.line}10`, borderRadius: 6,
            borderLeft: `2px solid ${C.line}40`,
          }}>
            {r.notes.map((n, i) => (
              <div key={i}>{n}</div>
            ))}
            <div style={{ marginTop: 4, fontSize: 10, opacity: 0.8 }}>
              Solène's wake {wakeSource} · drive 30min · pump runs parallel with feed.
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// v05.05bt146 — AllTasksView. Flat list of every task for the current
// user, grouped by status (scheduled / unscheduled / draft / done).
// Tap a row → opens the centered edit modal (handled by parent).
// Filter chips at top narrow the list; search box narrows by title.
function AllTasksView({ C, tasks, setTasks, currentUser, now, onEditTask, onBack, hideHeader }) {
  const [filter, setFilter] = useState("all"); // all | scheduled | unscheduled | draft | done
  const [search, setSearch] = useState("");
  // v05.05bt349 — Per chat: 'have a high priority work item list
  // further subdivided by the TYPE of task — replicate in the app.'
  // Two view modes for ALL filter: 'category' (Monday-style task
  // groups, default) and 'status' (legacy scheduled/unscheduled split).
  // Each user-facing group (LIMS · 35 / GRANT · 1 / etc.) is
  // collapsible; collapsed state persisted in-session.
  const [viewMode, setViewMode] = useState("category");
  // v05.05bt351 — Per chat: 'now instead of a long list we have
  // categories and can filter by regret score and deep work.' Two
  // filter chips at the top of the category view: high-regret-only
  // (R≥4) and deep-only.
  const [regretHighOnly, setRegretHighOnly] = useState(false);
  const [deepOnly, setDeepOnly] = useState(false);
  // v05.05bt351 — Per chat: 'Group-level bulk select.' Set of task IDs
  // currently flagged for bulk action (delete only for now).
  const [bulkSelected, setBulkSelected] = useState(new Set());
  const onBulkSelect = (ids) => {
    setBulkSelected(prev => {
      const next = new Set(prev);
      // If all already selected, deselect them; otherwise select all.
      const allIn = ids.every(id => next.has(id));
      if (allIn) ids.forEach(id => next.delete(id));
      else ids.forEach(id => next.add(id));
      return next;
    });
  };
  const onClearBulk = () => setBulkSelected(new Set());
  const onBulkDelete = () => {
    if (bulkSelected.size === 0) return;
    if (typeof window !== "undefined" && !window.confirm(`Delete ${bulkSelected.size} task${bulkSelected.size === 1 ? "" : "s"}? This can't be undone.`)) return;
    setTasks(prev => prev.filter(t => !bulkSelected.has(t.id)));
    setBulkSelected(new Set());
  };

  // v05.05bt353 — Per chat: 'sometimes there are duplicates so need
  // to check for that and remove them.' Detect tasks with identical
  // titles (case-insensitive, trimmed, completedAt-blind so an
  // open + done copy count as dupes). Keeps newest, offers to
  // remove the rest.
  const duplicateGroups = useMemo(() => {
    const buckets = new Map();
    for (const t of tasks) {
      if (t.completedAt) continue; // ignore done items in dedupe
      const key = (t.title || "").trim().toLowerCase();
      if (!key) continue;
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(t);
    }
    return Array.from(buckets.entries())
      .filter(([_, items]) => items.length >= 2)
      .map(([key, items]) => ({
        key, title: items[0].title,
        items: items.slice().sort((a, b) =>
          new Date(b.createdAt || 0) - new Date(a.createdAt || 0)
        ),
      }));
  }, [tasks]);
  const removeDuplicates = () => {
    if (duplicateGroups.length === 0) return;
    // v05.05bt356 — Inline two-tap. First tap arms; second commits.
    if (!mergeArmed) {
      setMergeArmed(true);
      if (mergeArmTimerRef.current) clearTimeout(mergeArmTimerRef.current);
      mergeArmTimerRef.current = setTimeout(() => setMergeArmed(false), 4000);
      return;
    }
    if (mergeArmTimerRef.current) clearTimeout(mergeArmTimerRef.current);
    setMergeArmed(false);
    const toRemove = new Set();
    for (const g of duplicateGroups) {
      // Keep first (newest); remove rest.
      for (let i = 1; i < g.items.length; i++) toRemove.add(g.items[i].id);
    }
    setTasks(prev => prev.filter(t => !toRemove.has(t.id)));
  };
  // v05.05bt349/350 — Per chat: 'Collapse categories by default.'
  // Switched from collapsedGroups (start expanded) to expandedGroups
  // (start collapsed). Counts are visible in headers so user can scan
  // without expanding.
  const [expandedGroups, setExpandedGroups] = useState(new Set());
  const toggleGroup = (key) => {
    setExpandedGroups(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };
  const isGroupOpen = (key) => expandedGroups.has(key);
  // v05.05bt353 — Per chat: 'under the all tasks, let me drag to
  // reorder categories or let me choose how the categories are
  // ordered.' Custom sort order persisted to localStorage. Default
  // sort (count desc / UNCATEGORIZED last) used for any group not in
  // the saved order; groups in saved order come first in saved
  // position. Reorder via ↑↓ arrows on each group header (drag is
  // unreliable on touch screens, so explicit buttons instead).
  const [taskGroupOrder, setTaskGroupOrderState] = useState(() => {
    try {
      const raw = localStorage.getItem("ll:taskGroupOrder");
      const parsed = raw ? JSON.parse(raw) : null;
      return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  });
  const setTaskGroupOrder = (next) => {
    setTaskGroupOrderState(next);
    try { localStorage.setItem("ll:taskGroupOrder", JSON.stringify(next)); } catch {}
  };
  // v05.05bt357 — Per chat: 'the move up or down to move category
  // and the edit buttons...also it doesn't do anything.' Rewrote
  // moveGroup to operate on the currently-rendered order: if the
  // saved order is partial, snapshot the visual order into the
  // saved array first so subsequent swaps reflect what the user
  // actually sees.
  const moveGroup = (key, delta, visibleOrder) => {
    // visibleOrder is the array of keys in current render order
    // (excluding UNCATEGORIZED and _DONE). Use it as the canonical
    // starting point so the user's tap moves things relative to
    // what's on screen.
    let cur = visibleOrder ? visibleOrder.slice() : taskGroupOrder.slice();
    const idx = cur.indexOf(key);
    if (idx < 0) return;
    const newIdx = idx + delta;
    if (newIdx < 0 || newIdx >= cur.length) return;
    const tgt = cur[newIdx];
    cur[newIdx] = key;
    cur[idx] = tgt;
    setTaskGroupOrder(cur);
  };
  // v05.05bt357 — Inline rename state. window.prompt is unreliable
  // in iOS PWAs (same reason MERGE button needed reworking).
  const [renamingGroupKey, setRenamingGroupKey] = useState(null);
  const [renamingGroupValue, setRenamingGroupValue] = useState("");
  const startRename = (oldKey) => {
    setRenamingGroupKey(oldKey);
    setRenamingGroupValue(oldKey);
  };
  const commitRename = () => {
    const oldKey = renamingGroupKey;
    const next = (renamingGroupValue || "").trim().toUpperCase();
    setRenamingGroupKey(null);
    setRenamingGroupValue("");
    if (!oldKey || !next || next === oldKey) return;
    setTasks(prev => prev.map(t => {
      const key = String(t.taskGroup || inferTaskGroup(t.title) || "UNCATEGORIZED").toUpperCase();
      if (key !== oldKey) return t;
      return { ...t, taskGroup: next };
    }));
    if (taskGroupOrder.includes(oldKey)) {
      setTaskGroupOrder(taskGroupOrder.map(k => k === oldKey ? next : k));
    }
  };
  const cancelRename = () => {
    setRenamingGroupKey(null);
    setRenamingGroupValue("");
  };
  // v05.05bt353 — DEPRECATED renameGroup helper kept as a no-op
  // wrapper so any stray callers do not crash.
  const renameGroup = startRename;
  // v05.05bt152 — Two-tap delete state, scoped to this view only.
  const [pendingDeleteId, setPendingDeleteId] = useState(null);
  const pendingDeleteTimerRef = useRef(null);
  // v05.05bt356 — Per chat: 'in the all tasks, when i click to merge
  // duplicates then nothing happens.' window.confirm is unreliable in
  // iOS Safari PWAs. Inline two-tap: first tap arms, second commits.
  const [mergeArmed, setMergeArmed] = useState(false);
  const mergeArmTimerRef = useRef(null);
  const userTint = currentUser === "Mommy" ? C.mommy : C.daddy;

  const today = new Date(now); today.setHours(0,0,0,0);
  const dayMs = 24 * 60 * 60 * 1000;
  const last30 = today.getTime() - 30 * dayMs;

  // Status derivation per task
  const enrich = (t) => {
    if (t.completedAt) return { ...t, _status: "done", _statusLabel: "DONE", _statusColor: "#7B9B6E" };
    if (t.drawer)      return { ...t, _status: "draft", _statusLabel: "DRAFT", _statusColor: "#C18D7A" };
    if (t.scheduledTime) return { ...t, _status: "scheduled", _statusLabel: "SCHEDULED", _statusColor: C.mommy };
    return { ...t, _status: "unscheduled", _statusLabel: "UNSCHEDULED", _statusColor: C.muted };
  };

  const all = (tasks || [])
    .filter(t => !t.ownerName || t.ownerName === currentUser)
    .map(enrich)
    .filter(t => {
      if (t._status === "done" && t.completedAt) {
        const ts = new Date(t.completedAt).getTime();
        if (ts < last30) return false;
      }
      return true;
    });

  // Apply filter
  const filtered = all.filter(t => {
    if (filter !== "all" && t._status !== filter) return false;
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      if (!t.title.toLowerCase().includes(q)) return false;
    }
    // v05.05bt351 — Regret-≥4 and deep-only chips.
    if (regretHighOnly && (t.regretScore || 0) < 4) return false;
    if (deepOnly && normalizeFocus(t.focusLevel) !== "deep") return false;
    return true;
  });

  // v05.05bt349 — Category-mode grouping. When viewMode === 'category'
  // AND filter === 'all' (no specific status filter) AND no active
  // search, render Monday.com-style groups. Otherwise fall through to
  // the legacy status-based grouping.
  const useCategoryGroups = viewMode === "category" && filter === "all" && !search.trim();
  // Group by status (for ALL filter, show groups; for specific filter just flat)
  const statusGroups = filter === "all"
    ? [
        { key: "scheduled", label: "Scheduled", color: C.mommy, items: filtered.filter(t => t._status === "scheduled") },
        { key: "unscheduled", label: "Unscheduled", color: C.muted, items: filtered.filter(t => t._status === "unscheduled") },
        { key: "draft", label: "Brain dump", color: "#C18D7A", items: filtered.filter(t => t._status === "draft") },
        { key: "done", label: "Done · last 30 days", color: "#7B9B6E", items: filtered.filter(t => t._status === "done") },
      ].filter(g => g.items.length > 0)
    : [{ key: filter, label: filter, color: C.mommy, items: filtered }];

  // Build category groups: bucket tasks by taskGroup (or live-infer
  // for legacy tasks that pre-date bt349 and have no field set),
  // sort buckets by count desc then alphabetical, completed tasks
  // get their own DONE bucket at the bottom.
  const categoryGroupsBuilt = (() => {
    if (!useCategoryGroups) return null;
    const buckets = new Map();
    let doneItems = [];
    for (const t of filtered) {
      if (t._status === "done") { doneItems.push(t); continue; }
      const raw = t.taskGroup || inferTaskGroup(t.title) || "UNCATEGORIZED";
      const key = String(raw).toUpperCase();
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(t);
    }
    // Sort within each bucket: regret desc, then focus deep>shallow,
    // then created asc.
    for (const items of buckets.values()) {
      items.sort((a, b) => {
        if ((b.regretScore || 0) !== (a.regretScore || 0)) {
          return (b.regretScore || 0) - (a.regretScore || 0);
        }
        const fa = normalizeFocus(a.focusLevel) === "deep" ? 0 : 1;
        const fb = normalizeFocus(b.focusLevel) === "deep" ? 0 : 1;
        if (fa !== fb) return fa - fb;
        return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);
      });
    }
    // Build sorted group list: count desc, then alphabetical for ties.
    // UNCATEGORIZED always lands at the bottom regardless of count.
    const entries = Array.from(buckets.entries())
      .map(([key, items]) => ({
        key,
        label: key,
        color: key === "UNCATEGORIZED" ? C.muted : C.mommy,
        items,
        isUncat: key === "UNCATEGORIZED",
      }));
    // v05.05bt353 — Apply custom order (from up/down arrow reorder)
    // before count-desc fallback. Saved keys come first in saved
    // position; new groups (not yet reordered) fall back to count
    // desc / alphabetical. UNCATEGORIZED always last.
    entries.sort((a, b) => {
      if (a.isUncat !== b.isUncat) return a.isUncat ? 1 : -1;
      const ai = taskGroupOrder.indexOf(a.key);
      const bi = taskGroupOrder.indexOf(b.key);
      if (ai !== -1 || bi !== -1) {
        if (ai === -1) return 1;
        if (bi === -1) return -1;
        return ai - bi;
      }
      if (b.items.length !== a.items.length) return b.items.length - a.items.length;
      return a.label.localeCompare(b.label);
    });
    if (doneItems.length > 0) {
      doneItems.sort((a, b) => new Date(b.completedAt) - new Date(a.completedAt));
      entries.push({
        key: "_DONE",
        label: "Done · last 30 days",
        color: "#7B9B6E",
        items: doneItems,
        isDone: true,
      });
    }
    return entries;
  })();

  const groups = useCategoryGroups ? categoryGroupsBuilt : statusGroups;

  // Sort within groups: scheduled by time asc, others by regret desc then createdAt asc.
  // Category-mode groups already sort themselves above; skip them here.
  if (!useCategoryGroups && groups) {
    for (const g of groups) {
      if (g.key === "scheduled") {
        g.items.sort((a, b) => (a.scheduledTime || "").localeCompare(b.scheduledTime || ""));
      } else if (g.key === "done") {
        g.items.sort((a, b) => new Date(b.completedAt) - new Date(a.completedAt));
      } else {
        g.items.sort((a, b) => {
          if (b.regretScore !== a.regretScore) return (b.regretScore || 0) - (a.regretScore || 0);
          return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);
        });
      }
    }
  }

  const totalCount = all.length;
  const filterChips = [
    { key: "all",          label: "ALL",         n: totalCount },
    { key: "scheduled",    label: "SCHEDULED",   n: all.filter(t => t._status === "scheduled").length },
    { key: "unscheduled",  label: "UNSCHEDULED", n: all.filter(t => t._status === "unscheduled").length },
    { key: "draft",        label: "DRAFT",       n: all.filter(t => t._status === "draft").length },
    { key: "done",         label: "DONE",        n: all.filter(t => t._status === "done").length },
  ];

  const fmtRegretColor = (n) => n >= 5 ? "#A04848" : n === 4 ? "#C18D7A" : n === 3 ? C.gold : C.muted;
  // v05.05bt155 — binary focus
  const fmtFocusColor = (f) => FOCUS_COLOR[normalizeFocus(f)];
  const fmtScheduled = (t) => {
    if (!t.scheduledTime) return "—";
    const [h, m] = t.scheduledTime.split(":").map(Number);
    const ap = h >= 12 ? "p" : "a";
    const h12 = h % 12 || 12;
    return m === 0 ? `${h12}${ap}` : `${h12}:${String(m).padStart(2, "0")}${ap}`;
  };
  const fmtDone = (t) => {
    if (!t.completedAt) return "";
    const d = new Date(t.completedAt);
    const diffDays = Math.floor((today.getTime() - new Date(d).setHours(0,0,0,0)) / dayMs);
    if (diffDays === 0) return "today";
    if (diffDays === 1) return "yesterday";
    return `${diffDays}d ago`;
  };

  return (
    <div>
      {/* v05.05bt286 — Back link to Mommy's Day. Per chat: All Tasks
          pill removed — this view is now reached via discrete link
          below today's task pile. */}
      {onBack && (
        <button
          onClick={onBack}
          style={{
            background: "transparent", border: "none", padding: "0 4px 6px",
            cursor: "pointer", color: C.mommy,
            fontFamily: "'Cormorant Garamond', serif",
            fontStyle: "italic", fontSize: 12.5,
          }}>← Back to Mommy's Day</button>
      )}
      {/* v05.05bt357 — Per chat: 'still the redundant titles at the
          top of the card with all tasks across days appearing
          twice.' Drop the internal h1 when this view is rendered
          inside a ModalShell that already shows the title. */}
      {!hideHeader && (
      <div style={{ marginBottom: 14, padding: "0 4px" }}>
        <h1 style={{
          fontFamily: "'Cormorant Garamond', serif",
          fontStyle: "italic", fontWeight: 500, fontSize: 30,
          color: C.ink, margin: 0, lineHeight: 1.05,
        }}>All tasks across days</h1>
        <div style={{
          marginTop: 4,
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 11, color: C.muted,
          letterSpacing: "0.08em",
        }}>
          {totalCount} total · search · filter · done history
        </div>
      </div>
      )}
      {hideHeader && (
        <div style={{
          marginTop: 0, marginBottom: 10, padding: "0 4px",
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 11, color: C.muted,
          letterSpacing: "0.08em",
        }}>
          {totalCount} total · search · filter · done history
        </div>
      )}

      {/* v05.05bt351/352 — Bulk action bar removed alongside the
          select-all chip per bt352 chat. Single-row delete is via
          EditTaskModal's delete button. */}

      {/* Search */}
      <input
        type="text"
        value={search}
        onChange={e => setSearch(e.target.value)}
        placeholder="Search…"
        style={{
          width: "100%",
          background: C.paper,
          border: `1px solid ${C.line}55`,
          borderRadius: 10, padding: "9px 14px",
          fontSize: 13, color: C.ink, marginBottom: 10,
          fontFamily: "'Cormorant Garamond', serif",
          fontStyle: "italic",
        }}
      />

      {/* Filter chips */}
      <div style={{
        display: "flex", gap: 5, marginBottom: 10,
        flexWrap: "wrap",
      }}>
        {filterChips.map(c => (
          <button
            key={c.key}
            onClick={() => setFilter(c.key)}
            style={{
              background: filter === c.key ? userTint : "transparent",
              color: filter === c.key ? "#fff" : "#7C6B5A",
              border: `1px solid ${filter === c.key ? userTint : C.line + "55"}`,
              borderRadius: 999, padding: "4px 10px",
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: 10, fontWeight: 700,
              letterSpacing: "0.14em",
              cursor: "pointer",
              display: "inline-flex", alignItems: "center", gap: 5,
            }}>
            {c.label}
            <span style={{ opacity: 0.7 }}>{c.n}</span>
          </button>
        ))}
      </div>

      {/* v05.05bt353/356 — Duplicate-detection banner. First tap
          arms (label flips to "TAP TO CONFIRM"); second tap commits. */}
      {duplicateGroups.length > 0 && (() => {
        const dupCount = duplicateGroups.reduce((s, g) => s + g.items.length - 1, 0);
        return (
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); removeDuplicates(); }}
            style={{
              width: "100%",
              background: mergeArmed ? `${C.gold}33` : `${C.gold}1a`,
              border: `1.5px solid ${mergeArmed ? C.gold : C.gold + "55"}`,
              borderRadius: 8,
              padding: "10px 12px",
              marginBottom: 10,
              cursor: "pointer", textAlign: "left",
              display: "flex", alignItems: "center", gap: 8,
              fontFamily: "inherit",
              touchAction: "manipulation",
              WebkitTapHighlightColor: "transparent",
              WebkitAppearance: "none",
            }}>
            <span style={{
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: 9.5, letterSpacing: "0.16em",
              fontWeight: 700, color: C.gold, textTransform: "uppercase",
            }}>↳ duplicates</span>
            <span style={{
              fontFamily: "'Cormorant Garamond', serif",
              fontStyle: "italic", fontSize: 13,
              color: C.ink, flex: 1,
            }}>
              {mergeArmed
                ? `Remove ${dupCount} older cop${dupCount === 1 ? "y" : "ies"}? Tap again to confirm.`
                : `${duplicateGroups.length} title${duplicateGroups.length === 1 ? "" : "s"} appear${duplicateGroups.length === 1 ? "s" : ""} more than once`}
            </span>
            <span style={{
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: 10, letterSpacing: "0.08em",
              fontWeight: 800, color: mergeArmed ? "#fff" : C.gold,
              background: mergeArmed ? C.gold : "transparent",
              padding: mergeArmed ? "3px 8px" : 0,
              borderRadius: 4,
            }}>{mergeArmed ? "CONFIRM" : "MERGE ↗"}</span>
          </button>
        );
      })()}

      {/* v05.05bt351 — Quick filter chips. */}
      <div style={{
        display: "flex", gap: 6, marginBottom: 10, alignItems: "center",
        flexWrap: "wrap",
      }}>
        <span style={{
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 8.5, letterSpacing: "0.22em",
          color: C.muted, fontWeight: 700,
          textTransform: "uppercase",
        }}>Filter</span>
        <button onClick={() => setRegretHighOnly(v => !v)} style={{
          background: regretHighOnly ? `${C.accent}22` : "transparent",
          color: regretHighOnly ? C.accent : C.muted,
          border: `1px solid ${regretHighOnly ? C.accent + "66" : C.line + "33"}`,
          borderRadius: 6, padding: "3px 9px",
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 9, fontWeight: 700, letterSpacing: "0.10em",
          cursor: "pointer", textTransform: "uppercase",
        }} title="Show only tasks with regret ≥ 4">
          R≥4 {regretHighOnly ? "✓" : ""}
        </button>
        <button onClick={() => setDeepOnly(v => !v)} style={{
          background: deepOnly ? `${FOCUS_COLOR.deep}22` : "transparent",
          color: deepOnly ? FOCUS_COLOR.deep : C.muted,
          border: `1px solid ${deepOnly ? FOCUS_COLOR.deep + "66" : C.line + "33"}`,
          borderRadius: 6, padding: "3px 9px",
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 9, fontWeight: 700, letterSpacing: "0.10em",
          cursor: "pointer", textTransform: "uppercase",
        }} title="Show only deep-focus tasks">
          🧠 deep {deepOnly ? "✓" : ""}
        </button>
        {(regretHighOnly || deepOnly) && (
          <button onClick={() => { setRegretHighOnly(false); setDeepOnly(false); }} style={{
            marginLeft: 2, background: "transparent",
            color: C.muted, border: "none",
            fontFamily: "'Cormorant Garamond', serif",
            fontStyle: "italic", fontSize: 11.5,
            cursor: "pointer",
          }}>clear</button>
        )}
        <span style={{
          marginLeft: "auto",
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 9.5, color: C.muted, opacity: 0.7,
        }}>{filtered.length}</span>
      </div>

      {/* v05.05bt349 — Group-by toggle */}
      {filter === "all" && !search.trim() && (
        <div style={{
          display: "flex", gap: 6, marginBottom: 14,
          alignItems: "center",
        }}>
          <span style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 8.5, letterSpacing: "0.22em",
            color: C.muted, fontWeight: 700,
            textTransform: "uppercase",
          }}>Group by</span>
          <button onClick={() => setViewMode("category")} style={{
            background: viewMode === "category" ? `${userTint}22` : "transparent",
            color: viewMode === "category" ? userTint : C.muted,
            border: `1px solid ${viewMode === "category" ? userTint + "55" : C.line + "33"}`,
            borderRadius: 6, padding: "3px 9px",
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 9, fontWeight: 700, letterSpacing: "0.10em",
            cursor: "pointer", textTransform: "uppercase",
          }}>Category</button>
          <button onClick={() => setViewMode("status")} style={{
            background: viewMode === "status" ? `${userTint}22` : "transparent",
            color: viewMode === "status" ? userTint : C.muted,
            border: `1px solid ${viewMode === "status" ? userTint + "55" : C.line + "33"}`,
            borderRadius: 6, padding: "3px 9px",
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 9, fontWeight: 700, letterSpacing: "0.10em",
            cursor: "pointer", textTransform: "uppercase",
          }}>Status</button>
          {useCategoryGroups && expandedGroups.size > 0 && (
            <button onClick={() => setExpandedGroups(new Set())} style={{
              marginLeft: "auto",
              background: "transparent",
              color: C.muted,
              border: "none",
              fontFamily: "'Cormorant Garamond', serif",
              fontStyle: "italic", fontSize: 12,
              cursor: "pointer",
            }}>collapse all</button>
          )}
          {useCategoryGroups && expandedGroups.size === 0 && categoryGroupsBuilt && categoryGroupsBuilt.length > 1 && (
            <button onClick={() => {
              setExpandedGroups(new Set(categoryGroupsBuilt.map(g => g.key)));
            }} style={{
              marginLeft: "auto",
              background: "transparent",
              color: C.gold,
              border: "none",
              fontFamily: "'Cormorant Garamond', serif",
              fontStyle: "italic", fontSize: 12,
              cursor: "pointer",
            }}>expand all</button>
          )}
        </div>
      )}

      {/* Empty state */}
      {filtered.length === 0 && (
        <div style={{
          textAlign: "center", padding: "30px 14px",
          fontFamily: "'Cormorant Garamond', serif",
          fontStyle: "italic", color: C.muted, fontSize: 14,
        }}>
          {search.trim()
            ? `Nothing matches "${search}".`
            : filter === "all" ? "No tasks yet. Add one from Mommy's Day."
            : `Nothing in ${filterChips.find(c => c.key === filter)?.label.toLowerCase()}.`}
        </div>
      )}

      {/* Groups */}
      {(() => {
        // v05.05bt357 — Compute canonical visible-order array for
        // moveGroup so swaps reflect what the user sees, regardless
        // of which entries are in the saved order vs not.
        const visibleGroupOrder = groups
          .filter(g => !g.isDone && !g.isUncat)
          .map(g => g.key);
        return groups.map(g => (
        <div key={g.key} style={{ marginBottom: 18 }}>
          {useCategoryGroups && !g.isDone && (
            <div style={{
              width: "100%",
              display: "flex", alignItems: "center", gap: 6,
              padding: "10px 4px 8px", marginBottom: 4,
            }}>
              <button
                onClick={() => toggleGroup(g.key)}
                style={{
                  flex: 1,
                  background: "transparent", border: "none",
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 11, letterSpacing: "0.20em", textTransform: "uppercase",
                  fontWeight: 700, color: g.color,
                  padding: 0,
                  display: "flex", alignItems: "center", gap: 10,
                  cursor: "pointer", textAlign: "left",
                  minWidth: 0,
                }}>
                <span style={{
                  display: "inline-block",
                  width: 12, fontSize: 12, opacity: 0.7,
                  transform: !isGroupOpen(g.key) ? "rotate(-90deg)" : "rotate(0deg)",
                  transition: "transform 0.15s",
                }}>▾</span>
                {/* v05.05bt357 — Inline rename via tap on label.
                    When this group is in renaming state, swap to
                    text input. Enter or blur commits; Esc cancels. */}
                {renamingGroupKey === g.key ? (
                  <input
                    autoFocus
                    type="text"
                    value={renamingGroupValue}
                    onChange={(e) => setRenamingGroupValue(e.target.value)}
                    onBlur={commitRename}
                    onClick={(e) => e.stopPropagation()}
                    onKeyDown={(e) => {
                      e.stopPropagation();
                      if (e.key === "Enter") { e.preventDefault(); commitRename(); }
                      else if (e.key === "Escape") { e.preventDefault(); cancelRename(); }
                    }}
                    style={{
                      flex: 1, minWidth: 80,
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: 11, fontWeight: 700,
                      letterSpacing: "0.20em", textTransform: "uppercase",
                      color: g.color,
                      background: `${g.color}10`,
                      border: `1px solid ${g.color}55`,
                      borderRadius: 4, padding: "2px 6px",
                      outline: "none",
                    }}
                  />
                ) : (
                  <span>{g.label}</span>
                )}
                <span style={{
                  opacity: 0.95,
                  background: `${g.color}1f`,
                  color: g.color,
                  borderRadius: 5,
                  padding: "2px 8px",
                  fontSize: 11,
                  fontWeight: 800,
                  letterSpacing: "0.02em",
                }}>{g.items.length}</span>
              </button>
              {/* v05.05bt353/357 — Subtle reorder + rename affordances.
                  Per chat (bt357): 'the move up or down to move
                  category and the edit buttons i feel like should be
                  more subtle.' Borderless minimal icons, muted
                  color, only visible on the header. */}
              {!g.isUncat && renamingGroupKey !== g.key && (
                <div style={{
                  display: "flex", alignItems: "center", gap: 1,
                  opacity: 0.55,
                }}>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      moveGroup(g.key, -1, visibleGroupOrder);
                    }}
                    title="Move group up"
                    aria-label="Move group up"
                    style={{
                      background: "transparent", border: "none",
                      padding: "4px 5px", lineHeight: 1,
                      fontSize: 11, color: C.muted, cursor: "pointer",
                      fontFamily: "'JetBrains Mono', monospace",
                      minWidth: 22, minHeight: 22,
                      touchAction: "manipulation",
                      WebkitTapHighlightColor: "transparent",
                    }}>↑</button>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      moveGroup(g.key, 1, visibleGroupOrder);
                    }}
                    title="Move group down"
                    aria-label="Move group down"
                    style={{
                      background: "transparent", border: "none",
                      padding: "4px 5px", lineHeight: 1,
                      fontSize: 11, color: C.muted, cursor: "pointer",
                      fontFamily: "'JetBrains Mono', monospace",
                      minWidth: 22, minHeight: 22,
                      touchAction: "manipulation",
                      WebkitTapHighlightColor: "transparent",
                    }}>↓</button>
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); startRename(g.key); }}
                    title="Rename group"
                    aria-label="Rename group"
                    style={{
                      background: "transparent", border: "none",
                      padding: "4px 5px", lineHeight: 1,
                      fontSize: 10.5, color: C.muted, cursor: "pointer",
                      fontFamily: "inherit",
                      minWidth: 22, minHeight: 22,
                      touchAction: "manipulation",
                      WebkitTapHighlightColor: "transparent",
                    }}>✎</button>
                </div>
              )}
              <span style={{ flex: 0, height: 1, background: `${g.color}33` }} />
            </div>
          )}
          {filter === "all" && (g.isDone || (!useCategoryGroups)) && (
            <button
              onClick={() => toggleGroup(g.key)}
              style={{
                width: "100%",
                background: "transparent", border: "none",
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 11, letterSpacing: "0.20em", textTransform: "uppercase",
                fontWeight: 700, color: g.color,
                padding: "10px 4px 8px", marginBottom: 4,
                display: "flex", alignItems: "center", gap: 10,
                cursor: "pointer", textAlign: "left",
              }}>
              <span style={{
                display: "inline-block",
                width: 12, fontSize: 12, opacity: 0.7,
                transform: !isGroupOpen(g.key) ? "rotate(-90deg)" : "rotate(0deg)",
                transition: "transform 0.15s",
              }}>▾</span>
              <span>{g.label}</span>
              <span style={{
                opacity: 0.95,
                background: `${g.color}1f`,
                color: g.color,
                borderRadius: 5,
                padding: "2px 8px",
                fontSize: 11,
                fontWeight: 800,
                letterSpacing: "0.02em",
              }}>{g.items.length}</span>
              <span style={{ flex: 1, height: 1, background: `${g.color}33` }} />
            </button>
          )}
          {(!useCategoryGroups || isGroupOpen(g.key)) && g.items.map(t => {
            const rail = t._status === "done" ? "#7B9B6E"
              : t._status === "draft" ? "#C18D7A"
              : t._status === "unscheduled" ? C.muted
              : C.mommy;
            const isSelected = bulkSelected.has(t.id);
            return (
              <div key={t.id}
                onClick={() => onEditTask(t)}
                style={{
                  position: "relative",
                  display: "grid",
                  gridTemplateColumns: "54px 1fr auto",
                  gap: 10, padding: "9px 8px 9px 12px",
                  borderBottom: `1px solid ${C.line}22`,
                  alignItems: "center",
                  cursor: "pointer",
                  background: isSelected ? `${C.accent}10` : "transparent",
                }}>
                <div style={{
                  position: "absolute",
                  left: 0, top: 6, bottom: 6, width: 2,
                  background: rail, borderRadius: 1,
                }} />
                <div style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 10, fontWeight: 600,
                  color: t._status === "scheduled" ? C.ink : C.muted,
                  letterSpacing: "-0.02em",
                }}>
                  {t._status === "scheduled" ? fmtScheduled(t)
                    : t._status === "done" ? fmtDone(t)
                    : t._status === "draft" ? "drawer"
                    : "—"}
                  <span style={{ display: "block", fontSize: 9, color: C.muted, fontWeight: 500, marginTop: 1 }}>
                    {fmtDurationHM(t.effortMin || 30)}
                  </span>
                </div>
                <div style={{
                  fontFamily: "'Cormorant Garamond', serif",
                  fontSize: 15, fontWeight: 500, color: C.ink,
                  lineHeight: 1.2,
                  textDecoration: t._status === "done" ? "line-through" : "none",
                  opacity: t._status === "done" ? 0.55 : 1,
                  textAlign: "left",
                }}>
                  <span style={{
                    display: "inline-block", width: 6, height: 6,
                    borderRadius: "50%", marginRight: 7, verticalAlign: "middle",
                    background: fmtFocusColor(t.focusLevel),
                  }} />
                  {t.title}
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  {t.regretScore != null && t._status !== "done" && (
                    <span style={{
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: 10, fontWeight: 700,
                      color: fmtRegretColor(t.regretScore),
                    }}>R{t.regretScore}</span>
                  )}
                  {/* v05.05bt353 — Per chat: 'on the all tasks, i see
                      where i can click on delete but i think it would
                      be good to click on done so maybe a little check
                      mark as well.' Toggles completedAt directly. */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      const nowIso = new Date().toISOString();
                      setTasks(prev => prev.map(x =>
                        x.id === t.id
                          ? { ...x, completedAt: x.completedAt ? null : nowIso }
                          : x
                      ));
                    }}
                    title={t._status === "done" ? "Mark not done" : "Mark done"}
                    style={{
                      width: 24, height: 24, borderRadius: "50%",
                      background: t._status === "done" ? "#7B9B6E" : "transparent",
                      color: "#fff", fontSize: 12, fontWeight: 700,
                      border: t._status === "done" ? "none" : `1.5px solid #7B9B6E66`,
                      cursor: "pointer", padding: 0, lineHeight: 1,
                      display: "flex", alignItems: "center", justifyContent: "center",
                      flexShrink: 0,
                    }}>
                    {t._status === "done" ? "✓" : ""}
                  </button>
                  {/* Delete (× → confirm) */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      if (pendingDeleteId === t.id) {
                        if (pendingDeleteTimerRef.current) clearTimeout(pendingDeleteTimerRef.current);
                        setPendingDeleteId(null);
                        setTasks(prev => prev.filter(x => x.id !== t.id));
                      } else {
                        setPendingDeleteId(t.id);
                        if (pendingDeleteTimerRef.current) clearTimeout(pendingDeleteTimerRef.current);
                        pendingDeleteTimerRef.current = setTimeout(() => setPendingDeleteId(null), 4000);
                      }
                    }}
                    title={pendingDeleteId === t.id ? "Tap again to confirm" : "Delete this task"}
                    style={{
                      background: pendingDeleteId === t.id ? "#B85040" : "transparent",
                      color: pendingDeleteId === t.id ? "#fff" : "rgba(184, 80, 64, 0.55)",
                      border: pendingDeleteId === t.id ? "none" : `1px solid rgba(184, 80, 64, 0.2)`,
                      borderRadius: 5,
                      padding: pendingDeleteId === t.id ? "4px 9px" : "2px 7px",
                      fontSize: pendingDeleteId === t.id ? 10 : 13,
                      fontWeight: 700, lineHeight: 1,
                      cursor: "pointer", fontFamily: "inherit",
                      transition: "all 0.15s",
                    }}>
                    {pendingDeleteId === t.id ? "delete?" : "×"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
        ));
      })()}

      {/* Footer note */}
      <div style={{
        marginTop: 18, padding: "12px 14px",
        fontFamily: "'Cormorant Garamond', serif",
        fontStyle: "italic", fontSize: 12,
        color: C.muted, textAlign: "center",
        lineHeight: 1.4,
      }}>
        Tap any task to edit. Status updates automatically based on whether it has a time, drawer flag, or completion.
      </div>
    </div>
  );
}


function ShiftsView({ C: receivedC, shifts, setShifts, meetings, setMeetings, now, onsite, setOnsite, activeShifts, swaps, tomorrowProjection, timeBank, setTimeBank, currentUser, pendingTimeBankAction, clearPendingTimeBankAction, events, addEvent, tasks, setTasks, parentAway, setParentAway, pumpPlan, setPumpPlan, todaySetup, setTodaySetup, focusProfile, setFocusProfile, dailyEnergy, setDailyEnergy, routineLibrary, setRoutineLibrary, showRoutineEditor, setShowRoutineEditor, showOptimizer, setShowOptimizer, tradeRequests, openSendTrade, appointments, schedulerDarkMode, setSchedulerDarkMode, setTab, productMode, setProductMode, cadenceScope, setCadenceScope }) {
  // v05.05bt283 — Whole Mommy Day page goes dark. Per chat: 'i think
  // the WHOLE page under mommy day should be under dark mode.' By
  // overriding C inside ShiftsView, every component rendered here
  // (sub-tabs, banners, TodayTaskPlanCard, AllTasksView) inherits the
  // dusk palette without per-component threading.
  // v05.05bt305 — Readability pass per chat: 'i have a really hard
  // time reading things clearly... font is very thin and faint and
  // often times have to strain.' schedulerC overrides muted color
  // to a darker warm taupe so secondary text (eyebrows, sub-lines,
  // meta) actually has contrast against the cream paper. In dark
  // mode the dusk palette is already calibrated, so leave its muted
  // untouched.
  const C = schedulerDarkMode ? PALETTES.dusk : { ...receivedC, muted: "#5C4D40" };
  const schedulerC = C;
  const [showAdd, setShowAdd] = useState(false);
  // v05.05bt248 — Default-start date for the add-meeting modal so tapping
  // "+ Add commitment" on the TOMORROW DayPlanCard pre-fills tomorrow's
  // date. Per chat: 'The scheduler is not considering the tomorrow
  // meeting commitments when looking at the tomorrow schedule.' Root
  // cause: when daddy taps add on Tomorrow's card, the form defaulted
  // to NOW (today's date), so unless he manually changed it, the
  // meeting saved with today's date — invisible to tomorrow view.
  const [addMeetingDefaultDate, setAddMeetingDefaultDate] = useState(null);
  // v05.05bt133 — Schedule tab now split into three sub-views:
  // 'today' = Today's Ledger card (working parent OS),
  // 'schedule' = base shift schedule + day plan + meetings,
  // 'caregiver' = day-in-life of Solène from her actual data.
  const [scheduleSubTab, setScheduleSubTab] = useState("today");
  // v05.05bt323 — Caregiver sub-tab removed (per chat). If a user has
  // it persisted from before, redirect them back to "today" on mount.
  useEffect(() => {
    if (scheduleSubTab === "caregiver") setScheduleSubTab("today");
  }, [scheduleSubTab]);
  // v05.05bt287 — All Tasks as bottom-sheet modal instead of full-screen
  // sub-tab. Per chat: 'i dont like how the all tasks history goes into
  // a whole different screen.' Modal preserves scheduler context behind
  // a dim overlay; swipe-down dismisses.
  const [allTasksModalOpen, setAllTasksModalOpen] = useState(false);
  // v05.05bt146 — editing a task from the All Tasks list view
  const [editingTaskFromAll, setEditingTaskFromAll] = useState(null);
  // NOTE: Time Bank and on-site state used to live here. Time Bank is now
  // its own tab (BankView), and on-site lives in NowView. The
  // pendingTimeBankAction deep-link is handled at App level (forwarded to
  // BankView) — this view no longer reacts to it.

  // Day-plan open state hoisted to parent so the Next-7-days peek strip
  // can toggle it from outside. Both default to closed (low overload).
  const [todayOpen, setTodayOpen] = useState(false);
  const [tomorrowOpen, setTomorrowOpen] = useState(false);

  // Upcoming-section trigger from peek strip. When user taps a day 3+
  // ahead, we open the Upcoming details and (if we can) narrow the filter.
  const [upcomingTrigger, setUpcomingTrigger] = useState(null); // { open: bool, filter: "week"|"month"|null }
  const [editingMeeting, setEditingMeeting] = useState(null); // meeting object being edited
  // v05.05bt106 — modal for editing parent-out-of-town context
  const [showAwayModal, setShowAwayModal] = useState(false);

  const addMeeting = (m) => {
    const newMeeting = { ...m, id: crypto.randomUUID() };
    setMeetings(prev => {
      const next = [...prev, newMeeting];
      try {
        localStorage.setItem("solene:meetings", JSON.stringify(next));
        localStorage.setItem("solene:meetings:backup", JSON.stringify(prev));
      } catch (e) { console.warn("[addMeeting] sync persist failed", e); }
      return next;
    });
    setShowAdd(false);
  };
  const removeMeeting = (id) => setMeetings(prev => {
    const next = prev.filter(m => m.id !== id);
    try {
      localStorage.setItem("solene:meetings", JSON.stringify(next));
      localStorage.setItem("solene:meetings:backup", JSON.stringify(prev));
    } catch (e) { console.warn("[removeMeeting] sync persist failed", e); }
    return next;
  });
  // Update an existing meeting in place — preserves id and any side-channel
  // fields (gift redemption metadata, etc.) by spreading the original first
  // and only overlaying the editable form fields on top.
  const updateMeeting = (id, patch) => setMeetings(prev => {
    const next = prev.map(m => m.id === id ? { ...m, ...patch } : m);
    try {
      localStorage.setItem("solene:meetings", JSON.stringify(next));
    } catch (e) { console.warn("[updateMeeting] sync persist failed", e); }
    return next;
  });
  // v05.05bt156 — Meeting filter scope clarified per chat:
  //   - "Shifts" sub-tab (Day Plan section) wants to see BOTH parents'
  //     meetings since shift coverage is a household-level view.
  //   - "Mommy's Day" sub-tab (TodayTaskPlanCard) wants ONLY Mommy's
  //     meetings — Daddy's meetings don't block Mommy's calendar.
  // This `today` constant feeds the Day Plan card (Shifts sub-tab) so
  // we DROP the owner filter here. The dayTimeline filter inside
  // TodayTaskPlanCard already filters by owner (bt141) — that path is
  // unchanged.
  const today = meetings.filter(m =>
    new Date(m.start).toDateString() === now.toDateString()
  );

  return (
    <div style={{
      marginTop: 14,
      // v05.05bt283 — Dark-mode wrapper for the whole Mommy Day page
      ...(schedulerDarkMode ? {
        background: C.bg,
        color: C.ink,
        padding: "12px 10px",
        borderRadius: 12,
        marginLeft: -10,
        marginRight: -10,
      } : {}),
    }}>
      {/* v05.05bt133 — Sub-tab pills split Schedule into three views. */}
      {currentUser === "Mommy" && (
        <div style={{
          display: "flex", gap: 6, marginBottom: 14,
          padding: "4px",
          background: `${C.line}10`,
          borderRadius: 12,
        }}>
          {[
            { key: "schedule",  label: "Shifts" },
            { key: "today",     label: "Mommy's Day" },
            // v05.05bt323 — Per chat: 'i dont think i need a Solene day
            // in little ledger scheduler tab because that info should
            // be captured in caregiver.' The caregiver-window banner +
            // the OnDutyCard caregiver-mode (bt310) already surface
            // Solène's context at the top of the Now tab; no need to
            // duplicate as a separate scheduler sub-tab.
          ].map(t => (
            <button
              key={t.key}
              onClick={() => setScheduleSubTab(t.key)}
              style={{
                flex: 1,
                // v05.05bt333 — Active state was hardcoded #FDFAF1 cream
                // bg + #7C6B5A brown inactive text — both invisible on
                // Cadence dark. Swap to palette colors so the active
                // pill always reads as a lifted surface and inactive
                // text is muted-but-legible in both modes.
                background: scheduleSubTab === t.key ? C.paper : "transparent",
                color: scheduleSubTab === t.key ? C.ink : C.muted,
                border: scheduleSubTab === t.key ? `1px solid ${C.mommy}38` : "1px solid transparent",
                borderRadius: 9, padding: "8px 4px",
                fontSize: 10, fontWeight: scheduleSubTab === t.key ? 700 : 500,
                cursor: "pointer", fontFamily: "inherit",
                letterSpacing: "0.01em",
                boxShadow: scheduleSubTab === t.key ? `0 1px 2px ${C.mommy}22` : "none",
              }}>
              {t.label}
            </button>
          ))}
        </div>
      )}

      {/* TODAY'S LEDGER sub-view */}
      {currentUser === "Mommy" && scheduleSubTab === "today" && (
        <TodayTaskPlanCard
          C={schedulerC} tasks={tasks} setTasks={setTasks}
          activeShifts={activeShifts}
          tomorrowProjection={tomorrowProjection}
          events={events} addEvent={addEvent} now={now}
          currentUser={currentUser}
          parentAway={parentAway}
          pumpPlan={pumpPlan} setPumpPlan={setPumpPlan}
          onsite={onsite} setOnsite={setOnsite}
          todaySetup={todaySetup} setTodaySetup={setTodaySetup}
          meetings={meetings} setMeetings={setMeetings}
          focusProfile={focusProfile} setFocusProfile={setFocusProfile}
          dailyEnergy={dailyEnergy} setDailyEnergy={setDailyEnergy}
          routineLibrary={routineLibrary} setRoutineLibrary={setRoutineLibrary}
          showRoutineEditor={showRoutineEditor} setShowRoutineEditor={setShowRoutineEditor}
          showOptimizer={showOptimizer} setShowOptimizer={setShowOptimizer}
            tradeRequests={tradeRequests} openSendTrade={openSendTrade}
            appointments={appointments}
            timeBank={timeBank}
            schedulerDarkMode={schedulerDarkMode} setSchedulerDarkMode={setSchedulerDarkMode}
            setScheduleSubTab={setScheduleSubTab}
            openAllTasksModal={() => setAllTasksModalOpen(true)}
            setTab={setTab}
            productMode={productMode} setProductMode={setProductMode}
            cadenceScope={cadenceScope} setCadenceScope={setCadenceScope}
        />
      )}

      {/* CAREGIVER sub-view — day in the life of Solène */}
      {/* v05.05bt146 — All Tasks sub-view. Flat list of every task in
          the system grouped by status. Tap row to edit. */}
      {currentUser === "Mommy" && scheduleSubTab === "all" && (
        <AllTasksView
          C={C} tasks={tasks} setTasks={setTasks}
          currentUser={currentUser} now={now}
          onEditTask={(t) => setEditingTaskFromAll(t)}
          onBack={() => setScheduleSubTab("today")}
        />
      )}

      {currentUser === "Mommy" && scheduleSubTab === "caregiver" && (
        <div>
          <div style={{
            marginBottom: 14, padding: "0 4px",
          }}>
            <h1 style={{
              fontFamily: "'Cormorant Garamond', serif",
              fontWeight: 500, fontSize: 26,
              color: C.ink, margin: 0,
              lineHeight: 1.05,
              letterSpacing: "-0.015em",
            }}>
              Solène's Day
            </h1>
            <div style={{
              marginTop: 4,
              fontFamily: "'Cormorant Garamond', serif",
              fontStyle: "italic", fontSize: 13,
              color: C.muted, lineHeight: 1.4,
            }}>
              Share with whoever's watching Solène. Times pulled from her actual rhythm.
            </div>
          </div>
          <DayInLifeCard C={C} events={events} now={now} />
        </div>
      )}

      {/* SCHEDULE sub-view: base shifts + day plans + meetings.
          Default when not Mommy too. */}
      {(currentUser !== "Mommy" || scheduleSubTab === "schedule") && (
      <div>
      {/* v05.05bt133 — Sunday morning plan hidden for now. */}
      {false && <SundayRoutineCard C={C} events={events} now={now} />}
      <Section C={C} title="Base shift schedule">
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          {["Mommy", "Daddy"].map(parent => {
            const color = parent === "Mommy" ? C.mommy : C.daddy;
            // Show effective shifts (which may differ from base when onsite is active)
            const displayShifts = onsite ? activeShifts[parent] : shifts[parent];
            return (
              <div key={parent} style={{
                background: C.paper, borderRadius: 12, padding: 14,
                border: `1px solid ${C.line}15`, borderTop: `3px solid ${color}`,
              }}>
                <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 22, fontWeight: 500, marginBottom: 8, color }}>
                  {parent}
                  {onsite?.parent === parent && (
                    <span style={{ fontSize: 10, color: C.accent, marginLeft: 6, letterSpacing: "0.1em", fontFamily: "'Inter', sans-serif", fontWeight: 600 }}>
                      AWAY
                    </span>
                  )}
                </div>
                {displayShifts.length === 0 ? (
                  <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic" }}>
                    no shifts (away)
                  </div>
                ) : displayShifts.map((s, i) => (
                  <div key={i} style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, padding: "3px 0", color: C.ink }}>
                    {fmtShiftRange(s)}
                  </div>
                ))}
              </div>
            );
          })}
        </div>
        {onsite && (
          <div style={{ marginTop: 8, fontSize: 11, color: C.muted, fontStyle: "italic", textAlign: "center" }}>
            ↑ shifts shown above include on-site coverage. base schedule resumes when you tap "I'm home."
          </div>
        )}
      </Section>

      {/* Day plan — unified Today + Tomorrow view. Each day shows shifts +
          auto-swap adjustments + commitments together so coverage and
          calendar are coupled. Both default to collapsed; tap headers to
          expand. The Next-7-days peek strip below provides the broader
          weekly context. */}
      <Section C={C} title="Day plan">
        {/* v05.05bt108 — out-of-town banner moved here per chat: this
            section is where meetings/appointments live, so business-trip
            context belongs alongside them. Sits above the Today/Tomorrow
            cards as upstream context (informs the day cards below). */}
        <ParentAwayBanner C={C} parentAway={parentAway} now={now}
          onOpenEditor={() => setShowAwayModal(true)} />
        {(() => {
          // ---- Today
          const todayLabel = now.toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" });
          const todayCommitments = [...today].sort((a, b) => new Date(a.start) - new Date(b.start));

          // ---- Tomorrow
          const tomorrow = new Date(now);
          tomorrow.setDate(tomorrow.getDate() + 1);
          const dayAfter = new Date(tomorrow);
          dayAfter.setDate(dayAfter.getDate() + 1);
          tomorrow.setHours(0, 0, 0, 0);
          dayAfter.setHours(0, 0, 0, 0);
          const tomorrowMeetings = (meetings || [])
            .filter(m => {
              const t = new Date(m.start);
              return t >= tomorrow && t < dayAfter;
              // v05.05bt156 — Shifts view = household coverage view,
              // includes both parents' meetings.
            })
            .sort((a, b) => new Date(a.start) - new Date(b.start));
          const tomorrowLabel = tomorrow.toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" });
          const tomProj = tomorrowProjection?.projected || { Mommy: shifts.Mommy || [], Daddy: shifts.Daddy || [] };
          const tomSwaps = tomorrowProjection?.swaps || [];

          return (
            <>
              <DayPlanCard
                key={`today-${todayCommitments.length}-${todayCommitments.map(m => m.start + m.end).join("|")}`}
                C={C}
                label="Today"
                subLabel={todayLabel}
                shiftBlocks={activeShifts}
                daySwaps={swaps || []}
                commitments={todayCommitments}
                onRemoveCommitment={removeMeeting}
                onEditCommitment={(m) => setEditingMeeting(m)}
                onAddCommitment={() => {
                  setAddMeetingDefaultDate(new Date());
                  setShowAdd(true);
                }}
                showAddButton={true}
                isToday={true}
                now={now}
                controlledOpen={todayOpen}
                setControlledOpen={setTodayOpen}
              />
              <DayPlanCard
                key={`tomorrow-${tomorrowMeetings.length}-${tomorrowMeetings.map(m => m.start + m.end).join("|")}`}
                C={C}
                label="Tomorrow"
                subLabel={tomorrowLabel}
                shiftBlocks={tomProj}
                daySwaps={tomSwaps}
                commitments={tomorrowMeetings}
                onRemoveCommitment={removeMeeting}
                onEditCommitment={(m) => setEditingMeeting(m)}
                onAddCommitment={() => {
                  // Pre-fill tomorrow's date so the meeting actually
                  // saves with tomorrow's date.
                  const tom = new Date(now);
                  tom.setDate(tom.getDate() + 1);
                  setAddMeetingDefaultDate(tom);
                  setShowAdd(true);
                }}
                showAddButton={true}
                isToday={false}
                now={now}
                controlledOpen={tomorrowOpen}
                setControlledOpen={setTomorrowOpen}
              />
              <div style={{ marginTop: 6, fontSize: 11, color: C.muted, fontStyle: "italic", textAlign: "center" }}>
                meetings, appointments, hair, friends — anything that takes you off duty
              </div>
            </>
          );
        })()}
      </Section>

      {/* Future peek — horizontal strip of the next 7 days. Each compact
          card summarizes the day at a glance: weekday, date, count of
          commitments, count of auto-adjustments. Tap behavior:
            • Today → expands the Today card in Day plan above and scrolls to it
            • Tomorrow → same for Tomorrow
            • Days 2-6 ahead → opens the Upcoming section below with a filter
              scoped to the week or month (whichever fits).
          Today's card is highlighted in coral. */}
      {(() => {
        const days = [];
        for (let i = 0; i < 7; i++) {
          const d = new Date(now);
          d.setDate(d.getDate() + i);
          d.setHours(0, 0, 0, 0);
          const dEnd = new Date(d);
          dEnd.setDate(dEnd.getDate() + 1);
          const dayMeetings = (meetings || []).filter(m => {
            const t = new Date(m.start);
            return t >= d && t < dEnd;
          });
          let swapCount = 0;
          if (i === 0) swapCount = (swaps || []).length;
          else if (i === 1) swapCount = (tomorrowProjection?.swaps || []).length;
          const giftCount = dayMeetings.filter(m => (m.label || "").startsWith("🎁")).length;
          days.push({ date: d, meetings: dayMeetings, swapCount, giftCount, isToday: i === 0, daysAhead: i });
        }

        const handleTap = (d) => {
          if (d.daysAhead === 0) {
            setTodayOpen(true);
            setTimeout(() => {
              const el = document.getElementById("dayplan-today");
              if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
            }, 50);
          } else if (d.daysAhead === 1) {
            setTomorrowOpen(true);
            setTimeout(() => {
              const el = document.getElementById("dayplan-tomorrow");
              if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
            }, 50);
          } else {
            // Open Upcoming with appropriate filter
            const filter = d.daysAhead <= 7 ? "week" : "month";
            setUpcomingTrigger({ open: true, filter });
          }
        };

        return (
          <Section C={C} title="Next 7 days">
            <div style={{
              display: "flex", gap: 8, overflowX: "auto", paddingBottom: 6,
              scrollbarWidth: "thin",
            }}>
              {days.map((d, i) => {
                const isToday = d.isToday;
                const isTomorrow = i === 1;
                const count = d.meetings.length;
                const hasGifts = d.giftCount > 0;
                const hasSwaps = d.swapCount > 0;
                const dim = count === 0 && !hasSwaps;
                return (
                  <button
                    key={i}
                    onClick={() => handleTap(d)}
                    style={{
                      flex: "0 0 auto",
                      minWidth: 76,
                      background: isToday ? `${C.accent}15` : C.paper,
                      border: `1px solid ${isToday ? C.accent + "55" : C.line + "20"}`,
                      borderRadius: 12, padding: "10px 8px",
                      textAlign: "center",
                      opacity: dim ? 0.7 : 1,
                      cursor: "pointer",
                      fontFamily: "inherit",
                      transition: "transform 0.1s, box-shadow 0.15s",
                    }}
                    onMouseDown={e => e.currentTarget.style.transform = "scale(0.96)"}
                    onMouseUp={e => e.currentTarget.style.transform = "scale(1)"}
                    onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}
                  >
                    <div style={{
                      fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase",
                      color: isToday ? C.accent : C.muted, fontWeight: 700,
                    }}>
                      {isToday ? "Today" : isTomorrow ? "Tom." : d.date.toLocaleDateString(undefined, { weekday: "short" })}
                    </div>
                    <div style={{
                      fontFamily: "'Cormorant Garamond', serif",
                      fontSize: 24, fontWeight: 500, fontStyle: "italic",
                      color: isToday ? C.accent : C.ink, lineHeight: 1.05,
                      marginTop: 1,
                    }}>
                      {d.date.getDate()}
                    </div>
                    <div style={{
                      fontSize: 9, color: C.muted,
                      fontFamily: "'JetBrains Mono', monospace",
                      marginTop: 2,
                    }}>
                      {d.date.toLocaleDateString(undefined, { month: "short" }).toLowerCase()}
                    </div>
                    <div style={{
                      marginTop: 6, paddingTop: 6,
                      borderTop: `1px solid ${C.line}15`,
                      display: "flex", flexDirection: "column", gap: 2,
                      minHeight: 28,
                    }}>
                      {count === 0 && !hasSwaps ? (
                        <div style={{ fontSize: 9, color: C.muted, fontStyle: "italic" }}>—</div>
                      ) : (
                        <>
                          {count > 0 && (
                            <div style={{
                              fontSize: 10, color: C.accent, fontWeight: 700,
                              fontFamily: "'JetBrains Mono', monospace",
                              display: "flex", alignItems: "center", justifyContent: "center", gap: 3,
                            }}>
                              {hasGifts && <span style={{ fontSize: 9 }}>🎁</span>}
                              {count}{count === 1 ? " mtg" : " mtgs"}
                            </div>
                          )}
                          {hasSwaps && (
                            <div style={{
                              fontSize: 9, color: C.gold, fontWeight: 600,
                              fontFamily: "'JetBrains Mono', monospace",
                            }}>
                              ↻ {d.swapCount}
                            </div>
                          )}
                        </>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>
            <div style={{ fontSize: 10, color: C.muted, fontStyle: "italic", marginTop: 4, textAlign: "center" }}>
              tap a day to jump to its details
            </div>
          </Section>
        );
      })()}

      {/* Upcoming — anything beyond tomorrow. Collapsible because it can grow
          long once recurring commitments accumulate. Groups by date so
          scanning is easier than a flat list. Includes filter pills for
          quick narrowing: Day-after / This week / This month / All. Filters
          act on the visible groups; the count badge in the header still
          shows the TOTAL future count so you can see at a glance whether
          things are falling outside the current filter. */}
      {(() => {
        const dayAfterTomorrow = new Date(now);
        dayAfterTomorrow.setDate(dayAfterTomorrow.getDate() + 2);
        dayAfterTomorrow.setHours(0, 0, 0, 0);
        const allFuture = (meetings || [])
          .filter(m => new Date(m.start) >= dayAfterTomorrow)
          .sort((a, b) => new Date(a.start) - new Date(b.start));
        if (allFuture.length === 0) return null;

        // Filter cutoffs (relative to now)
        const sevenDaysOut = new Date(now); sevenDaysOut.setDate(sevenDaysOut.getDate() + 7); sevenDaysOut.setHours(23, 59, 59, 999);
        const thirtyDaysOut = new Date(now); thirtyDaysOut.setDate(thirtyDaysOut.getDate() + 30); thirtyDaysOut.setHours(23, 59, 59, 999);

        return (
          <UpcomingSection
            C={C}
            allFuture={allFuture}
            sevenDaysOut={sevenDaysOut}
            thirtyDaysOut={thirtyDaysOut}
            onRemoveMeeting={removeMeeting}
            onEditMeeting={(m) => setEditingMeeting(m)}
            externalOpen={upcomingTrigger?.open}
            externalFilter={upcomingTrigger?.filter}
            onExternalOpenHandled={() => setUpcomingTrigger(null)}
          />
        );
      })()}
      </div>
      )}
      {/* v05.05bt133 — End of Schedule sub-view. Modals below render
          regardless of which sub-tab is active. */}

      {showAdd && <AddMeetingModal C={C} onClose={() => { setShowAdd(false); setAddMeetingDefaultDate(null); }} onSubmit={addMeeting} currentUser={currentUser} defaultDate={addMeetingDefaultDate} />}
      {showAwayModal && (
        <ParentAwayModal
          C={C}
          parentAway={parentAway}
          onClose={() => setShowAwayModal(false)}
          onSave={(a) => { setParentAway(a); setShowAwayModal(false); }}
          onClear={() => setParentAway(null)}
        />
      )}

      {/* Edit meeting modal — pre-fills the same form used for adding,
          updates in place on submit. */}
      {editingMeeting && (
        <ModalShell C={C} onClose={() => setEditingMeeting(null)} title="Edit commitment">
          <InlineCommitmentForm
            C={C}
            currentUser={currentUser}
            initial={editingMeeting}
            onSubmit={(patch) => {
              updateMeeting(editingMeeting.id, patch);
              setEditingMeeting(null);
            }}
          />
        </ModalShell>
      )}

      {/* v05.05bt146 — Edit task from All Tasks list view */}
      {editingTaskFromAll && (
        <EditTaskModal
          C={C}
          task={editingTaskFromAll}
          onClose={() => setEditingTaskFromAll(null)}
          onSave={(updated) => {
            setTasks(prev => prev.map(t => t.id === updated.id ? { ...t, ...updated } : t));
            setEditingTaskFromAll(null);
          }}
          onDelete={() => {
            setTasks(prev => prev.filter(t => t.id !== editingTaskFromAll.id));
            setEditingTaskFromAll(null);
          }}
        />
      )}
      {/* v05.05bt287 — All Tasks bottom-sheet modal */}
      {allTasksModalOpen && (
        <ModalShell C={C} onClose={() => setAllTasksModalOpen(false)} title="All tasks across days">
          <AllTasksView
            C={C} tasks={tasks} setTasks={setTasks}
            currentUser={currentUser} now={now}
            hideHeader={true}
            onEditTask={(t) => { setAllTasksModalOpen(false); setEditingTaskFromAll(t); }}
          />
        </ModalShell>
      )}
    </div>
  );
}

function DiffCard({ C, swaps, shifts, activeShifts }) {
  // Show side-by-side base vs effective for each parent, with arrows on swapped blocks
  const swappedKeySet = new Set(swaps.map(s => `${s.originalParent}|${s.shift.start}-${s.shift.end}`));

  return (
    <div style={{ background: C.paper, borderRadius: 12, padding: 14, border: `1px solid ${C.line}15` }}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        {["Mommy", "Daddy"].map(parent => {
          const color = parent === "Mommy" ? C.mommy : C.daddy;
          const baseList = shifts[parent];
          const liveList = activeShifts[parent];
          // Build a unified list of {shift, status} based on what's in base vs live
          const liveSet = new Set(liveList.map(s => `${s.start}-${s.end}`));
          const baseSet = new Set(baseList.map(s => `${s.start}-${s.end}`));
          const all = [...baseList, ...liveList.filter(s => !baseSet.has(`${s.start}-${s.end}`))]
            .sort((a, b) => toMin(a.start) - toMin(b.start));

          return (
            <div key={parent} style={{ borderTop: `3px solid ${color}`, paddingTop: 8 }}>
              <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, fontWeight: 500, color, marginBottom: 6 }}>
                {parent}
              </div>
              {all.length === 0 ? (
                <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic" }}>—</div>
              ) : all.map((s, i) => {
                const inBase = baseSet.has(`${s.start}-${s.end}`);
                const inLive = liveSet.has(`${s.start}-${s.end}`);
                const lostFromBase = inBase && !inLive; // they're losing this shift
                const gainedNow = !inBase && inLive;    // they're picking this up
                return (
                  <div key={i} style={{
                    fontFamily: "'JetBrains Mono', monospace", fontSize: 11,
                    padding: "2px 0",
                    color: lostFromBase ? C.muted : C.ink,
                    textDecoration: lostFromBase ? "line-through" : "none",
                    fontWeight: gainedNow ? 600 : 400,
                  }}>
                    {gainedNow && "+ "}{lostFromBase && "− "}{fmtShiftRange(s)}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
      <div style={{ marginTop: 10, padding: "8px 10px", background: C.bg, borderRadius: 8, fontSize: 11, color: C.muted, lineHeight: 1.5 }}>
        <strong style={{ color: C.ink }}>+ added</strong> = picking up to cover · <strong style={{ color: C.ink, textDecoration: "line-through" }}>removed</strong> = covered by partner
      </div>
    </div>
  );
}

// ---- Time Bank --------------------------------------------------------
// Convention: balance > 0 means Mommy owes Daddy (Daddy gave Mommy time).
//             balance < 0 means Daddy owes Mommy.
function fmtBalance(mins) {
  const abs = Math.abs(mins);
  const h = Math.floor(abs / 60);
  const m = abs % 60;
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
}

function TimeBankCard({ C, timeBank, onOpen, currentUser, onRedeem }) {
  const balance = timeBank.balance || 0;
  // Breakdown by transaction kind, FROM currentUser's perspective.
  // Gifts and debts both contribute to balance the same way (per the
  // computeTimeBankBalance logic), but for breakdown display we want to
  // show them separately so the user sees what's accumulating where:
  //   - gifts directed AT currentUser show as positive (received)
  //   - debts owed BY currentUser show as negative
  // This mirrors the "+ and -" mental model the user asked for.
  const breakdown = useMemo(() => {
    let giftsReceived = 0;  // gifts where currentUser is the recipient
    let giftsGiven = 0;     // gifts where currentUser is the giver
    let debtsOwedToYou = 0; // owed where currentUser is owed (i.e. partner covered for them)
    let debtsYouOwe = 0;    // owed where currentUser owes
    let payback = 0;        // either direction
    for (const tx of (timeBank.transactions || [])) {
      const m = tx.mins || 0;
      if (tx.kind === "gift") {
        if (tx.to === currentUser) giftsReceived += m;
        else if (tx.from === currentUser) giftsGiven += m;
      } else if (tx.kind === "owed") {
        if (tx.to === currentUser) debtsYouOwe += m;       // partner covered for you → you owe them
        else if (tx.from === currentUser) debtsOwedToYou += m; // you covered for partner → they owe you
      } else if (tx.kind === "paid") {
        payback += m;
      }
    }
    return { giftsReceived, giftsGiven, debtsOwedToYou, debtsYouOwe, payback };
  }, [timeBank.transactions, currentUser]);

  // From currentUser's POV:
  //   if balance > 0: Mommy owes Daddy.
  //     - if currentUser=Mommy → "You owe Daddy"
  //     - if currentUser=Daddy → "Mommy owes you"
  //   if balance < 0: Daddy owes Mommy.
  //     - if currentUser=Daddy → "You owe Mommy"
  //     - if currentUser=Mommy → "Daddy owes you"
  const partner = currentUser === "Mommy" ? "Daddy" : "Mommy";
  const partnerColor = currentUser === "Mommy" ? C.daddy : C.mommy;
  const youColor = currentUser === "Mommy" ? C.mommy : C.daddy;

  let directionLabel, primaryColor, youOwe;
  if (balance === 0) {
    directionLabel = "All square";
    primaryColor = C.ink;
    youOwe = null;
  } else if (
    (balance > 0 && currentUser === "Mommy") ||
    (balance < 0 && currentUser === "Daddy")
  ) {
    // currentUser owes partner
    directionLabel = `You owe ${partner}`;
    primaryColor = partnerColor;
    youOwe = true;
  } else {
    // partner owes currentUser → time to spend!
    directionLabel = `${partner} owes you`;
    primaryColor = youColor;
    youOwe = false;
  }

  // Total +/- shown in the breakdown strip.
  // From your view: +gifts received, -gifts given, +debts owed to you, -debts you owe.
  const positiveTotal = breakdown.giftsReceived + breakdown.debtsOwedToYou;
  const negativeTotal = breakdown.giftsGiven + breakdown.debtsYouOwe;
  const hasAny = (timeBank.transactions || []).length > 0;

  return (
    <div style={{
      background: balance === 0
        ? C.paper
        : `linear-gradient(135deg, ${primaryColor}22, ${C.paper})`,
      border: `1px solid ${C.line}15`,
      borderLeft: balance === 0 ? `1px solid ${C.line}15` : `4px solid ${primaryColor}`,
      borderRadius: 12, padding: 16,
    }}>
      <div onClick={onOpen} style={{ cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
        <div style={{ minWidth: 0, flex: 1 }}>
          <div style={{ fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontWeight: 600 }}>
            Time bank · {directionLabel}
          </div>
          <div style={{ marginTop: 4 }}>
            {balance === 0 ? (
              <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 28, fontWeight: 500, fontStyle: "italic", color: C.ink }}>
                no debts
              </span>
            ) : (
              <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 32, fontWeight: 500, color: primaryColor, lineHeight: 1 }}>
                {fmtBalance(balance)}
              </span>
            )}
          </div>
          {/* Breakdown strip — from current user's perspective.
              Plus side = gifts received + debts owed to you (both move balance toward you).
              Minus side = gifts given + debts you owe (both move balance away from you).
              Hidden when there are no transactions. */}
          {hasAny && (positiveTotal > 0 || negativeTotal > 0) && (
            <div style={{
              marginTop: 10, display: "flex", alignItems: "center", gap: 12,
              fontSize: 11, fontFamily: "'JetBrains Mono', monospace",
            }}>
              {positiveTotal > 0 && (
                <span style={{ color: "#4F6E4D", fontWeight: 600 }}>
                  +{fmtBalance(positiveTotal)}
                  <span style={{ color: C.muted, fontWeight: 400, marginLeft: 4 }}>received</span>
                </span>
              )}
              {negativeTotal > 0 && (
                <span style={{ color: C.accent, fontWeight: 600 }}>
                  −{fmtBalance(negativeTotal)}
                  <span style={{ color: C.muted, fontWeight: 400, marginLeft: 4 }}>given</span>
                </span>
              )}
            </div>
          )}
          <div style={{ fontSize: 11, color: C.muted, marginTop: 6 }}>
            {timeBank.transactions.length === 0
              ? "tap to log a swap, gift, or payback"
              : `${timeBank.transactions.length} transaction${timeBank.transactions.length === 1 ? "" : "s"} · tap for history`}
          </div>
        </div>
        <ChevronRight size={18} color={C.muted} />
      </div>

      {/* Redeem button — show whenever currentUser has any positive credit.
          v05.05bt41: lowered from ≥30m to ≥1m per user feedback. The picker
          step is now 5m, so even small balances are practical to redeem. */}
      {youOwe === false && Math.abs(balance) >= 1 && (
        <button onClick={onRedeem} style={{
          marginTop: 12, width: "100%",
          background: youColor, color: "#fff", border: "none",
          padding: "10px 14px", borderRadius: 8,
          fontSize: 13, fontWeight: 600, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <Gift size={14} /> Cash in: have {partner} cover a shift
        </button>
      )}
    </div>
  );
}

function TimeBankModal({ C, timeBank, setTimeBank, initialMode, onClose }) {
  // initialMode is "gift" | "payback" | null. Maps to TimeBankAddForm's
  // initial 'kind' state: gift → 'gift', payback → 'paid'.
  const [tab, setTab] = useState("add"); // 'add' | 'history'
  const initialKind = initialMode === "gift" ? "gift" : initialMode === "payback" ? "paid" : null;
  // Confirmation banner: after saving a transaction we briefly show a
  // success message so the user sees the action took effect (especially
  // important for gifts, which don't visibly change the balance number).
  const [lastSaved, setLastSaved] = useState(null); // { kind, mins, to } | null

  const recordTransaction = (tx) => {
    const newTx = { ...tx, id: crypto.randomUUID(), ts: new Date().toISOString() };
    const newTransactions = [...timeBank.transactions, newTx];
    // Always derive balance from the full ledger — no cached-balance drift.
    setTimeBank({
      balance: computeTimeBankBalance(newTransactions),
      transactions: newTransactions,
    });
    // Show a 4s confirmation. Capture the new tx's id in the toast so the
    // auto-clear setTimeout only clears THIS toast (not a newer one if the
    // user records a second transaction within 4 seconds).
    setLastSaved({ id: newTx.id, kind: tx.kind, mins: tx.mins, to: tx.to, from: tx.from });
    setTimeout(() => setLastSaved(prev => prev && prev.id === newTx.id ? null : prev), 4000);
  };

  const removeTransaction = (id) => {
    const newTransactions = timeBank.transactions.filter(t => t.id !== id);
    setTimeBank({
      balance: computeTimeBankBalance(newTransactions),
      transactions: newTransactions,
    });
  };

  const settleAll = () => {
    if (!confirm("Wipe the slate clean — set balance to zero and clear history?")) return;
    setTimeBank({ balance: 0, transactions: [] });
  };

  // Detect drift between stored balance and ledger-derived balance.
  // Should always be 0 with the new logic, but if a legacy entry had a
  // calculation bug, this surfaces it for the user with a "Recompute" button.
  const ledgerBalance = computeTimeBankBalance(timeBank.transactions);
  const storedBalance = timeBank.balance || 0;
  const driftDetected = ledgerBalance !== storedBalance;
  const recomputeBalance = () => {
    setTimeBank({
      balance: ledgerBalance,
      transactions: timeBank.transactions,
    });
  };

  return (
    <ModalShell C={C} onClose={onClose} title="Time Bank">
      {driftDetected && (
        <div style={{
          background: `${C.accent}10`,
          border: `1px solid ${C.accent}40`,
          borderRadius: 10,
          padding: "10px 12px",
          marginBottom: 12,
          fontSize: 12, color: C.ink, lineHeight: 1.5,
        }}>
          <div style={{ fontWeight: 600, color: C.accent, marginBottom: 4, display: "flex", alignItems: "center", gap: 6 }}>
            <AlertCircle size={13} /> Balance doesn't match the history
          </div>
          <div style={{ marginBottom: 8 }}>
            Stored: <strong>{fmtBalance(Math.abs(storedBalance))}</strong> {storedBalance > 0 ? "(Mommy → Daddy)" : storedBalance < 0 ? "(Daddy → Mommy)" : "(zero)"} ·{" "}
            From history: <strong>{fmtBalance(Math.abs(ledgerBalance))}</strong> {ledgerBalance > 0 ? "(Mommy → Daddy)" : ledgerBalance < 0 ? "(Daddy → Mommy)" : "(zero)"}
          </div>
          <button onClick={recomputeBalance} style={{
            background: C.accent, color: "#fff", border: "none",
            borderRadius: 8, padding: "6px 12px",
            fontSize: 11, fontWeight: 600, cursor: "pointer",
            fontFamily: "inherit",
          }}>
            Recompute from history
          </button>
        </div>
      )}
      {lastSaved && (
        <div style={{
          background: "#7B9B6E18",
          border: "1px solid #7B9B6E55",
          borderRadius: 10,
          padding: "10px 12px",
          marginBottom: 12,
          fontSize: 13, color: "#4D6B43", lineHeight: 1.5,
          display: "flex", alignItems: "center", gap: 8,
        }}>
          <Check size={14} style={{ flexShrink: 0 }} />
          <div style={{ flex: 1 }}>
            <strong>Saved.</strong>{" "}
            {lastSaved.kind === "gift"
              ? <>Gift of <strong>{fmtBalance(lastSaved.mins)}</strong> for <strong>{lastSaved.to}</strong> is now pending — they'll see it on their Now page and choose when to redeem.</>
              : lastSaved.kind === "paid"
              ? <>Payback of <strong>{fmtBalance(lastSaved.mins)}</strong> from {lastSaved.from} → {lastSaved.to} recorded. Balance updated.</>
              : <>Debt of <strong>{fmtBalance(lastSaved.mins)}</strong> recorded. {lastSaved.to} owes {lastSaved.from}.</>
            }
          </div>
        </div>
      )}
      <SegControl C={C} value={tab} onChange={setTab} options={[
        { v: "add", l: "Record" },
        { v: "history", l: `History (${timeBank.transactions.length})` },
      ]} />

      <div style={{ marginTop: 14 }}>
        {tab === "add" ? (
          <TimeBankAddForm C={C} onSubmit={recordTransaction} balance={timeBank.balance || 0} initialKind={initialKind} />
        ) : (
          <TimeBankHistory C={C} transactions={timeBank.transactions} onRemove={removeTransaction} onSettleAll={settleAll} />
        )}
      </div>
    </ModalShell>
  );
}

function TimeBankAddForm({ C, onSubmit, balance, initialKind, initialTx }) {
  // Edit mode: when initialTx is provided, pre-fill all fields. The submit
  // label changes to "Save changes" and the parent's onSubmit callback
  // gets the same shape — but it's the parent's job to replace the tx
  // (rather than append) when initialTx was passed.
  const isEdit = !!initialTx;
  const [kind, setKind] = useState(initialTx?.kind || initialKind || "owed");
  const [from, setFrom] = useState(initialTx?.from || "Daddy");
  const [to, setTo] = useState(initialTx?.to || "Mommy");
  const [mins, setMins] = useState(initialTx?.mins || 60);
  const [reason, setReason] = useState(initialTx?.reason || "");

  // Quick reason chips
  const REASONS = {
    owed: ["Took my shift while I napped", "Covered an extra hour", "Handled bedtime", "Took early morning"],
    gift: ["Sleep in", "Self-care time", "Hobby time", "Gym session"],
    paid: ["Covered overnight", "Took weekend morning", "Handled bath + bed", "Extra shift today"],
  };

  const fromColor = from === "Mommy" ? C.mommy : C.daddy;
  const toColor = to === "Mommy" ? C.mommy : C.daddy;

  const swapDirection = () => {
    setFrom(to);
    setTo(from);
  };

  return (
    <>
      <Field C={C} label="What kind?">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 6 }}>
          {[
            { v: "owed", l: "Owed", emoji: "⏰", desc: "covered my shift" },
            { v: "gift", l: "Gift", emoji: "🎁", desc: "no payback" },
            { v: "paid", l: "Paid back", emoji: "✓", desc: "settling up" },
          ].map(o => (
            <button key={o.v} onClick={() => setKind(o.v)} style={{
              background: kind === o.v ? C.accent : C.bg,
              color: kind === o.v ? "#fff" : C.ink,
              border: `1.5px solid ${kind === o.v ? C.accent : C.line + "22"}`,
              borderRadius: 10, padding: "10px 6px", cursor: "pointer",
              display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
            }}>
              <span style={{ fontSize: 18 }}>{o.emoji}</span>
              <span style={{ fontSize: 12, fontWeight: 600 }}>{o.l}</span>
              <span style={{ fontSize: 9, opacity: 0.85 }}>{o.desc}</span>
            </button>
          ))}
        </div>
      </Field>

      <Field C={C} label={
        kind === "owed" ? "Who covered for whom?"
        : kind === "gift" ? "Who's giving the gift?"
        : "Who's paying back?"
      }>
        <div style={{
          background: `${C.line}08`, borderRadius: 12, padding: 12,
          display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
        }}>
          <div style={{ flex: 1, textAlign: "center" }}>
            <div style={{ fontSize: 9, letterSpacing: "0.2em", textTransform: "uppercase", color: C.muted, fontWeight: 600 }}>
              {kind === "owed" ? "Covered" : kind === "gift" ? "From" : "From"}
            </div>
            <div style={{
              fontFamily: "'Cormorant Garamond', serif", fontSize: 24, fontWeight: 500,
              color: fromColor, marginTop: 2,
            }}>
              {from}
            </div>
          </div>
          <button onClick={swapDirection} style={{
            background: C.paper, color: C.ink, border: `1px solid ${C.line}33`,
            borderRadius: "50%", width: 36, height: 36, cursor: "pointer",
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>
            <ArrowRightLeft size={14} />
          </button>
          <div style={{ flex: 1, textAlign: "center" }}>
            <div style={{ fontSize: 9, letterSpacing: "0.2em", textTransform: "uppercase", color: C.muted, fontWeight: 600 }}>
              {kind === "owed" ? "For" : kind === "gift" ? "To" : "To"}
            </div>
            <div style={{
              fontFamily: "'Cormorant Garamond', serif", fontSize: 24, fontWeight: 500,
              color: toColor, marginTop: 2,
            }}>
              {to}
            </div>
          </div>
        </div>
      </Field>

      <Field C={C} label="How much time?">
        <BigNumberPicker C={C} value={mins} onChange={setMins} step={15} presets={[15, 30, 60, 90, 120, 180]} unit="MINUTES" />
      </Field>

      <Field C={C} label="Reason (optional)">
        <div style={{ display: "flex", gap: 5, flexWrap: "wrap", marginBottom: 6 }}>
          {REASONS[kind].map(r => (
            <button key={r} onClick={() => setReason(r)} style={{
              background: reason === r ? C.ink : "transparent",
              color: reason === r ? C.paper : C.ink,
              border: `1px solid ${C.line}33`, borderRadius: 14,
              padding: "4px 10px", fontSize: 11, cursor: "pointer",
            }}>
              {r}
            </button>
          ))}
        </div>
        <TextInput C={C} value={reason} onChange={setReason} placeholder="or write your own…" />
      </Field>

      {/* Preview */}
      <div style={{ background: C.bg, borderRadius: 8, padding: 10, fontSize: 12, color: C.muted, marginBottom: 12, lineHeight: 1.5 }}>
        <strong style={{ color: C.ink }}>Preview:</strong>{" "}
        {kind === "owed" && <span><span style={{ color: fromColor, fontWeight: 600 }}>{from}</span> covered {fmtBalance(mins)} for <span style={{ color: toColor, fontWeight: 600 }}>{to}</span> → {to} owes {from} {fmtBalance(mins)}.</span>}
        {kind === "gift" && <span><span style={{ color: fromColor, fontWeight: 600 }}>{from}</span> gifts {fmtBalance(mins)} to <span style={{ color: toColor, fontWeight: 600 }}>{to}</span> · {to} chooses when to redeem.</span>}
        {kind === "paid" && <span><span style={{ color: fromColor, fontWeight: 600 }}>{from}</span> pays back {fmtBalance(mins)} to <span style={{ color: toColor, fontWeight: 600 }}>{to}</span> · debt reduced.</span>}
      </div>

      <SubmitButton C={C} onClick={() => onSubmit({ kind, from, to, mins: Number(mins), reason: reason.trim() })}>
        {isEdit ? "Save changes" : kind === "owed" ? "Log debt" : kind === "gift" ? "Log gift" : "Log payback"}
      </SubmitButton>
    </>
  );
}

function TimeBankHistory({ C, transactions, onRemove, onSettleAll }) {
  if (transactions.length === 0) {
    return (
      <div style={{ background: C.paper, borderRadius: 12, padding: 24, border: `1px solid ${C.line}15`, textAlign: "center" }}>
        <div style={{ fontSize: 14, color: C.muted, fontStyle: "italic" }}>No transactions yet.</div>
      </div>
    );
  }
  const sorted = [...transactions].sort((a, b) => new Date(b.ts) - new Date(a.ts));
  return (
    <>
      <div style={{ display: "grid", gap: 6, maxHeight: 400, overflowY: "auto" }}>
        {sorted.map(tx => {
          const fromColor = tx.from === "Mommy" ? C.mommy : C.daddy;
          const toColor = tx.to === "Mommy" ? C.mommy : C.daddy;
          const emoji = tx.kind === "owed" ? "⏰" : tx.kind === "gift" ? "🎁" : "✓";
          return (
            <div key={tx.id} style={{
              background: C.paper, borderRadius: 10, padding: "10px 12px",
              border: `1px solid ${C.line}15`,
              display: "flex", alignItems: "center", gap: 10,
            }}>
              <span style={{ fontSize: 18 }}>{emoji}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, color: C.ink, display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <span>
                    <span style={{ color: fromColor, fontWeight: 600 }}>{tx.from}</span>
                    {tx.kind === "owed" && " covered "}
                    {tx.kind === "gift" && " gifted "}
                    {tx.kind === "paid" && " paid back "}
                    <strong>{fmtBalance(tx.mins)}</strong>
                    {" "}{tx.kind === "owed" ? "for" : "to"}{" "}
                    <span style={{ color: toColor, fontWeight: 600 }}>{tx.to}</span>
                  </span>
                  {tx.kind === "gift" && (
                    tx.redeemed ? (
                      <span style={{
                        fontSize: 10, fontWeight: 700, letterSpacing: "0.04em",
                        background: "#7B9B6E25", color: "#4D6B43",
                        padding: "2px 6px", borderRadius: 4, textTransform: "uppercase",
                      }}>✓ Redeemed</span>
                    ) : (
                      <span style={{
                        fontSize: 10, fontWeight: 700, letterSpacing: "0.04em",
                        background: `${C.gold}25`, color: "#7A5A00",
                        padding: "2px 6px", borderRadius: 4, textTransform: "uppercase",
                      }}>Pending</span>
                    )
                  )}
                </div>
                {tx.reason && (
                  <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic", marginTop: 2 }}>
                    {tx.reason}
                  </div>
                )}
                {tx.redeemed && (
                  <div style={{ fontSize: 10, color: C.muted, fontFamily: "'JetBrains Mono', monospace", marginTop: 2 }}>
                    redeemed {new Date(tx.redeemed.at).toLocaleDateString(undefined, { month: "short", day: "numeric" })} · used {fmtTimeShort(new Date(tx.redeemed.blockStart))}
                  </div>
                )}
                <div style={{ fontSize: 10, color: C.muted, fontFamily: "'JetBrains Mono', monospace", marginTop: 2 }}>
                  {new Date(tx.ts).toLocaleDateString(undefined, { month: "short", day: "numeric" })} · {fmtTimeShort(new Date(tx.ts))}
                </div>
              </div>
              <button onClick={() => onRemove(tx.id)} style={{
                background: "transparent", border: "none", color: C.muted, cursor: "pointer", padding: 4, opacity: 0.5,
              }}>
                <Trash2 size={13} />
              </button>
            </div>
          );
        })}
      </div>

      <button onClick={onSettleAll} style={{
        marginTop: 14, width: "100%",
        background: "transparent", color: C.muted, border: `1px dashed ${C.line}33`, borderRadius: 10,
        padding: 10, fontSize: 12, cursor: "pointer",
      }}>
        Wipe slate clean (zero everything)
      </button>
    </>
  );
}

// Redeem modal: cash in owed time as a shift cover by partner
function RedeemModal({ C, timeBank, setTimeBank, setMeetings, currentUser, currentlyOnShift, now, onClose }) {
  const balance = timeBank.balance || 0;
  const partner = currentUser === "Mommy" ? "Daddy" : "Mommy";
  const partnerColor = currentUser === "Mommy" ? C.daddy : C.mommy;
  const owedToYou = (currentUser === "Mommy" && balance < 0) || (currentUser === "Daddy" && balance > 0)
    ? Math.abs(balance) : 0;

  const [mins, setMins] = useState(Math.min(owedToYou, 120));
  // v05.05bt165 — Default to "pick" when the user is not currently on
  // their shift (per chat: "Redeem right now is an issue if my shift
  // hasn't started"). Redeeming for "now" only makes sense when the
  // partner would actually be covering an active shift; otherwise the
  // window has no shift to swap and the redemption is wasted.
  const [whenChoice, setWhenChoice] = useState(currentlyOnShift ? "now" : "pick");
  const [pickedDateTime, setPickedDateTime] = useState(() => {
    const d = new Date();
    d.setHours(d.getHours() + 1);
    d.setMinutes(0);
    return d.toISOString().slice(0, 16);
  });
  const [reason, setReason] = useState("");

  const handleSubmit = () => {
    const startTime = whenChoice === "now" ? new Date(now) : new Date(pickedDateTime);
    const endTime = new Date(startTime.getTime() + mins * 60000);
    // Create a red commitment for currentUser → projection auto-swaps to partner covering
    const newMeeting = {
      id: crypto.randomUUID(),
      parent: currentUser,
      level: "red",
      label: `Time bank: ${reason || "cashed in"}${reason ? "" : " owed time"}`,
      start: startTime.toISOString(),
      end: endTime.toISOString(),
    };
    setMeetings(prev => {
      const next = [...prev, newMeeting];
      try {
        localStorage.setItem("solene:meetings", JSON.stringify(next));
        localStorage.setItem("solene:meetings:backup", JSON.stringify(prev));
      } catch (e) { console.warn("[redeem addMeeting] sync persist failed", e); }
      return next;
    });
    // Record the payback transaction (partner is "paying" currentUser their owed time)
    const newTx = {
      id: crypto.randomUUID(),
      ts: new Date().toISOString(),
      kind: "paid",
      from: partner,
      to: currentUser,
      mins,
      reason: `Cashed in ${reason || "owed time"}`,
    };
    const newTransactions = [...timeBank.transactions, newTx];
    setTimeBank({
      balance: computeTimeBankBalance(newTransactions),
      transactions: newTransactions,
    });
    onClose();
  };

  return (
    <ModalShell C={C} onClose={onClose} title="Cash in owed time">
      <div style={{
        background: `${partnerColor}15`, borderRadius: 10, padding: 12, marginBottom: 14,
        border: `1px solid ${partnerColor}33`, fontSize: 13, color: C.ink, lineHeight: 1.5,
      }}>
        <strong style={{ color: partnerColor }}>{partner}</strong> owes you{" "}
        <strong>{fmtBalance(owedToYou)}</strong>. Pick how much to redeem and when —
        the shift will auto-flip to {partner} covering for you, and the debt reduces.
      </div>

      <Field C={C} label="How much time?">
        <BigNumberPicker C={C} value={mins} onChange={setMins} step={5}
          presets={[15, 30, 60, 90, 120, 180, 240].filter(p => p <= owedToYou)}
          unit="MINUTES" />
        {mins > owedToYou && (
          <div style={{ fontSize: 11, color: C.accent, marginTop: 4 }}>
            ⚠ exceeds owed balance — the rest will become a new debt
          </div>
        )}
      </Field>

      <Field C={C} label="When?">
        <SegControl C={C} value={whenChoice} onChange={setWhenChoice} options={[
          { v: "now", l: "Right now" },
          { v: "pick", l: "Pick a time" },
        ]} />
        {/* v05.05bt165 — Hint when currentUser isn't on shift. */}
        {!currentlyOnShift && whenChoice === "now" && (
          <div style={{
            fontSize: 11, color: C.accent, fontStyle: "italic",
            marginTop: 6, lineHeight: 1.4,
          }}>
            ⚠ You're not currently on shift, so "right now" has nothing to redeem against. Pick a time during your shift instead.
          </div>
        )}
        {whenChoice === "pick" && (
          <div style={{ marginTop: 8 }}>
            <DateTimeInput C={C} value={pickedDateTime} onChange={setPickedDateTime} />
          </div>
        )}
      </Field>

      <Field C={C} label="What for? (optional)">
        <div style={{ display: "flex", gap: 5, flexWrap: "wrap", marginBottom: 6 }}>
          {["Nap", "Self-care", "Workout", "Shower", "Hobby time", "Just need a break"].map(r => (
            <button key={r} onClick={() => setReason(r)} style={{
              background: reason === r ? C.ink : "transparent",
              color: reason === r ? C.paper : C.ink,
              border: `1px solid ${C.line}33`, borderRadius: 14,
              padding: "4px 10px", fontSize: 11, cursor: "pointer",
            }}>
              {r}
            </button>
          ))}
        </div>
        <TextInput C={C} value={reason} onChange={setReason} placeholder="or write your own…" />
      </Field>

      <SubmitButton C={C} onClick={handleSubmit}>
        Redeem {fmtBalance(mins)} — {partner} covers
      </SubmitButton>
    </ModalShell>
  );
}

// ---- BankView ----------------------------------------------------------
// Standalone tab for time bank management. Acts like a real bank app —
// balance hero card at top, quick action buttons below, transaction
// ledger with filter pills, drill-down on each transaction.
//
// Lives separate from Schedule because time-bank accounting is its own
// mental model: credits / debits / gifts that flow between two parents.
// Mixing it with shift scheduling made both feel cluttered.
function BankView({ C, timeBank, setTimeBank, setMeetings, now, currentUser, currentlyOnShift, pendingTimeBankAction, clearPendingTimeBankAction }) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [addInitialMode, setAddInitialMode] = useState(null); // "owed" | "gift" | "paid" | null
  const [editingTx, setEditingTx] = useState(null); // tx being edited; when set, shows the form pre-filled
  const [showRedeem, setShowRedeem] = useState(false);
  const [filter, setFilter] = useState("all"); // "all" | "gifts" | "debts" | "paybacks"

  // Honor deep-link pending action (e.g. from LOG sheet pills)
  // Maps action → addInitialMode (the form's `kind` field):
  //   "owed"    → "owed"   (log a debt — partner covered for me)
  //   "gift"    → "gift"   (gift time, no payback expected)
  //   "payback" → "paid"   (settle a debt)
  useEffect(() => {
    if (!pendingTimeBankAction) return;
    const modeMap = { owed: "owed", gift: "gift", payback: "paid" };
    setAddInitialMode(modeMap[pendingTimeBankAction] || "owed");
    setShowAddModal(true);
    clearPendingTimeBankAction && clearPendingTimeBankAction();
  }, [pendingTimeBankAction, clearPendingTimeBankAction]);

  const transactions = timeBank.transactions || [];
  // Always recompute from history. If the cached `balance` field drifted
  // (e.g. from an old build that mishandled a transaction kind, or a sync
  // race), the displayed number was wrong. Recomputing on each render
  // guarantees the displayed balance always reflects the visible ledger.
  const balance = computeTimeBankBalance(transactions);
  const partner = currentUser === "Mommy" ? "Daddy" : "Mommy";
  const partnerColor = currentUser === "Mommy" ? C.daddy : C.mommy;
  const youColor = currentUser === "Mommy" ? C.mommy : C.daddy;

  // Auto-heal the cached balance if it's drifted. This silently keeps the
  // stored state in sync with the ledger so other views (Now's pip, etc.)
  // also show the correct number on next render.
  useEffect(() => {
    if ((timeBank.balance || 0) !== balance) {
      setTimeBank({ ...timeBank, balance });
    }
  }, [balance, timeBank, setTimeBank]);

  // From currentUser's POV — direction language matches the modal
  let directionLabel, primaryColor, youOwe;
  if (balance === 0) {
    directionLabel = "All square";
    primaryColor = C.ink;
    youOwe = null;
  } else if (
    (balance > 0 && currentUser === "Mommy") ||
    (balance < 0 && currentUser === "Daddy")
  ) {
    directionLabel = `You owe ${partner}`;
    primaryColor = partnerColor;
    youOwe = true;
  } else {
    directionLabel = `${partner} owes you`;
    primaryColor = youColor;
    youOwe = false;
  }

  // Breakdown for the +/- summary
  const breakdown = useMemo(() => {
    let giftsReceived = 0, giftsGiven = 0, debtsOwedToYou = 0, debtsYouOwe = 0, payback = 0;
    for (const tx of transactions) {
      const m = tx.mins || 0;
      if (tx.kind === "gift") {
        if (tx.to === currentUser) giftsReceived += m;
        else if (tx.from === currentUser) giftsGiven += m;
      } else if (tx.kind === "owed") {
        if (tx.to === currentUser) debtsYouOwe += m;
        else if (tx.from === currentUser) debtsOwedToYou += m;
      } else if (tx.kind === "paid") {
        payback += m;
      }
    }
    return { giftsReceived, giftsGiven, debtsOwedToYou, debtsYouOwe, payback };
  }, [transactions, currentUser]);

  const positiveTotal = breakdown.giftsReceived + breakdown.debtsOwedToYou;
  const negativeTotal = breakdown.giftsGiven + breakdown.debtsYouOwe;

  // Filter transactions for the ledger
  const filtered = useMemo(() => {
    let result = [...transactions];
    if (filter === "gifts") result = result.filter(t => t.kind === "gift");
    else if (filter === "debts") result = result.filter(t => t.kind === "owed");
    else if (filter === "paybacks") result = result.filter(t => t.kind === "paid");
    return result.sort((a, b) => new Date(b.ts) - new Date(a.ts));
  }, [transactions, filter]);

  const counts = useMemo(() => ({
    all: transactions.length,
    gifts: transactions.filter(t => t.kind === "gift").length,
    debts: transactions.filter(t => t.kind === "owed").length,
    paybacks: transactions.filter(t => t.kind === "paid").length,
  }), [transactions]);

  // Drift detection — for the recompute button
  const ledgerBalance = computeTimeBankBalance(transactions);
  const driftDetected = ledgerBalance !== balance;
  const recomputeBalance = () => {
    setTimeBank({ balance: ledgerBalance, transactions });
  };

  const removeTransaction = (id) => {
    const newTransactions = transactions.filter(t => t.id !== id);
    setTimeBank({ balance: computeTimeBankBalance(newTransactions), transactions: newTransactions });
  };

  const recordTransaction = (tx) => {
    const newTx = { ...tx, id: crypto.randomUUID(), ts: new Date().toISOString() };
    const newTransactions = [...transactions, newTx];
    setTimeBank({ balance: computeTimeBankBalance(newTransactions), transactions: newTransactions });
  };

  // Update an existing transaction in place. Preserves id, original
  // timestamp, and any side-channel fields like .redeemed (so editing a
  // redeemed gift's reason doesn't accidentally un-redeem it). The
  // mutable shape is only what TimeBankAddForm owns: kind, from, to,
  // mins, reason. Balance is recomputed from history afterward.
  const updateTransaction = (id, patch) => {
    const newTransactions = transactions.map(t =>
      t.id === id ? { ...t, ...patch } : t
    );
    setTimeBank({ balance: computeTimeBankBalance(newTransactions), transactions: newTransactions });
  };

  const FILTERS = [
    { v: "all",      l: "All" },
    { v: "debts",    l: "Debts" },
    { v: "gifts",    l: "Gifts" },
    { v: "paybacks", l: "Paybacks" },
  ];

  return (
    <div style={{ marginTop: 14 }}>
      {/* === Balance hero card === */}
      <div style={{
        background: balance === 0
          ? C.paper
          : `linear-gradient(135deg, ${primaryColor}22, ${C.paper})`,
        border: `1px solid ${C.line}15`,
        borderLeft: balance === 0 ? `1px solid ${C.line}15` : `4px solid ${primaryColor}`,
        borderRadius: 14, padding: 18,
        marginBottom: 12,
      }}>
        <div style={{ fontSize: 10, letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontWeight: 600 }}>
          Time bank
        </div>
        <div style={{
          fontFamily: "'Cormorant Garamond', serif",
          fontSize: 14, fontStyle: "italic", color: C.muted, marginTop: 2,
        }}>
          {directionLabel}
        </div>
        <div style={{
          fontFamily: "'Cormorant Garamond', serif",
          fontSize: balance === 0 ? 36 : 44,
          fontWeight: 500,
          color: balance === 0 ? C.ink : primaryColor,
          lineHeight: 1, marginTop: 6,
          fontStyle: balance === 0 ? "italic" : "normal",
        }}>
          {balance === 0 ? "no debts" : fmtBalance(balance)}
        </div>

        {/* +/- breakdown */}
        {transactions.length > 0 && (positiveTotal > 0 || negativeTotal > 0) && (
          <div style={{
            marginTop: 14, paddingTop: 10,
            borderTop: `1px solid ${C.line}15`,
            display: "flex", alignItems: "center", gap: 16,
            fontSize: 12, fontFamily: "'JetBrains Mono', monospace",
          }}>
            {positiveTotal > 0 && (
              <span style={{ color: "#4F6E4D", fontWeight: 600 }}>
                +{fmtBalance(positiveTotal)}
                <span style={{ color: C.muted, fontWeight: 400, marginLeft: 5 }}>received</span>
              </span>
            )}
            {negativeTotal > 0 && (
              <span style={{ color: C.accent, fontWeight: 600 }}>
                −{fmtBalance(negativeTotal)}
                <span style={{ color: C.muted, fontWeight: 400, marginLeft: 5 }}>given</span>
              </span>
            )}
          </div>
        )}

        {/* Recompute drift warning */}
        {driftDetected && (
          <div style={{
            marginTop: 12,
            background: `${C.accent}10`,
            border: `1px solid ${C.accent}40`,
            borderRadius: 8, padding: "8px 10px",
            fontSize: 11, color: C.ink,
          }}>
            <div style={{ color: C.accent, fontWeight: 600, marginBottom: 4, display: "flex", alignItems: "center", gap: 5 }}>
              <AlertCircle size={11} /> Balance doesn't match the history
            </div>
            <button onClick={recomputeBalance} style={{
              background: C.accent, color: "#fff", border: "none",
              borderRadius: 6, padding: "4px 10px",
              fontSize: 10, fontWeight: 600, cursor: "pointer",
              fontFamily: "inherit",
            }}>
              Recompute from history
            </button>
          </div>
        )}
      </div>

      {/* === Quick actions ===
          v05.05bt39: 4-column grid (was 3). Redeem promoted from
          conditional standalone button to a permanent quick-action so it's
          always discoverable. When ineligible (you currently owe, or
          partner's debt is <30m), the tile renders disabled with explanatory
          micro-copy below the grid; when eligible, primary-colored. */}
      {(() => {
        const canRedeem = youOwe === false && Math.abs(balance) >= 1;
        return (
          <>
            <div style={{
              display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr",
              gap: 8, marginBottom: canRedeem ? 8 : 6,
            }}>
              <button onClick={() => { setAddInitialMode("owed"); setShowAddModal(true); }} style={{
                background: C.paper, border: `1.5px solid ${C.line}30`,
                borderRadius: 10, padding: "12px 6px",
                cursor: "pointer", fontFamily: "inherit",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
              }}>
                <ArrowRightLeft size={16} color={C.accent} />
                <span style={{ fontSize: 11, fontWeight: 600, color: C.ink }}>Log debt</span>
              </button>
              <button onClick={() => { setAddInitialMode("gift"); setShowAddModal(true); }} style={{
                background: C.paper, border: `1.5px solid ${C.line}30`,
                borderRadius: 10, padding: "12px 6px",
                cursor: "pointer", fontFamily: "inherit",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
              }}>
                <Gift size={16} color={C.gold} />
                <span style={{ fontSize: 11, fontWeight: 600, color: C.ink }}>Send gift</span>
              </button>
              <button onClick={() => { setAddInitialMode("paid"); setShowAddModal(true); }} style={{
                background: C.paper, border: `1.5px solid ${C.line}30`,
                borderRadius: 10, padding: "12px 6px",
                cursor: "pointer", fontFamily: "inherit",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
              }}>
                <Check size={16} color={youColor} />
                <span style={{ fontSize: 11, fontWeight: 600, color: C.ink }}>Log payback</span>
              </button>
              {/* Redeem — permanent fourth tile. Eligible: primary-colored
                  with subtle glow. Ineligible: disabled, muted, no hover. */}
              <button
                onClick={canRedeem ? () => setShowRedeem(true) : undefined}
                disabled={!canRedeem}
                style={{
                  background: canRedeem ? youColor : C.paper,
                  border: canRedeem ? "none" : `1.5px solid ${C.line}30`,
                  borderRadius: 10, padding: "12px 6px",
                  cursor: canRedeem ? "pointer" : "not-allowed",
                  fontFamily: "inherit",
                  display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
                  opacity: canRedeem ? 1 : 0.55,
                  boxShadow: canRedeem ? `0 2px 8px ${youColor}55` : "none",
                  transition: "opacity 0.2s, box-shadow 0.2s",
                }}>
                <Sparkles size={16} color={canRedeem ? "#fff" : C.muted} />
                <span style={{
                  fontSize: 11, fontWeight: 600,
                  color: canRedeem ? "#fff" : C.muted,
                }}>
                  Redeem
                </span>
              </button>
            </div>
            {/* Helper line — explains why Redeem is disabled, OR what
                Redeem will do when eligible. Always renders so the user
                understands the affordance. */}
            <div style={{
              fontSize: 10, color: C.muted, fontStyle: "italic",
              marginBottom: 14, lineHeight: 1.45,
              padding: "0 2px",
            }}>
              {canRedeem ? (
                <>
                  ✦ <strong style={{ color: youColor, fontStyle: "normal", fontWeight: 600 }}>Redeem</strong> available — pick a day &amp; time and {partner} will auto-cover that shift, drawing down your{" "}
                  <strong style={{ color: youColor, fontStyle: "normal", fontWeight: 600 }}>{fmtBalance(Math.abs(balance))}</strong>.
                </>
              ) : balance === 0 ? (
                <>Redeem unlocks once {partner} owes you any coverage time.</>
              ) : (
                <>Redeem is for the creditor — right now {partner} is owed, so you can't redeem (you'd log a payback to settle).</>
              )}
            </div>
          </>
        );
      })()}

      {/* === Hero redeem CTA — large primary button shown when there's any
          positive credit. v05.05bt41: lowered from ≥30m to ≥1m per user
          feedback. The picker step in RedeemModal is now 5m, so even
          small balances (e.g. 12m) can be redeemed without awkward picker
          friction. */}
      {youOwe === false && Math.abs(balance) >= 1 && (
        <button onClick={() => setShowRedeem(true)} style={{
          width: "100%", marginBottom: 14,
          background: youColor, color: "#fff", border: "none",
          padding: "14px 18px", borderRadius: 10,
          fontSize: 14, fontWeight: 600, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          fontFamily: "inherit",
          boxShadow: `0 2px 8px ${youColor}55`,
        }}>
          <Gift size={16} /> Cash in {fmtBalance(Math.abs(balance))} — pick day &amp; time
        </button>
      )}

      {/* === Transaction ledger === */}
      <Section C={C} title={`Ledger · ${transactions.length} transaction${transactions.length === 1 ? "" : "s"}`}>
        {transactions.length === 0 ? (
          <div style={{
            background: C.paper, borderRadius: 12, padding: 20,
            border: `1px solid ${C.line}15`, textAlign: "center",
          }}>
            <div style={{
              fontFamily: "'Cormorant Garamond', serif", fontSize: 18,
              fontStyle: "italic", color: C.muted,
            }}>
              No transactions yet.
            </div>
            <div style={{ fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 1.5 }}>
              When one parent covers for the other (or gifts time, or pays back),
              log it here. The bank tracks who's ahead and who's behind.
            </div>
          </div>
        ) : (
          <>
            {/* Filter pills */}
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
              {FILTERS.map(f => {
                const active = filter === f.v;
                return (
                  <button key={f.v} onClick={() => setFilter(f.v)} style={{
                    background: active ? C.accent : "transparent",
                    color: active ? "#fff" : C.ink,
                    border: `1px solid ${active ? C.accent : C.line + "40"}`,
                    borderRadius: 999, padding: "5px 11px",
                    fontSize: 11, fontWeight: 600, cursor: "pointer",
                    fontFamily: "inherit",
                    display: "inline-flex", alignItems: "center", gap: 5,
                  }}>
                    {f.l}
                    <span style={{
                      fontSize: 10, opacity: active ? 0.85 : 0.6,
                      fontFamily: "'JetBrains Mono', monospace", fontWeight: 500,
                    }}>{counts[f.v]}</span>
                  </button>
                );
              })}
            </div>

            {/* Transaction rows */}
            {filtered.length === 0 ? (
              <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic", textAlign: "center", padding: 20 }}>
                No {filter} in the ledger.
              </div>
            ) : (
              <div style={{ display: "grid", gap: 8 }}>
                {filtered.map(tx => {
                  const fromColor = tx.from === "Mommy" ? C.mommy : C.daddy;
                  const toColor = tx.to === "Mommy" ? C.mommy : C.daddy;
                  const kindIcon = tx.kind === "gift" ? "🎁" : tx.kind === "paid" ? "✓" : "⇄";
                  const kindLabel = tx.kind === "gift" ? "GIFT" : tx.kind === "paid" ? "PAYBACK" : "DEBT";
                  const kindColor = tx.kind === "gift" ? C.gold : tx.kind === "paid" ? C.mommy : C.accent;
                  const date = new Date(tx.ts);
                  const isRedeemed = tx.kind === "gift" && tx.redeemed;
                  return (
                    <div key={tx.id} style={{
                      background: C.paper, borderRadius: 10,
                      padding: "10px 12px",
                      border: `1px solid ${C.line}15`,
                      borderLeft: `3px solid ${kindColor}`,
                      display: "flex", flexDirection: "column", gap: 4,
                    }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <span style={{
                          fontSize: 9, letterSpacing: "0.16em", fontWeight: 700,
                          background: `${kindColor}18`, color: kindColor,
                          padding: "2px 7px", borderRadius: 4,
                        }}>
                          {kindIcon} {kindLabel}
                        </span>
                        <span style={{
                          fontFamily: "'JetBrains Mono', monospace",
                          fontSize: 13, fontWeight: 600, color: C.ink,
                        }}>
                          {fmtBalance(tx.mins)}
                        </span>
                        {isRedeemed && (
                          <span style={{
                            fontSize: 9, letterSpacing: "0.12em", fontWeight: 600,
                            background: `${C.muted}18`, color: C.muted,
                            padding: "1px 6px", borderRadius: 3,
                          }}>
                            REDEEMED
                          </span>
                        )}
                        {tx.kind === "gift" && !isRedeemed && tx.to === currentUser && (
                          <span style={{
                            fontSize: 9, letterSpacing: "0.12em", fontWeight: 600,
                            background: `${C.gold}22`, color: C.gold,
                            padding: "1px 6px", borderRadius: 3,
                          }}>
                            PENDING
                          </span>
                        )}
                        <div style={{ marginLeft: "auto", display: "flex", gap: 2 }}>
                          {/* Edit — only enabled for non-redeemed transactions.
                              A redeemed gift has a downstream meeting that
                              auto-swapped coverage; editing its mins/direction
                              after redemption would create inconsistency. */}
                          {!isRedeemed && (
                            <button
                              onClick={() => setEditingTx(tx)}
                              title="Edit this transaction"
                              style={{
                                background: "transparent", border: "none",
                                color: C.muted, cursor: "pointer", padding: 2,
                                display: "flex", alignItems: "center",
                              }}>
                              <Edit3 size={12} />
                            </button>
                          )}
                          <button onClick={() => {
                            if (window.confirm(`Remove this ${kindLabel.toLowerCase()} transaction?`)) {
                              removeTransaction(tx.id);
                            }
                          }} style={{
                            background: "transparent", border: "none",
                            color: C.muted, cursor: "pointer", padding: 2,
                            display: "flex", alignItems: "center",
                          }}>
                            <X size={12} />
                          </button>
                        </div>
                      </div>
                      <div style={{ fontSize: 12, color: C.ink, lineHeight: 1.4 }}>
                        <span style={{ color: fromColor, fontWeight: 600 }}>{tx.from}</span>
                        <span style={{ color: C.muted }}>{" "}{tx.kind === "gift" ? "→ gifts to" : tx.kind === "paid" ? "→ pays back" : "covered for"}{" "}</span>
                        <span style={{ color: toColor, fontWeight: 600 }}>{tx.to}</span>
                      </div>
                      {tx.reason && (
                        <div style={{ fontSize: 11, color: C.muted, fontStyle: "italic" }}>
                          "{tx.reason}"
                        </div>
                      )}
                      <div style={{ fontSize: 10, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
                        {date.toLocaleDateString(undefined, { month: "short", day: "numeric" })} · {fmtTimeShort(date)}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </>
        )}
      </Section>

      {/* Add transaction modal — reuses the same TimeBankAddForm */}
      {showAddModal && (
        <ModalShell C={C} onClose={() => { setShowAddModal(false); setAddInitialMode(null); }} title="Record transaction">
          <TimeBankAddForm
            C={C}
            balance={balance}
            initialKind={addInitialMode}
            onSubmit={(tx) => {
              recordTransaction(tx);
              setShowAddModal(false);
              setAddInitialMode(null);
            }}
          />
        </ModalShell>
      )}

      {/* Edit modal — same form pre-filled with the transaction's current
          values. Updates in place rather than appending a new row. */}
      {editingTx && (
        <ModalShell C={C} onClose={() => setEditingTx(null)} title="Edit transaction">
          <TimeBankAddForm
            C={C}
            balance={balance}
            initialTx={editingTx}
            onSubmit={(patch) => {
              updateTransaction(editingTx.id, patch);
              setEditingTx(null);
            }}
          />
        </ModalShell>
      )}

      {showRedeem && <RedeemModal
        C={C}
        timeBank={timeBank}
        setTimeBank={setTimeBank}
        setMeetings={setMeetings}
        currentUser={currentUser}
        currentlyOnShift={currentlyOnShift}
        now={now}
        onClose={() => setShowRedeem(false)}
      />}
    </div>
  );
}

// ---- RedeemGiftModal ----------------------------------------------------
// Recipient picks WHEN to use a specific gift. The flow is intentionally
// minimal — show what gift this is, ask "now or pick a time + duration",
// then on confirm: (a) create a red Meeting for the recipient at that time
// so the shift schedule auto-swaps the giver into coverage, and (b) mark
// the gift transaction as .redeemed so it stops appearing on the recipient's
// landing page.
function RedeemGiftModal({ C, gift, timeBank, setTimeBank, setMeetings, now, onClose }) {
  const recipient = gift.to;
  const giver = gift.from;
  const giverColor = giver === "Mommy" ? C.mommy : C.daddy;
  const recipientColor = recipient === "Mommy" ? C.mommy : C.daddy;

  const [whenChoice, setWhenChoice] = useState("now"); // 'now' | 'pick'
  const [pickedDateTime, setPickedDateTime] = useState(() => {
    const d = new Date();
    d.setHours(d.getHours() + 1);
    d.setMinutes(0);
    return d.toISOString().slice(0, 16);
  });
  const [reason, setReason] = useState("");

  const handleSubmit = () => {
    const startTime = whenChoice === "now" ? new Date(now) : new Date(pickedDateTime);
    const endTime = new Date(startTime.getTime() + gift.mins * 60000);
    const meetingId = crypto.randomUUID();

    // Create a red commitment for the recipient → projection auto-assigns
    // the giver to cover. Label it as "gift" so it's distinguishable in the
    // schedule view from regular meetings.
    const newMeeting = {
      id: meetingId,
      parent: recipient,
      level: "red",
      label: `🎁 Gift from ${giver}${reason ? ` · ${reason}` : ""}`,
      start: startTime.toISOString(),
      end: endTime.toISOString(),
    };
    setMeetings(prev => {
      const next = [...prev, newMeeting];
      try { localStorage.setItem("solene:meetings", JSON.stringify(next)); } catch {}
      return next;
    });

    // Mark the gift as redeemed (don't add a new transaction; just update
    // the existing one). This keeps the gift's history intact while
    // preventing it from re-appearing on the landing page.
    const newTransactions = (timeBank.transactions || []).map(t =>
      t.id === gift.id
        ? { ...t, redeemed: { at: new Date().toISOString(), blockStart: startTime.toISOString(), blockEnd: endTime.toISOString(), meetingId } }
        : t
    );
    setTimeBank({
      balance: computeTimeBankBalance(newTransactions),
      transactions: newTransactions,
    });
    onClose();
  };

  return (
    <ModalShell C={C} onClose={onClose} title="Redeem gift">
      <div style={{
        background: `${giverColor}15`,
        border: `1px solid ${giverColor}40`,
        borderRadius: 10,
        padding: 14,
        marginBottom: 16,
      }}>
        <div style={{ fontSize: 13, color: C.ink, lineHeight: 1.55, marginBottom: 8 }}>
          🎁 <strong style={{ color: giverColor }}>{giver}</strong> gifted you{" "}
          <strong>{fmtBalance(gift.mins)}</strong> off-duty time
          {gift.reason ? <> for <em>{gift.reason}</em></> : null}
          .
        </div>
        <div style={{ fontSize: 11, color: C.muted, fontFamily: "'JetBrains Mono', monospace" }}>
          Logged {new Date(gift.ts).toLocaleDateString(undefined, { month: "short", day: "numeric" })} at {fmtTimeShort(new Date(gift.ts))}
        </div>
      </div>

      <Field C={C} label="When do you want to use it?">
        <SegControl C={C} value={whenChoice} onChange={setWhenChoice} options={[
          { v: "now", l: "Right now" },
          { v: "pick", l: "Pick a time" },
        ]} />
      </Field>

      {whenChoice === "pick" && (
        <Field C={C} label="Start">
          <input type="datetime-local"
            value={pickedDateTime}
            onChange={(e) => setPickedDateTime(e.target.value)}
            style={{
              width: "100%", padding: 10, fontSize: 14,
              background: C.bg, border: `1px solid ${C.line}33`,
              borderRadius: 8, color: C.ink, outline: "none",
              fontFamily: "inherit",
            }} />
        </Field>
      )}

      <Field C={C} label="Optional note">
        <input type="text"
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          placeholder="nap, gym, errand…"
          style={{
            width: "100%", padding: 10, fontSize: 14,
            background: C.bg, border: `1px solid ${C.line}33`,
            borderRadius: 8, color: C.ink, outline: "none",
            fontFamily: "inherit",
          }} />
      </Field>

      {(() => {
        const startTime = whenChoice === "now" ? new Date(now) : new Date(pickedDateTime);
        const endTime = new Date(startTime.getTime() + gift.mins * 60000);
        const startDate = new Date(startTime);
        startDate.setHours(0, 0, 0, 0);
        const todayDate = new Date(now);
        todayDate.setHours(0, 0, 0, 0);
        const daysAhead = Math.round((startDate - todayDate) / 86400000);
        // We compute live shift swaps for today and tomorrow only. Beyond
        // that, the meeting is recorded but the visible auto-swap doesn't
        // appear in any pre-computed view until that day becomes today
        // or tomorrow. Surface this so the user knows what to expect.
        const isFarFuture = daysAhead >= 2;
        return (
          <div style={{
            background: C.bg, borderRadius: 8, padding: 10,
            fontSize: 12, color: C.muted, marginBottom: 14, lineHeight: 1.5,
          }}>
            <div style={{ marginBottom: isFarFuture ? 6 : 0 }}>
              <strong style={{ color: C.ink }}>What happens:</strong>{" "}
              You go off-duty for{" "}
              <strong>{fmtBalance(gift.mins)}</strong>{" "}
              starting{" "}
              <strong>
                {whenChoice === "now" ? "right now" : new Date(pickedDateTime).toLocaleString(undefined, { weekday: "short", hour: "numeric", minute: "2-digit" })}
              </strong>.{" "}
              <span style={{ color: giverColor, fontWeight: 600 }}>{giver}</span>{" "}
              {daysAhead === 0 ? "covers — today's shifts auto-adjust immediately." :
               daysAhead === 1 ? "covers — tomorrow's shifts auto-adjust on the Schedule tab." :
                                 "covers — a commitment block is created for that day."}
            </div>
            {isFarFuture && (
              <div style={{
                fontSize: 11, color: C.gold, fontStyle: "italic",
                paddingTop: 6, borderTop: `1px solid ${C.line}15`,
              }}>
                Note: shift auto-swap is computed for today and tomorrow only. The block is saved and will appear in coverage when {daysAhead === 2 ? "the day after tomorrow" : "that day"} becomes tomorrow.
              </div>
            )}
          </div>
        );
      })()}

      <SubmitButton C={C} onClick={handleSubmit}>
        Redeem · {giver} covers {fmtBalance(gift.mins)}
      </SubmitButton>
    </ModalShell>
  );
}

function ActiveOnsiteCard({ C, onsite, now, onUpdateEta, onArrived }) {
  const awayColor = onsite.parent === "Mommy" ? C.mommy : C.daddy;
  const homeColor = onsite.parent === "Mommy" ? C.daddy : C.mommy;
  const homeParent = onsite.parent === "Mommy" ? "Daddy" : "Mommy";
  const departure = new Date(onsite.departedAt);
  const earliest = new Date(onsite.earliestReturn);
  const latest = new Date(onsite.latestReturn);
  const etaUpdate = onsite.etaUpdate ? new Date(onsite.etaUpdate) : null;
  const effectiveReturn = etaUpdate || latest;

  const minsAway = Math.round((now - departure) / 60000);
  const hoursAway = Math.floor(minsAway / 60);
  const minsRemainder = minsAway % 60;
  const minsToReturn = Math.round((effectiveReturn - now) / 60000);

  return (
    <div style={{
      background: `linear-gradient(135deg, ${awayColor}15, ${C.paper})`,
      borderRadius: 12, padding: 16,
      border: `2px solid ${awayColor}55`,
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
        <div style={{
          width: 36, height: 36, borderRadius: "50%",
          background: awayColor, display: "flex", alignItems: "center", justifyContent: "center",
          color: "#fff", flexShrink: 0,
        }}>
          <MapPin size={18} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 20, fontWeight: 500, lineHeight: 1.1, color: awayColor }}>
            {onsite.parent} is on-site
          </div>
          <div style={{ fontSize: 11, color: C.muted, marginTop: 2, fontFamily: "'JetBrains Mono', monospace" }}>
            left {fmtTimeShort(departure)} · {hoursAway > 0 ? `${hoursAway}h ${minsRemainder}m` : `${minsRemainder}m`} ago
          </div>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 12 }}>
        <div style={{ background: C.bg, borderRadius: 8, padding: "10px 12px" }}>
          <div style={{ fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase", color: C.muted, fontWeight: 500 }}>
            Earliest back
          </div>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, fontWeight: 500, marginTop: 2 }}>
            {fmtTimeShort(earliest)}
          </div>
        </div>
        <div style={{ background: C.bg, borderRadius: 8, padding: "10px 12px" }}>
          <div style={{ fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase", color: C.muted, fontWeight: 500 }}>
            {etaUpdate ? "Updated ETA" : "Latest back"}
          </div>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, fontWeight: 500, marginTop: 2, color: etaUpdate ? C.accent : C.ink }}>
            {fmtTimeShort(effectiveReturn)}
          </div>
        </div>
      </div>

      <div style={{ fontSize: 12, color: C.ink, padding: "10px 12px", background: `${homeColor}15`, borderRadius: 8, marginBottom: 12 }}>
        <span style={{ fontWeight: 600, color: homeColor }}>{homeParent}</span> is covering all shifts until you're back. Tap below to update your ETA or mark yourself home.
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <button onClick={onUpdateEta} style={{
          background: "transparent", color: C.ink, border: `1.5px solid ${C.line}33`,
          borderRadius: 8, padding: "10px", fontSize: 13, fontWeight: 500, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <Edit3 size={13} /> Update ETA
        </button>
        <button onClick={onArrived} style={{
          background: C.accent, color: "#fff", border: "none",
          borderRadius: 8, padding: "10px", fontSize: 13, fontWeight: 600, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <Check size={13} /> I'm home
        </button>
      </div>
    </div>
  );
}

// ---- SleepDownPickerModal ---------------------------------------------
// When the parent confirms the baby fell asleep (after a "still awake?"
// prompt), this lets them specify the actual sleep-down time. Pre-filled
// with the system's midpoint estimate, but if the parent remembers — say
// — that she dozed off 20 min ago, they can adjust.
//
// Behavior:
//   • Default selection = "Use estimate" (one-tap path stays fast)
//   • "I know when" reveals a datetime-local input
//   • Bound to range [last feed, now] — can't pick the future or before
//     the last feed since that would be nonsensical
//   • The `estimated` flag on the resulting event is true ONLY when the
//     user accepts the system estimate. If they specify a time, we trust
//     them and mark estimated:false.
function SleepDownPickerModal({ C, prefill, now, onClose, onSubmit }) {
  const [mode, setMode] = useState("estimate"); // "estimate" | "exact"
  // datetime-local format: YYYY-MM-DDTHH:MM (local time, no seconds, no TZ)
  const toLocalIso = (d) => {
    const pad = (n) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  };
  const [exactTime, setExactTime] = useState(toLocalIso(prefill));

  const submit = () => {
    if (mode === "estimate") {
      onSubmit(prefill, true);
    } else {
      const ts = new Date(exactTime);
      if (isNaN(ts.getTime())) return;
      // Clamp: don't allow future, or earlier than 8h ago (sanity bound).
      const eightHoursAgo = new Date(now.getTime() - 8 * 3600 * 1000);
      if (ts > now) return onSubmit(now, false);
      if (ts < eightHoursAgo) return onSubmit(eightHoursAgo, false);
      onSubmit(ts, false);
    }
  };

  const fmtPretty = (d) =>
    d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  const minsAgo = Math.round((now - prefill) / 60000);

  return (
    <ModalShell C={C} onClose={onClose} title="When did she fall asleep?">
      <div style={{
        background: `${C.gold}10`,
        border: `1px solid ${C.gold}30`,
        borderRadius: 10, padding: "10px 12px", marginBottom: 14,
        fontSize: 12, color: C.muted, lineHeight: 1.5,
      }}>
        Based on the last feed, she likely went down around{" "}
        <strong style={{ color: C.ink }}>{fmtPretty(prefill)}</strong>{" "}
        ({minsAgo} min ago). If you remember the actual time, you can enter it below.
      </div>

      {/* Mode toggle */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
        <button onClick={() => setMode("estimate")} style={{
          padding: "12px 10px", borderRadius: 10,
          background: mode === "estimate" ? C.accent : "transparent",
          color: mode === "estimate" ? "#fff" : C.ink,
          border: `1.5px solid ${mode === "estimate" ? C.accent : C.line + "40"}`,
          fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit",
          display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
        }}>
          <span style={{ fontSize: 9, letterSpacing: "0.16em", opacity: 0.85 }}>USE ESTIMATE</span>
          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 14 }}>
            {fmtPretty(prefill)}
          </span>
        </button>
        <button onClick={() => setMode("exact")} style={{
          padding: "12px 10px", borderRadius: 10,
          background: mode === "exact" ? C.accent : "transparent",
          color: mode === "exact" ? "#fff" : C.ink,
          border: `1.5px solid ${mode === "exact" ? C.accent : C.line + "40"}`,
          fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit",
          display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
        }}>
          <span style={{ fontSize: 9, letterSpacing: "0.16em", opacity: 0.85 }}>I KNOW WHEN</span>
          <span style={{ fontSize: 12 }}>specify time</span>
        </button>
      </div>

      {/* Exact time input — shown only when mode = "exact" */}
      {mode === "exact" && (
        <div style={{ marginBottom: 14 }}>
          <label style={{
            display: "block", fontSize: 11, color: C.muted,
            marginBottom: 6, letterSpacing: "0.08em", textTransform: "uppercase",
          }}>
            She fell asleep at
          </label>
          <input
            type="datetime-local"
            value={exactTime}
            onChange={e => setExactTime(e.target.value)}
            max={toLocalIso(now)}
            style={{
              width: "100%",
              padding: "10px 12px",
              borderRadius: 10,
              border: `1px solid ${C.line}40`,
              background: C.bg,
              color: C.ink,
              fontSize: 14,
              fontFamily: "'JetBrains Mono', monospace",
            }}
          />
          <div style={{ fontSize: 10, color: C.muted, marginTop: 4, fontStyle: "italic" }}>
            Use 24h format. Can't pick a future time.
          </div>
        </div>
      )}

      <SubmitButton C={C} onClick={submit}>
        Log sleep-down
      </SubmitButton>
    </ModalShell>
  );
}

function OnsiteModal({ C, onClose, onSubmit }) {
  const [parent, setParent] = useState("Mommy");
  const nowIso = () => {
    const d = new Date();
    return d.toISOString().slice(0, 16);
  };
  const plusHours = (h) => {
    const d = new Date();
    d.setHours(d.getHours() + h);
    return d.toISOString().slice(0, 16);
  };
  const [departedAt, setDepartedAt] = useState(nowIso());
  const [earliestReturn, setEarliestReturn] = useState(plusHours(3));
  const [latestReturn, setLatestReturn] = useState(plusHours(8));

  return (
    <ModalShell C={C} onClose={onClose} title="Going on-site">
      <Field C={C} label="Who's leaving?">
        <SegControl C={C} value={parent} onChange={setParent} options={[
          { v: "Mommy", l: "Mommy", color: C.mommy },
          { v: "Daddy", l: "Daddy", color: C.daddy },
        ]} />
      </Field>
      <Field C={C} label="Departure time">
        <DateTimeInput C={C} value={departedAt} onChange={setDepartedAt} />
      </Field>
      <Field C={C} label="Earliest plausible return">
        <DateTimeInput C={C} value={earliestReturn} onChange={setEarliestReturn} />
      </Field>
      <Field C={C} label="Latest plausible return">
        <DateTimeInput C={C} value={latestReturn} onChange={setLatestReturn} />
      </Field>
      <div style={{ background: `${C.line}08`, borderRadius: 10, padding: 12, fontSize: 12, color: C.muted, marginBottom: 8, lineHeight: 1.5 }}>
        Your partner will cover all your shifts in this window. You can tap "Update ETA" anytime when you have a clearer estimate, or "I'm home" when you arrive.
      </div>
      <SubmitButton C={C} onClick={() => onSubmit({
        parent,
        departedAt: new Date(departedAt).toISOString(),
        earliestReturn: new Date(earliestReturn).toISOString(),
        latestReturn: new Date(latestReturn).toISOString(),
      })}>
        Activate on-site mode
      </SubmitButton>
    </ModalShell>
  );
}

function EtaUpdateModal({ C, onsite, onClose, onSubmit }) {
  const fmtIso = (d) => new Date(d).toISOString().slice(0, 16);
  const plusMin = (m) => fmtIso(new Date(Date.now() + m * 60000));
  const [eta, setEta] = useState(onsite.etaUpdate ? fmtIso(onsite.etaUpdate) : plusMin(60));

  const quickSet = (mins) => setEta(plusMin(mins));

  return (
    <ModalShell C={C} onClose={onClose} title="Update ETA home">
      <Field C={C} label="Quick options">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 6 }}>
          {[
            { mins: 15, label: "15 min" },
            { mins: 30, label: "30 min" },
            { mins: 45, label: "45 min" },
            { mins: 60, label: "1 hour" },
            { mins: 90, label: "1.5 hr" },
            { mins: 120, label: "2 hours" },
          ].map(opt => (
            <button key={opt.mins} onClick={() => quickSet(opt.mins)} style={{
              background: C.bg, color: C.ink,
              border: `1px solid ${C.line}22`, borderRadius: 8,
              padding: "10px 6px", fontSize: 13, fontWeight: 500, cursor: "pointer",
            }}>
              {opt.label}
            </button>
          ))}
        </div>
      </Field>
      <Field C={C} label="Or pick exactly">
        <DateTimeInput C={C} value={eta} onChange={setEta} />
      </Field>
      <SubmitButton C={C} onClick={() => onSubmit(new Date(eta).toISOString())}>
        Update ETA to {fmtTimeShort(new Date(eta))}
      </SubmitButton>
    </ModalShell>
  );
}

// ---- SwipeableRow ------------------------------------------------------
// Reusable wrapper that lets users swipe-left on a list item to reveal
// action buttons (typically Edit + Delete). Distinguishes horizontal swipe
// from vertical scroll by requiring dx > dy * 1.5 before locking to swipe
// gesture. Snaps back if released before 60px threshold. Tap-anywhere-else
// (on the page) closes any open swipe.
//
// Usage:
//   <SwipeableRow C={C} actions={[
//     { label: "Edit", icon: <Edit3 size={14} />, color: "#888", onClick: () => ... },
//     { label: "Delete", icon: <Trash2 size={14} />, color: "#C44545", onClick: () => ... },
//   ]}>
//     <YourRowContent />
//   </SwipeableRow>
//
// Props:
//   actions: array of { label, icon, color, onClick }
//   children: the row content
//   C: theme palette
//
// v05.05bt17.
function SwipeableRow({ C, actions, children, rowKey }) {
  const [dragX, setDragX] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [snapped, setSnapped] = useState(false); // is the row currently held open?
  const startX = useRef(0);
  const startY = useRef(0);
  const didLockToSwipe = useRef(false);
  const containerRef = useRef(null);

  const ACTION_WIDTH = 64; // px per action button
  const totalActionWidth = actions.length * ACTION_WIDTH;
  const SNAP_THRESHOLD = ACTION_WIDTH; // half-way through one action width

  // Close on outside click
  useEffect(() => {
    if (!snapped) return;
    const handler = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setSnapped(false);
        setDragX(0);
      }
    };
    document.addEventListener("click", handler);
    return () => document.removeEventListener("click", handler);
  }, [snapped]);

  const onPointerDown = (clientX, clientY) => {
    startX.current = clientX;
    startY.current = clientY;
    didLockToSwipe.current = false;
    setIsDragging(true);
  };

  const onPointerMove = (clientX, clientY, e) => {
    if (!isDragging) return;
    const dx = clientX - startX.current;
    const dy = clientY - startY.current;
    // First few pixels — decide whether this is a horizontal swipe or
    // vertical scroll. Once locked, we ignore vertical movement.
    if (!didLockToSwipe.current) {
      if (Math.abs(dx) > 8 || Math.abs(dy) > 8) {
        if (Math.abs(dx) > Math.abs(dy) * 1.5) {
          didLockToSwipe.current = true;
        } else {
          // Vertical scroll wins — release and don't drag
          setIsDragging(false);
          return;
        }
      } else {
        return;
      }
    }
    // Only swipes to the left reveal actions. Right swipes either close a
    // snapped row or do nothing.
    let nextDragX;
    if (snapped) {
      // Starting from open position: dx is delta from open
      nextDragX = Math.min(0, -totalActionWidth + dx);
    } else {
      nextDragX = Math.min(0, dx);
    }
    // Resist over-drag past full open
    if (nextDragX < -totalActionWidth - 20) {
      nextDragX = -totalActionWidth - 20 + (nextDragX + totalActionWidth + 20) * 0.2;
    }
    setDragX(nextDragX);
    if (e && e.preventDefault && didLockToSwipe.current) e.preventDefault();
  };

  const onPointerUp = () => {
    if (!isDragging) return;
    setIsDragging(false);
    // Snap to nearest stable state
    if (dragX < -SNAP_THRESHOLD) {
      setDragX(-totalActionWidth);
      setSnapped(true);
    } else {
      setDragX(0);
      setSnapped(false);
    }
  };

  // Touch handlers
  const onTouchStart = (e) => {
    onPointerDown(e.touches[0].clientX, e.touches[0].clientY);
  };
  const onTouchMove = (e) => {
    if (didLockToSwipe.current && e.cancelable) e.preventDefault();
    onPointerMove(e.touches[0].clientX, e.touches[0].clientY, e);
  };
  const onTouchEnd = () => onPointerUp();

  // Mouse handlers — useful for desktop demoing
  const onMouseDown = (e) => onPointerDown(e.clientX, e.clientY);
  const onMouseMove = (e) => isDragging && onPointerMove(e.clientX, e.clientY, e);
  const onMouseUp = () => onPointerUp();
  // Mouse needs document-level listeners since the cursor can leave the row
  useEffect(() => {
    if (!isDragging) return;
    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);
    return () => {
      document.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseup", onMouseUp);
    };
  });

  return (
    <div ref={containerRef} style={{
      position: "relative", overflow: "hidden", borderRadius: 10,
    }}>
      {/* Action buttons — sit BEHIND the content, revealed when content slides left */}
      <div style={{
        position: "absolute", top: 0, right: 0, bottom: 0,
        display: "flex",
      }}>
        {actions.map((action, i) => (
          <button
            key={i}
            onClick={(e) => {
              e.stopPropagation();
              action.onClick();
              setDragX(0);
              setSnapped(false);
            }}
            style={{
              width: ACTION_WIDTH,
              background: action.color || C.muted,
              color: "#fff",
              border: "none",
              cursor: "pointer",
              display: "flex", flexDirection: "column",
              alignItems: "center", justifyContent: "center",
              gap: 3,
              fontFamily: "inherit", fontSize: 10, fontWeight: 600,
              letterSpacing: "0.04em",
            }}>
            {action.icon}
            <span>{action.label}</span>
          </button>
        ))}
      </div>
      {/* Content — slides left to reveal actions */}
      <div
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onMouseDown={onMouseDown}
        style={{
          transform: `translateX(${dragX}px)`,
          transition: isDragging ? "none" : "transform 0.2s ease-out",
          background: C.paper,
          touchAction: "pan-y",
        }}>
        {children}
      </div>
    </div>
  );
}

function MeetingRow({ m, C, onRemove, onEdit }) {
  const colors = {
    red: { bg: "#C44545", fg: "#fff", label: "RED" },
    yellow: { bg: C.gold, fg: "#1F1B16", label: "YELLOW" },
    green: { bg: "#5C8E5C", fg: "#fff", label: "GREEN" },
  }[m.level];
  const start = new Date(m.start);
  const end = new Date(m.end);
  const parentColor = m.parent === "Mommy" ? C.mommy : C.daddy;

  // v05.05bt17: swipe-left to reveal Edit + Delete buttons. Tap on body
  // still opens edit modal. The old 2-step confirm trash button is gone
  // since the swipe gesture itself is intentional.
  const actions = [];
  if (onEdit) {
    actions.push({
      label: "Edit",
      icon: <Edit3 size={14} />,
      color: C.muted,
      onClick: onEdit,
    });
  }
  actions.push({
    label: "Delete",
    icon: <Trash2 size={14} />,
    color: "#C44545",
    onClick: onRemove,
  });

  return (
    <SwipeableRow C={C} actions={actions} rowKey={m.id}>
      <div style={{
        background: C.paper,
        border: `1px solid ${C.line}15`,
        borderRadius: 10,
        display: "flex", alignItems: "center", gap: 10,
      }}>
        <div style={{ width: 4, alignSelf: "stretch", borderRadius: 2, background: colors.bg, marginLeft: 12 }} />
        {/* Tappable body — clicks open edit modal */}
        <button
          onClick={onEdit}
          disabled={!onEdit}
          style={{
            flex: 1, minWidth: 0, textAlign: "left",
            background: "transparent", border: "none",
            padding: "10px 0", cursor: onEdit ? "pointer" : "default",
            fontFamily: "inherit", color: "inherit",
          }}>
          <div style={{ fontSize: 14, fontWeight: 500 }}>{m.label || "(untitled)"}</div>
          <div style={{ fontSize: 11, color: C.muted, fontFamily: "'JetBrains Mono', monospace", marginTop: 2 }}>
            <span style={{ color: parentColor, fontWeight: 600 }}>{m.parent}</span>
            {" · "}{fmtTimeShort(start)}–{fmtTimeShort(end)}
          </div>
        </button>
        <span style={{
          fontSize: 9, fontWeight: 700, letterSpacing: "0.1em",
          background: colors.bg, color: colors.fg,
          padding: "3px 6px", borderRadius: 4,
        }}>
          {colors.label}
        </span>
        {/* v05.05bt29: visible inline edit + delete buttons as fallback
            for users who don't discover the swipe gesture. The swipe and
            the body tap still work as before; these are just an
            always-visible alternative. */}
        {onEdit && (
          <button
            onClick={(e) => { e.stopPropagation(); onEdit(); }}
            aria-label="Edit"
            style={{
              background: "transparent", border: "none", color: C.muted,
              cursor: "pointer", padding: "8px 4px", opacity: 0.6,
              display: "flex", alignItems: "center",
            }}>
            <Edit3 size={13} />
          </button>
        )}
        {onRemove && (
          <button
            onClick={(e) => { e.stopPropagation(); onRemove(); }}
            aria-label="Delete"
            style={{
              background: "transparent", border: "none", color: C.muted,
              cursor: "pointer", padding: "8px 12px 8px 4px", opacity: 0.6,
              display: "flex", alignItems: "center",
            }}>
            <Trash2 size={13} />
          </button>
        )}
      </div>
    </SwipeableRow>
  );
}

// Thin wrapper around InlineCommitmentForm so the Shifts tab "Add commitment"
